const lessons = [
{num:1,time:"00:00:59,000 --> 00:01:02,399",arabic:"أَكَادُ لَا أُصَدِّقُ أَنَّنِي أَرَاكَ ثَانِيَةً يَا وَلَدِي.",segs:[{ar:"أَكَادُ لَا أُصَدِّقُ",uz:"deyarli ishona olmayapman"},{ar:"أَنَّنِي أَرَاكَ ثَانِيَةً",uz:"sizni yana ko‘rayotganimga"},{ar:"يَا وَلَدِي",uz:"ey bolam"}],full_uz:"Sizni yana ko‘rayotganimga deyarli ishona olmayapman, bolam.",note:"كَادَ + muzoriy fe’l ish-harakat sodir bo‘lishiga yaqin qolganini bildiradi. أَكَادُ لَا أُصَدِّقُ — «deyarli ishona olmayapman»."},
{num:2,time:"00:01:02,399 --> 00:01:06,719",arabic:"وَأَنَا رَكِبْتُ جَنَاحَيْ نَعَامَةٍ لِأَطْوِيَ الْمَسَافَاتِ لِأَصِلَ إِلَيْكِ يَا أُمَّاهُ.",segs:[{ar:"وَأَنَا رَكِبْتُ",uz:"men esa mindim"},{ar:"جَنَاحَيْ نَعَامَةٍ",uz:"tuyaqushning ikki qanotiga"},{ar:"لِأَطْوِيَ الْمَسَافَاتِ",uz:"masofalarni bosib o‘tish uchun"},{ar:"لِأَصِلَ إِلَيْكِ",uz:"sizning oldingizga yetib kelish uchun"},{ar:"يَا أُمَّاهُ",uz:"ey onajon"}],full_uz:"Men esa masofalarni bosib o‘tib, oldingizga yetib kelish uchun tuyaqushning ikki qanotiga mindim, onajon.",note:"طَوَى الْمَسَافَاتِ — «masofalarni bosib o‘tdi». جَنَاحَيْ — ikkilikning nasb shakli; izofada oxiridagi ن tushadi."},
{num:3,time:"00:01:06,719 --> 00:01:08,799",arabic:"حَفِظَكَ اللَّهُ وَأَطَالَ عُمْرَكَ.",segs:[{ar:"حَفِظَكَ اللَّهُ",uz:"Alloh sizni asrasin"},{ar:"وَأَطَالَ عُمْرَكَ",uz:"va umringizni uzoq qilsin"}],full_uz:"Alloh sizni asrasin va umringizni uzoq qilsin.",note:"O‘tgan zamon shaklidagi fe’llar duo ma’nosida ham keladi: حَفِظَكَ اللَّهُ — «Alloh sizni asrasin»."},
{num:4,time:"00:01:08,799 --> 00:01:11,159",arabic:"إِنَّ الْبَيْتَ مُوحِشٌ مِنْ دُونِكَ يَا وَلَدِي.",segs:[{ar:"إِنَّ الْبَيْتَ مُوحِشٌ",uz:"uy huvillab qolgan"},{ar:"مِنْ دُونِكَ",uz:"sizsiz"},{ar:"يَا وَلَدِي",uz:"ey bolam"}],full_uz:"Sizsiz uy huvillab qolgan, bolam.",note:"مِنْ دُونِكَ — «sizsiz». مُوحِشٌ yolg‘izlik yoki vahima hissini uyg‘otadigan joyni ifodalaydi."},
{num:5,time:"00:01:11,159 --> 00:01:16,260",arabic:"حَتَّى كُنْتُ أَشْعُرُ أَنَّ جُدْرَانَهُ سَتُطْبِقُ عَلَى رُوحِي فِي غِيَابِكَ.",segs:[{ar:"حَتَّى كُنْتُ أَشْعُرُ",uz:"hatto his qilardim"},{ar:"أَنَّ جُدْرَانَهُ",uz:"uning devorlari"},{ar:"سَتُطْبِقُ عَلَى رُوحِي",uz:"ruhimni siqib qo‘yadigandek"},{ar:"فِي غِيَابِكَ",uz:"siz yo‘qligingizda"}],full_uz:"Hatto siz yo‘qligingizda uning devorlari ruhimni siqib qo‘yadigandek his qilardim.",note:"كَانَ + muzoriy o‘tmishdagi davomiy yoki takroriy holatni bildiradi. أَطْبَقَ عَلَى — «ustidan yopildi, siqib oldi»."},
{num:6,time:"00:01:16,260 --> 00:01:19,039",arabic:"لَا حَرَمَنِيَ اللَّهُ مِنْكَ يَا أَحْمَدُ.",segs:[{ar:"لَا حَرَمَنِيَ اللَّهُ مِنْكَ",uz:"Alloh meni sizdan ayirmasin"},{ar:"يَا أَحْمَدُ",uz:"ey Ahmad"}],full_uz:"Alloh meni sizdan ayirmasin, Ahmad.",note:"لَا + o‘tgan zamon fe’li bu yerda salbiy duo-istakni bildiradi: «ayirmasin»."},
{num:7,time:"00:01:19,039 --> 00:01:21,200",arabic:"سَلَّمَكِ اللَّهُ يَا أُمَّاهُ.",segs:[{ar:"سَلَّمَكِ اللَّهُ",uz:"Alloh sizni salomat saqlasin"},{ar:"يَا أُمَّاهُ",uz:"ey onajon"}],full_uz:"Alloh sizni salomat saqlasin, onajon.",note:"ـكِ ayol kishiga murojaatni bildiradi; erkakka murojaatda ـكَ bo‘ladi."},
{num:8,time:"00:01:21,200 --> 00:01:24,700",arabic:"وَأَنَا وَاللَّهِ لَمْ يُفَارِقْنِي طَيْفُكِ لَحْظَةً مِنْ لَيْلٍ أَوْ نَهَارٍ.",segs:[{ar:"وَأَنَا وَاللَّهِ",uz:"men esa, Allohga qasam"},{ar:"لَمْ يُفَارِقْنِي طَيْفُكِ",uz:"sizning xayolingiz meni tark etmadi"},{ar:"لَحْظَةً",uz:"bir lahza ham"},{ar:"مِنْ لَيْلٍ أَوْ نَهَارٍ",uz:"kechasi ham, kunduzi ham"}],full_uz:"Allohga qasam, sizning xayolingiz meni kechasi ham, kunduzi ham bir lahza tark etmadi.",note:"لَمْ muzoriy fe’lni jazm qilib, o‘tgan zamondagi inkorni bildiradi: لَمْ يُفَارِقْنِي — «meni tark etmadi»."},
{num:9,time:"00:01:24,700 --> 00:01:26,980",arabic:"كُنْتِ حَاضِرَةً مَعِي فِي كُلِّ خَطَرٍ.",segs:[{ar:"كُنْتِ حَاضِرَةً مَعِي",uz:"siz men bilan birga edingiz"},{ar:"فِي كُلِّ خَطَرٍ",uz:"har bir xavfda"}],full_uz:"Har bir xavfda siz men bilan birga edingiz.",note:"كُنْتِ — ayol kishiga «siz edingiz». حَاضِرَةً — كَانَning xabari bo‘lgani uchun mansub."},
{num:10,time:"00:01:26,980 --> 00:01:29,219",arabic:"هَاتِ، أَخْبِرْنِي مَا عِنْدَكَ يَا أَحْمَدُ.",segs:[{ar:"هَاتِ",uz:"qani"},{ar:"أَخْبِرْنِي مَا عِنْدَكَ",uz:"menga bor gaplaringizni ayting"},{ar:"يَا أَحْمَدُ",uz:"ey Ahmad"}],full_uz:"Qani, Ahmad, menga bor gaplaringizni ayting.",note:"هَاتِ suhbatda «qani, ayting-chi» ma’nosida ham ishlatiladi."},
{num:11,time:"00:01:29,219 --> 00:01:32,780",arabic:"مُنْذُ خُرُوجِكَ مِنْ بَغْدَادَ حَتَّى عَوْدَتِكَ إِلَى أُمِّكَ.",segs:[{ar:"مُنْذُ خُرُوجِكَ",uz:"chiqib ketganingizdan boshlab"},{ar:"مِنْ بَغْدَادَ",uz:"Bag‘doddan"},{ar:"حَتَّى عَوْدَتِكَ",uz:"qaytganingizgacha"},{ar:"إِلَى أُمِّكَ",uz:"onangizning oldiga"}],full_uz:"Bag‘doddan chiqib ketganingizdan onangizning oldiga qaytganingizgacha.",note:"مُنْذُ ... حَتَّى ... — «...dan boshlab ...gacha». خُرُوجٌ va عَوْدَةٌ — harakat nomlari."},
{num:12,time:"00:01:50,300 --> 00:01:52,280",arabic:"السَّلَامُ عَلَيْكُمْ يَا أَخِي.",segs:[{ar:"السَّلَامُ عَلَيْكُمْ",uz:"assalomu alaykum"},{ar:"يَا أَخِي",uz:"ey birodarim"}],full_uz:"Assalomu alaykum, birodarim.",note:null},
{num:13,time:"00:01:52,280 --> 00:01:54,280",arabic:"وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ.",segs:[{ar:"وَعَلَيْكُمُ السَّلَامُ",uz:"sizga ham tinchlik bo‘lsin"},{ar:"وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ",uz:"va Allohning rahmati hamda barakalari"}],full_uz:"Sizga ham tinchlik, Allohning rahmati va barakalari bo‘lsin.",note:null},
{num:14,time:"00:01:54,280 --> 00:01:58,180",arabic:"أَنَا أَخُوكَ فِي اللَّهِ أُسَامَةُ الْبَكْرِيُّ.",segs:[{ar:"أَنَا أَخُوكَ فِي اللَّهِ",uz:"men sizning Alloh yo‘lidagi birodaringizman"},{ar:"أُسَامَةُ الْبَكْرِيُّ",uz:"Usoma Bakriy"}],full_uz:"Men sizning Alloh yo‘lidagi birodaringiz Usoma Bakriyman.",note:"أَخٌ so‘zi bu yerda nasabdagi aka-uka emas, diniy birodarlik ma’nosida."},
{num:15,time:"00:01:58,180 --> 00:02:06,439",arabic:"لَعَلَّ أَبَاكِ بَحَثَ عَنْكِ كَثِيرًا أَيْضًا وَلَمَّا يَجِدْكِ.",segs:[{ar:"لَعَلَّ أَبَاكِ",uz:"ehtimol, otangiz"},{ar:"بَحَثَ عَنْكِ كَثِيرًا أَيْضًا",uz:"sizni ham ko‘p qidirgandir"},{ar:"وَلَمَّا يَجِدْكِ",uz:"va hali sizni topmagandir"}],full_uz:"Ehtimol, otangiz ham sizni ko‘p qidirgan, lekin hali topmagandir.",note:"لَمَّا + muzoriy — «hali ...madi». لَعَلَّ dan keyin أَبٌ mansub bo‘lib, أَبَاكِ shaklida kelgan."},
{num:16,time:"00:02:06,439 --> 00:02:08,580",arabic:"وَأَنَا أَيْضًا يَا مَرْوَانُ.",segs:[{ar:"وَأَنَا أَيْضًا",uz:"men ham"},{ar:"يَا مَرْوَانُ",uz:"ey Marvon"}],full_uz:"Men ham, Marvon.",note:null},
{num:17,time:"00:02:08,580 --> 00:02:12,860",arabic:"أَمْضَيْتُ أَيَّامًا أَبْحَثُ عَنْهُ مَعَ خَالِدٍ، جَزَاهُ اللَّهُ خَيْرًا.",segs:[{ar:"أَمْضَيْتُ أَيَّامًا",uz:"kunlar o‘tkazdim"},{ar:"أَبْحَثُ عَنْهُ",uz:"uni qidirib"},{ar:"مَعَ خَالِدٍ",uz:"Xolid bilan"},{ar:"جَزَاهُ اللَّهُ خَيْرًا",uz:"Alloh uni yaxshilik bilan mukofotlasin"}],full_uz:"Xolid bilan uni qidirib kunlar o‘tkazdim. Alloh uni yaxshilik bilan mukofotlasin.",note:"أَمْضَى vaqt bilan kelganda «vaqt o‘tkazdi» degani. أَبْحَثُ عَنْهُ bu vaqt qanday o‘tganini bildiradi."},
{num:18,time:"00:02:12,860 --> 00:02:14,420",arabic:"وَلَمْ نَقَعْ لَهُ عَلَى أَثَرٍ.",segs:[{ar:"وَلَمْ نَقَعْ",uz:"va duch kelmadik"},{ar:"لَهُ عَلَى أَثَرٍ",uz:"uning biror iziga"}],full_uz:"Ammo uning biror izini topmadik.",note:"وَقَعَ عَلَى أَثَرٍ — «iz topdi, izga duch keldi»."},
{num:19,time:"00:02:14,420 --> 00:02:16,659",arabic:"يَفْعَلُ اللَّهُ مَا يَشَاءُ يَا شَهْنَازُ.",segs:[{ar:"يَفْعَلُ اللَّهُ مَا يَشَاءُ",uz:"Alloh xohlaganini qiladi"},{ar:"يَا شَهْنَازُ",uz:"ey Shahnoz"}],full_uz:"Alloh xohlaganini qiladi, Shahnoz.",note:null},
{num:20,time:"00:02:17,920 --> 00:02:22,740",arabic:"مَا زِلْتُ أَذْكُرُ آخِرَ لِقَاءٍ بَيْنَنَا وَكَأَنَّهُ السَّاعَةَ.",segs:[{ar:"مَا زِلْتُ أَذْكُرُ",uz:"hali ham eslayman"},{ar:"آخِرَ لِقَاءٍ بَيْنَنَا",uz:"oramizdagi oxirgi uchrashuvni"},{ar:"وَكَأَنَّهُ السَّاعَةَ",uz:"go‘yo hozir bo‘lgandek"}],full_uz:"Oxirgi uchrashuvimizni hali ham xuddi hozir bo‘lgandek eslayman.",note:"مَا زَالَ — davom etayotgan holat: «hali ham». السَّاعَةَ bu yerda «hozir, shu dam» degani."},
{num:21,time:"00:02:22,740 --> 00:02:25,400",arabic:"كَانَ عِنْدَ دُكَّانِ التَّاجِرِ.",segs:[{ar:"كَانَ",uz:"bo‘lgan edi"},{ar:"عِنْدَ دُكَّانِ التَّاجِرِ",uz:"savdogarning do‘koni yonida"}],full_uz:"Bu savdogarning do‘koni yonida bo‘lgan edi.",note:null},
{num:22,time:"00:02:25,400 --> 00:02:26,960",arabic:"وَبَعْدَهَا افْتَرَقْنَا.",segs:null,full_uz:"Shundan keyin bir-birimizdan ayrildik.",note:null},
{num:23,time:"00:02:26,960 --> 00:02:28,420",arabic:"كَيْفَ؟ لَا أَدْرِي.",segs:[{ar:"كَيْفَ؟",uz:"qanday qilib?"},{ar:"لَا أَدْرِي",uz:"bilmayman"}],full_uz:"Qanday qilib? Bilmayman.",note:null},
{num:24,time:"00:02:28,420 --> 00:02:32,719",arabic:"هَلْ قُلْتِ: عِنْدَ دُكَّانِ التَّاجِرِ؟",segs:[{ar:"هَلْ قُلْتِ",uz:"siz dedingizmi"},{ar:"عِنْدَ دُكَّانِ التَّاجِرِ؟",uz:"savdogarning do‘koni yonida deb?"}],full_uz:"Savdogarning do‘koni yonida dedingizmi?",note:"قُلْتِ — ayol kishiga «siz aytdingiz»; قُلْتَ — erkak kishiga."},
{num:25,time:"00:02:33,080 --> 00:02:36,260",arabic:"تَاجِرٌ فِي بَغْدَادَ.",segs:null,full_uz:"Bag‘doddagi bir savdogar.",note:null},
{num:26,time:"00:02:36,260 --> 00:02:38,719",arabic:"كَانَ أَبِي يَبِيعُ لَهُ أَمْشَاطَ الْفِضَّةِ.",segs:[{ar:"كَانَ أَبِي يَبِيعُ لَهُ",uz:"otam unga sotardi"},{ar:"أَمْشَاطَ الْفِضَّةِ",uz:"kumush taroqlarni"}],full_uz:"Otam unga kumush taroqlar sotardi.",note:"أَمْشَاطٌ — مِشْطٌ («taroq») so‘zining ko‘pligi. كَانَ يَبِيعُ — «sotardi»."},
{num:27,time:"00:02:39,520 --> 00:02:48,939",arabic:"لَمْ أَجِدْ مَلْجَأً غَيْرَكَ يَا أَخِي.",segs:[{ar:"لَمْ أَجِدْ مَلْجَأً غَيْرَكَ",uz:"sizdan boshqa panoh topmadim"},{ar:"يَا أَخِي",uz:"ey birodarim"}],full_uz:"Sizdan boshqa panoh topmadim, birodarim.",note:"مَلْجَأٌ — «panoh, boshpana»; ko‘chma ma’noda yordam so‘rab murojaat qilinadigan kishi."},
{num:28,time:"00:02:48,939 --> 00:02:50,900",arabic:"فَأَنْتَ وَحْدَكَ مَنْ يَسْتَطِيعُ مُسَاعَدَتِي.",segs:[{ar:"فَأَنْتَ وَحْدَكَ",uz:"chunki faqat siz"},{ar:"مَنْ يَسْتَطِيعُ مُسَاعَدَتِي",uz:"menga yordam bera oladigan kishisiz"}],full_uz:"Chunki menga faqat siz yordam bera olasiz.",note:"وَحْدَكَ — «yolg‘iz o‘zingiz, faqat siz». مُسَاعَدَتِي — «menga yordam berish»."},
{num:29,time:"00:02:50,900 --> 00:02:53,020",arabic:"وَمَنْ قَالَ لَكَ إِنَّنِي...",segs:[{ar:"وَمَنْ قَالَ لَكَ",uz:"sizga kim aytdi"},{ar:"إِنَّنِي...",uz:"men ... ekanimni"}],full_uz:"Sizga kim aytdi, men...",note:null},
{num:30,time:"00:02:53,020 --> 00:02:54,860",arabic:"رَأَيْتُكَ مَرَّةً مَعَ الشَّيْخِ الْمَرِيسِيِّ.",segs:[{ar:"رَأَيْتُكَ مَرَّةً",uz:"sizni bir marta ko‘rganman"},{ar:"مَعَ الشَّيْخِ الْمَرِيسِيِّ",uz:"shayx Marisiy bilan"}],full_uz:"Sizni bir marta shayx Marisiy bilan ko‘rganman.",note:null},
{num:31,time:"00:02:54,860 --> 00:02:57,800",arabic:"أَوَتَعْرِفُ الشَّيْخَ؟",segs:null,full_uz:"Shayxni taniysizmi?",note:"So‘z boshidagi أَ so‘roq hamzasi; undan keyingi وَ — bog‘lovchi."},
{num:32,time:"00:02:57,800 --> 00:03:01,280",arabic:"لَيْتَ لِي أَنْ أَزْعُمَ هَذَا، وَلَكِنَّهُ كَالنَّجْمِ يُرَى وَلَا يُطَالُ.",segs:[{ar:"لَيْتَ لِي",uz:"qaniydi menga mumkin bo‘lsa"},{ar:"أَنْ أَزْعُمَ هَذَا",uz:"buni da’vo qilish"},{ar:"وَلَكِنَّهُ كَالنَّجْمِ",uz:"lekin u yulduz kabidir"},{ar:"يُرَى وَلَا يُطَالُ",uz:"ko‘rinadi-yu, unga yetib bo‘lmaydi"}],full_uz:"Qaniydi buni da’vo qila olsam. Lekin u yulduz kabi: ko‘rinadi-yu, unga yetib bo‘lmaydi.",note:"لَيْتَ — «qaniydi». يُرَى va يُطَالُ majhul nisbatda: «ko‘riladi» va «unga yetiladi»."},
{num:33,time:"00:03:01,280 --> 00:03:07,020",arabic:"بِمَ أَسْتَطِيعُ أَنْ أَخْدُمَكَ يَا أُسَامَةُ؟",segs:[{ar:"بِمَ أَسْتَطِيعُ أَنْ أَخْدُمَكَ",uz:"sizga qanday xizmat qila olaman"},{ar:"يَا أُسَامَةُ؟",uz:"ey Usoma?"}],full_uz:"Sizga qanday xizmat qila olaman, Usoma?",note:"بِمَ = بِ + مَا. So‘roq مَا oldidan jar harfi kelsa, uning alifi tushadi."},
{num:34,time:"00:03:07,020 --> 00:03:09,500",arabic:"أُرِيدُكَ أَنْ تُقَدِّمَنِي إِلَى الشَّيْخِ الْمَرِيسِيِّ لَا غَيْرُ.",segs:[{ar:"أُرِيدُكَ أَنْ تُقَدِّمَنِي",uz:"meni tanishtirishingizni istayman"},{ar:"إِلَى الشَّيْخِ الْمَرِيسِيِّ",uz:"shayx Marisiyga"},{ar:"لَا غَيْرُ",uz:"xolos"}],full_uz:"Meni shayx Marisiyga tanishtirishingizni istayman, xolos.",note:"قَدَّمَ شَخْصًا إِلَى شَخْصٍ — «bir kishini boshqa kishiga tanishtirdi»."},
{num:35,time:"00:03:09,500 --> 00:03:13,020",arabic:"وَلِمَاذَا لَا تُقَدِّمُ لَهُ نَفْسَكَ بِنَفْسِكَ؟",segs:[{ar:"وَلِمَاذَا لَا تُقَدِّمُ لَهُ نَفْسَكَ",uz:"nega unga o‘zingizni tanishtirmaysiz"},{ar:"بِنَفْسِكَ؟",uz:"o‘zingiz?"}],full_uz:"Nega unga o‘zingizni o‘zingiz tanishtirmaysiz?",note:"نَفْسَكَ — «o‘zingizni»; بِنَفْسِكَ — «o‘zingiz, shaxsan»."},
{num:36,time:"00:03:13,620 --> 00:03:17,659",arabic:"الشَّيْخُ أَبُو عَبْدِ الرَّحْمَنِ مُتَوَاضِعٌ وَيَسْتَقْبِلُ أَيَّ قَاصِدٍ، اِذْهَبْ إِلَيْهِ.",segs:[{ar:"الشَّيْخُ أَبُو عَبْدِ الرَّحْمَنِ مُتَوَاضِعٌ",uz:"shayx Abu Abdurahmon kamtar"},{ar:"وَيَسْتَقْبِلُ أَيَّ قَاصِدٍ",uz:"va kelgan har bir kishini qabul qiladi"},{ar:"اِذْهَبْ إِلَيْهِ",uz:"uning oldiga boring"}],full_uz:"Shayx Abu Abdurahmon kamtar, kelgan har bir kishini qabul qiladi. Uning oldiga boring.",note:"قَاصِدٌ — biror maqsad bilan keluvchi kishi. أَيَّ قَاصِدٍ — «har qanday murojaat qiluvchi»."},
{num:37,time:"00:03:17,659 --> 00:03:21,639",arabic:"أُرِيدُ أَنْ أَتَعَرَّفَ إِلَيْهِ مِنْ خِلَالِ مَنْ يَعْرِفُهُ وَيَثِقُ بِهِ الشَّيْخُ.",segs:[{ar:"أُرِيدُ أَنْ أَتَعَرَّفَ إِلَيْهِ",uz:"u bilan tanishmoqchiman"},{ar:"مِنْ خِلَالِ مَنْ يَعْرِفُهُ",uz:"uni taniydigan kishi orqali"},{ar:"وَيَثِقُ بِهِ الشَّيْخُ",uz:"va shayx ishonadigan"}],full_uz:"U bilan uni taniydigan va shayx ishonadigan kishi orqali tanishmoqchiman.",note:"تَعَرَّفَ إِلَى — «bilan tanishdi»; وَثِقَ بِـ — «...ga ishondi»."},
{num:38,time:"00:03:21,639 --> 00:03:23,960",arabic:"حَتَّى يَضُمَّنِي فِي عِدَادِ مُرِيدِيهِ.",segs:[{ar:"حَتَّى يَضُمَّنِي",uz:"meni qo‘shishi uchun"},{ar:"فِي عِدَادِ مُرِيدِيهِ",uz:"o‘z muridlari qatoriga"}],full_uz:"Meni o‘z muridlari qatoriga qo‘shishi uchun.",note:"فِي عِدَادِ — «qatorida, safida». Maqsad bildirgan حَتَّى dan keyin muzoriy mansub keladi."},
{num:39,time:"00:03:23,960 --> 00:03:31,620",arabic:"أَتَعْرِفُ أَنَّ رُفْقَةَ الشَّيْخِ مُخَاطَرَةٌ كَبِيرَةٌ؟",segs:[{ar:"أَتَعْرِفُ",uz:"bilasizmi"},{ar:"أَنَّ رُفْقَةَ الشَّيْخِ",uz:"shayxga hamroh bo‘lish"},{ar:"مُخَاطَرَةٌ كَبِيرَةٌ؟",uz:"katta tavakkal ekanini?"}],full_uz:"Shayxga hamroh bo‘lish katta tavakkal ekanini bilasizmi?",note:"رُفْقَةٌ — «hamrohlik»; مُخَاطَرَةٌ — «o‘zini xavfga qo‘yish, tavakkal»."},
{num:40,time:"00:03:31,620 --> 00:03:32,939",arabic:"أَعْرِفُ.",segs:null,full_uz:"Bilaman.",note:null},
{num:41,time:"00:03:32,939 --> 00:03:36,780",arabic:"وَأَعْرِفُ أَنَّ زَبَانِيَةَ هَارُونَ يَتَلَصَّصُونَ عَلَى الْكَبِيرِ وَالصَّغِيرِ.",segs:[{ar:"وَأَعْرِفُ",uz:"va bilaman"},{ar:"أَنَّ زَبَانِيَةَ هَارُونَ",uz:"Horunning zolim malaylari"},{ar:"يَتَلَصَّصُونَ",uz:"yashirin kuzatayotganini"},{ar:"عَلَى الْكَبِيرِ وَالصَّغِيرِ",uz:"kattani ham, kichikni ham"}],full_uz:"Horunning zolim malaylari kattani ham, kichikni ham yashirin kuzatayotganini bilaman.",note:"تَلَصَّصَ عَلَى — «yashirin kuzatdi, josuslik qildi». زَبَانِيَةٌ bu yerda kamsituvchi ma’noda qo‘llangan."},
{num:42,time:"00:03:36,780 --> 00:03:41,079",arabic:"وَأَنَّهُمْ لَمْ يَعْثُرُوا عَلَى دَلِيلٍ وَاحِدٍ يُدِينُ الشَّيْخَ حَتَّى لَحْظَةِ حَدِيثِنَا هَذَا.",segs:[{ar:"وَأَنَّهُمْ لَمْ يَعْثُرُوا",uz:"va ular topmaganini"},{ar:"عَلَى دَلِيلٍ وَاحِدٍ",uz:"birorta ham dalil"},{ar:"يُدِينُ الشَّيْخَ",uz:"shayxni aybdor qiladigan"},{ar:"حَتَّى لَحْظَةِ حَدِيثِنَا هَذَا",uz:"shu gaplashayotgan paytimizgacha"}],full_uz:"Va shu gaplashayotgan paytimizgacha shayxni aybdor qiladigan birorta ham dalil topmaganlarini bilaman.",note:"عَثَرَ عَلَى — «topdi». لَمْ يَعْثُرُوا da jazm belgisi — oxirgi ن ning tushishi."},
{num:43,time:"00:03:41,079 --> 00:03:47,199",arabic:"وَأَعْرِفُ أَيْضًا أَنَّ حَيَاتِي لَيْسَتْ أَكْثَرَ قِيمَةً مِنْ حَيَاةِ شَيْخِنَا، حَفِظَهُ اللَّهُ.",segs:[{ar:"وَأَعْرِفُ أَيْضًا",uz:"yana bilaman"},{ar:"أَنَّ حَيَاتِي لَيْسَتْ أَكْثَرَ قِيمَةً",uz:"hayotim qadrliroq emasligini"},{ar:"مِنْ حَيَاةِ شَيْخِنَا",uz:"shayximizning hayotidan"},{ar:"حَفِظَهُ اللَّهُ",uz:"Alloh uni asrasin"}],full_uz:"Hayotim shayximizning hayotidan qadrliroq emasligini ham bilaman. Alloh uni asrasin.",note:"أَكْثَرَ قِيمَةً مِنْ — «...dan qadrliroq». قِيمَةً taqqoslash qaysi jihatdan ekanini izohlovchi tamyiz."},
{num:44,time:"00:03:47,199 --> 00:03:52,199",arabic:"لَا أَدْرِي يَا أُسَامَةُ.",segs:[{ar:"لَا أَدْرِي",uz:"bilmayman"},{ar:"يَا أُسَامَةُ",uz:"ey Usoma"}],full_uz:"Bilmayman, Usoma.",note:null},
{num:45,time:"00:03:52,199 --> 00:03:56,619",arabic:"أَرْجُوكَ أَلَّا تَرُدَّنِي خَائِبًا يَا بَدْرُ.",segs:[{ar:"أَرْجُوكَ",uz:"sizdan iltimos qilaman"},{ar:"أَلَّا تَرُدَّنِي خَائِبًا",uz:"meni noumid qaytarmang"},{ar:"يَا بَدْرُ",uz:"ey Badr"}],full_uz:"Iltimos, meni noumid qaytarmang, Badr.",note:"أَلَّا = أَنْ + لَا. خَائِبًا — «umidi puchga chiqqan holda», hol vazifasida."},
{num:46,time:"00:03:56,619 --> 00:04:02,699",arabic:"حَسَنًا، سَأُكَلِّمُ الشَّيْخَ فِي أَمْرِكَ أَوَّلًا، وَعِنْدَهَا سَنَرَى مَا يَكُونُ.",segs:[{ar:"حَسَنًا",uz:"xo‘p"},{ar:"سَأُكَلِّمُ الشَّيْخَ",uz:"shayx bilan gaplashaman"},{ar:"فِي أَمْرِكَ أَوَّلًا",uz:"avval sizning masalangiz haqida"},{ar:"وَعِنْدَهَا سَنَرَى",uz:"shundan keyin ko‘ramiz"},{ar:"مَا يَكُونُ",uz:"nima bo‘lishini"}],full_uz:"Xo‘p, avval shayx bilan sizning masalangiz haqida gaplashaman. Keyin nima bo‘lishini ko‘ramiz.",note:"فِي أَمْرِكَ — «sizning masalangiz haqida». سَنَرَى — رَأَى fe’lining «ko‘ramiz» shakli."},
{num:47,time:"00:04:02,699 --> 00:04:06,019",arabic:"شُكْرًا لَكَ يَا سَيِّدَ بَدْرٍ.",segs:[{ar:"شُكْرًا لَكَ",uz:"sizga rahmat"},{ar:"يَا سَيِّدَ بَدْرٍ",uz:"ey Badr janoblari"}],full_uz:"Sizga rahmat, Badr janoblari.",note:null},
{num:48,time:"00:04:06,019 --> 00:04:08,799",arabic:"لَا بَأْسَ، وَلَكِنْ أَيْنَ سَأَجِدُكَ؟",segs:[{ar:"لَا بَأْسَ",uz:"mayli"},{ar:"وَلَكِنْ أَيْنَ سَأَجِدُكَ؟",uz:"lekin sizni qayerdan topaman?"}],full_uz:"Mayli, lekin sizni qayerdan topaman?",note:null},
{num:49,time:"00:04:08,799 --> 00:04:12,060",arabic:"فَلْنَلْتَقِ عِنْدَ النَّهْرِ عِنْدَ طَرَفِ الْجِسْرِ.",segs:[{ar:"فَلْنَلْتَقِ",uz:"unda uchrashaylik"},{ar:"عِنْدَ النَّهْرِ",uz:"daryo yonida"},{ar:"عِنْدَ طَرَفِ الْجِسْرِ",uz:"ko‘prikning chetida"}],full_uz:"Unda daryo yonida, ko‘prikning chetida uchrashaylik.",note:"لِـ buyruq lomi fe’lni jazm qiladi. نَلْتَقِي → لِنَلْتَقِ: oxirgi ي tushadi."},
{num:50,time:"00:04:12,060 --> 00:04:15,060",arabic:"حَسَنًا، هَذَا مُنَاسِبٌ. إِلَى اللِّقَاءِ يَا أُسَامَةُ.",segs:[{ar:"حَسَنًا، هَذَا مُنَاسِبٌ",uz:"xo‘p, bu qulay"},{ar:"إِلَى اللِّقَاءِ",uz:"ko‘rishguncha"},{ar:"يَا أُسَامَةُ",uz:"ey Usoma"}],full_uz:"Xo‘p, bu qulay. Ko‘rishguncha, Usoma.",note:null},
{num:51,time:"00:04:15,579 --> 00:04:16,500",arabic:"إِلَى اللِّقَاءِ.",segs:null,full_uz:"Ko‘rishguncha.",note:null},
{num:52,time:"00:04:16,500 --> 00:04:38,500",arabic:"مَا لِي أَرَى مَوْلَايَ الرَّشِيدَ عَلَى غَيْرِ سَجِيَّتِهِ الَّتِي أَعْرِفُهُ بِهَا؟",segs:[{ar:"مَا لِي أَرَى",uz:"nega ko‘ryapman"},{ar:"مَوْلَايَ الرَّشِيدَ",uz:"hukmdorim Rashidni"},{ar:"عَلَى غَيْرِ سَجِيَّتِهِ",uz:"odatdagi tabiatidan boshqacha holda"},{ar:"الَّتِي أَعْرِفُهُ بِهَا؟",uz:"men uni tanigan holatidan?"}],full_uz:"Nega hukmdorim Rashidni men bilgan odatdagi holatidan boshqacha ko‘ryapman?",note:"مَا لِي أَرَى...؟ — hayrat bilan «nega men ...ni ko‘ryapman?» degan ifoda. سَجِيَّةٌ — «tabiat, odatiy fe’l-atvor»."},
{num:53,time:"00:04:42,500 --> 00:04:44,500",arabic:"مَا بِكَ يَا مَوْلَايَ؟",segs:[{ar:"مَا بِكَ",uz:"sizga nima bo‘ldi"},{ar:"يَا مَوْلَايَ؟",uz:"ey hukmdorim?"}],full_uz:"Sizga nima bo‘ldi, hukmdorim?",note:null},
{num:54,time:"00:04:44,500 --> 00:04:47,579",arabic:"لِمَاذَا كُلُّ هَذَا الشُّرُودِ وَالْحُزْنِ؟",segs:[{ar:"لِمَاذَا كُلُّ هَذَا",uz:"nega buncha"},{ar:"الشُّرُودِ وَالْحُزْنِ؟",uz:"xayolga cho‘mish va qayg‘u?"}],full_uz:"Nega buncha xayolga cho‘mish va qayg‘u?",note:"شُرُودٌ — diqqatning boshqa joyda bo‘lishi, xayolga cho‘mish."},
{num:55,time:"00:04:47,579 --> 00:04:52,660",arabic:"لَا شَيْءَ يَا زُبَيْدَةُ.",segs:[{ar:"لَا شَيْءَ",uz:"hech narsa"},{ar:"يَا زُبَيْدَةُ",uz:"ey Zubayda"}],full_uz:"Hech narsa, Zubayda.",note:null},
{num:56,time:"00:04:54,660 --> 00:05:04,540",arabic:"لَوْ قُلْتَ هَذَا الْكَلَامَ لِغَيْرِي لَصَدَّقَكَ.",segs:[{ar:"لَوْ قُلْتَ هَذَا الْكَلَامَ",uz:"agar bu gapni aytganingizda"},{ar:"لِغَيْرِي",uz:"mendan boshqasiga"},{ar:"لَصَدَّقَكَ",uz:"u sizga ishongan bo‘lardi"}],full_uz:"Bu gapni mendan boshqasiga aytganingizda, u sizga ishongan bo‘lardi.",note:"لَوْ ... لَـ ... amalga oshmagan shart va uning faraziy natijasini bildiradi."},
{num:57,time:"00:05:04,540 --> 00:05:05,959",arabic:"أَمَّا أَنَا...",segs:null,full_uz:"Menga kelsak...",note:null},
{num:58,time:"00:05:05,959 --> 00:05:08,339",arabic:"أَنَا الَّتِي تَعْرِفُكَ جَيِّدًا.",segs:[{ar:"أَنَا الَّتِي",uz:"men o‘sha kishimanki"},{ar:"تَعْرِفُكَ جَيِّدًا",uz:"sizni yaxshi biladi"}],full_uz:"Men sizni yaxshi biladigan kishiman.",note:"الَّتِي ayol kishiga tegishli nisbiy olmosh. Undan keyingi تَعْرِفُ fe’li shu olmoshga moslashgan."},
{num:59,time:"00:05:08,339 --> 00:05:12,160",arabic:"أَنَا الَّتِي تَشْعُرُ بِكُلِّ أَنْفَاسِكَ وَهُمُومِكَ.",segs:[{ar:"أَنَا الَّتِي تَشْعُرُ",uz:"men his qiladigan kishiman"},{ar:"بِكُلِّ أَنْفَاسِكَ وَهُمُومِكَ",uz:"har bir nafasingiz va tashvishlaringizni"}],full_uz:"Men har bir nafasingiz va tashvishlaringizni his qiladigan kishiman.",note:"أَنْفَاسٌ — نَفَسٌ («nafas»)ning, هُمُومٌ — هَمٌّ («tashvish»)ning ko‘pligi."},
{num:60,time:"00:05:12,160 --> 00:05:14,019",arabic:"فَلَا يُمْكِنُنِي.",segs:null,full_uz:"Shuning uchun men bunday qila olmayman.",note:null},
{num:61,time:"00:05:14,019 --> 00:05:21,219",arabic:"لَا أُخْفِيكِ يَا زُبَيْدَةُ.",segs:[{ar:"لَا أُخْفِيكِ",uz:"sizdan yashirmayman"},{ar:"يَا زُبَيْدَةُ",uz:"ey Zubayda"}],full_uz:"Sizdan yashirmayman, Zubayda.",note:"لَا أُخْفِيكِ — suhbatdagi «sizdan yashirmayman, ochig‘ini aytaman» iborasi."},
{num:62,time:"00:05:21,219 --> 00:05:25,819",arabic:"وَاللَّهِ مُنْذُ أَنْ حَدَثَ لِجَعْفَرٍ مَا حَدَثَ...",segs:[{ar:"وَاللَّهِ",uz:"Allohga qasam"},{ar:"مُنْذُ أَنْ حَدَثَ لِجَعْفَرٍ",uz:"Ja’farning boshiga kelganidan beri"},{ar:"مَا حَدَثَ",uz:"o‘sha voqea"}],full_uz:"Allohga qasam, Ja’farning boshiga o‘sha voqea kelganidan beri...",note:"مُنْذُ أَنْ + fe’l — «...ganidan beri». مَا حَدَثَ — «sodir bo‘lgan narsa»."},
{num:63,time:"00:05:25,819 --> 00:05:30,259",arabic:"وَأَنَا نَادِرًا أَجِدُ فِي رُوحِيَ الرَّاحَةَ.",segs:[{ar:"وَأَنَا نَادِرًا أَجِدُ",uz:"men kamdan kam topaman"},{ar:"فِي رُوحِيَ الرَّاحَةَ",uz:"ruhimda xotirjamlik"}],full_uz:"Men ruhimda kamdan kam xotirjamlik topaman.",note:"نَادِرًا — «kamdan kam». Ko‘pincha fe’ldan oldin kelib, harakatning kam takrorlanishini bildiradi."},
{num:64,time:"00:05:30,259 --> 00:05:32,740",arabic:"فَدَتْكَ نَفْسِي يَا مَوْلَايَ.",segs:[{ar:"فَدَتْكَ نَفْسِي",uz:"jonim sizga fido bo‘lsin"},{ar:"يَا مَوْلَايَ",uz:"ey hukmdorim"}],full_uz:"Jonim sizga fido bo‘lsin, hukmdorim.",note:"فَدَتْكَ نَفْسِي — mehr va sadoqatni ifodalovchi ibora."},
{num:65,time:"00:05:44,019 --> 00:05:57,379",arabic:"لَيْتَ صَاحِبِي كَانَ يَعْلَمُ مِقْدَارَ مَحَبَّتِي لَهُ.",segs:[{ar:"لَيْتَ صَاحِبِي كَانَ يَعْلَمُ",uz:"qaniydi do‘stim bilganida"},{ar:"مِقْدَارَ مَحَبَّتِي لَهُ",uz:"unga bo‘lgan muhabbatimning darajasini"}],full_uz:"Qaniydi do‘stim uni qanchalik yaxshi ko‘rishimni bilganida.",note:"لَيْتَ armon yoki istakni bildiradi. مِقْدَارُ مَحَبَّتِي — «muhabbatimning darajasi»."},
{num:66,time:"00:05:57,379 --> 00:06:01,479",arabic:"لَكَانَ جَنَّبَنِي فِعْلَ ذَلِكَ.",segs:[{ar:"لَكَانَ جَنَّبَنِي",uz:"unda meni saqlagan bo‘lardi"},{ar:"فِعْلَ ذَلِكَ",uz:"buni qilishdan"}],full_uz:"Unda meni buni qilishdan saqlagan bo‘lardi.",note:"جَنَّبَ فُلَانًا شَيْئًا — «bir kishini biror narsadan chetlatdi, saqladi»."},
{num:67,time:"00:06:01,479 --> 00:06:04,899",arabic:"غَفَرَ اللَّهُ لَهُ وَلَنَا.",segs:[{ar:"غَفَرَ اللَّهُ لَهُ",uz:"Alloh uni kechirsin"},{ar:"وَلَنَا",uz:"va bizni ham"}],full_uz:"Alloh uni ham, bizni ham kechirsin.",note:null},
{num:68,time:"00:06:04,899 --> 00:06:08,439",arabic:"وَثَبَّتَكَ عَلَى الْحَقِّ يَا أَمِيرَ الْمُؤْمِنِينَ.",segs:[{ar:"وَثَبَّتَكَ عَلَى الْحَقِّ",uz:"va sizni haq yo‘lida sobit qilsin"},{ar:"يَا أَمِيرَ الْمُؤْمِنِينَ",uz:"ey mo‘minlar amiri"}],full_uz:"Va sizni haq yo‘lida sobit qilsin, ey mo‘minlar amiri.",note:"ثَبَّتَ — «mustahkam qildi, sobit qildi». يَا أَمِيرَ الْمُؤْمِنِينَ da izofali munodo mansub."},
{num:69,time:"00:06:14,019 --> 00:06:15,539",arabic:"غَفَرَ اللَّهُ لَهُ.",segs:null,full_uz:"Alloh uni kechirsin.",note:null},
{num:70,time:"00:06:15,539 --> 00:06:19,060",arabic:"لَا أَسْتَطِيعُ أَنْ أَقُولَ أَكْثَرَ مِنْ ذَلِكَ.",segs:[{ar:"لَا أَسْتَطِيعُ أَنْ أَقُولَ",uz:"ayta olmayman"},{ar:"أَكْثَرَ مِنْ ذَلِكَ",uz:"bundan ortiq"}],full_uz:"Bundan ortiq gap ayta olmayman.",note:null},
{num:71,time:"00:06:19,060 --> 00:06:33,639",arabic:"أُرِيدُ أَنْ أُفَاتِحَكِ بِأَمْرٍ يَا أُخْتَاهُ.",segs:[{ar:"أُرِيدُ أَنْ أُفَاتِحَكِ بِأَمْرٍ",uz:"sizga bir masalani ochmoqchiman"},{ar:"يَا أُخْتَاهُ",uz:"ey singlim"}],full_uz:"Sizga bir masalani ochmoqchiman, singlim.",note:"فَاتَحَ شَخْصًا بِأَمْرٍ — «birov bilan bir masala haqida gap ochdi»."},
{num:72,time:"00:06:33,639 --> 00:06:35,259",arabic:"قُلْ يَا شَفِيعُ.",segs:[{ar:"قُلْ",uz:"ayting"},{ar:"يَا شَفِيعُ",uz:"ey Shafi’"}],full_uz:"Ayting, Shafi’.",note:null},
{num:73,time:"00:06:35,259 --> 00:06:36,879",arabic:"إِنِّي أَسْمَعُكَ.",segs:null,full_uz:"Sizni eshityapman.",note:null},
{num:74,time:"00:06:36,879 --> 00:06:40,000",arabic:"لَقَدْ كَثُرَتْ عَلَيَّ مَشَاغِلِي.",segs:[{ar:"لَقَدْ كَثُرَتْ عَلَيَّ",uz:"zimmamda juda ko‘paydi"},{ar:"مَشَاغِلِي",uz:"yumushlarim"}],full_uz:"Zimmamdagi yumushlarim juda ko‘paydi.",note:"مَشَاغِلُ — مَشْغَلٌ so‘zining ko‘pligi: kishini band qiladigan ishlar, yumushlar."},
{num:75,time:"00:06:40,000 --> 00:06:43,479",arabic:"وَلَمْ يَعُدْ وَقْتِي يُعِينُنِي عَلَى الِاعْتِنَاءِ بِكِ.",segs:[{ar:"وَلَمْ يَعُدْ وَقْتِي يُعِينُنِي",uz:"va vaqtim endi imkon bermayapti"},{ar:"عَلَى الِاعْتِنَاءِ بِكِ",uz:"sizga g‘amxo‘rlik qilishga"}],full_uz:"Vaqtim endi sizga g‘amxo‘rlik qilishga imkon bermayapti.",note:"لَمْ يَعُدْ — «endi ...maydi». اِعْتَنَى بِـ — «g‘amxo‘rlik qildi, qaradi»."},
{num:76,time:"00:06:43,480 --> 00:06:48,900",arabic:"وَقَدْ أَصْبَحَ مِنَ الضَّرُورِيِّ أَنْ آتِيَ لَكِ بِجَارِيَةٍ تَهْتَمُّ بِكِ.",segs:[{ar:"وَقَدْ أَصْبَحَ مِنَ الضَّرُورِيِّ",uz:"va zarur bo‘lib qoldi"},{ar:"أَنْ آتِيَ لَكِ بِجَارِيَةٍ",uz:"sizga bir joriya olib kelishim"},{ar:"تَهْتَمُّ بِكِ",uz:"sizga g‘amxo‘rlik qiladigan"}],full_uz:"Sizga g‘amxo‘rlik qiladigan bir joriya olib kelishim zarur bo‘lib qoldi.",note:"أَتَى بِـ — «olib keldi». جَارِيَةٌ bu tarixiy kontekstda qul ayol, joriya degani."},
{num:77,time:"00:06:48,900 --> 00:06:51,900",arabic:"وَتَعْتَنِي بِشُؤُونِكِ فِي غِيَابِي.",segs:[{ar:"وَتَعْتَنِي بِشُؤُونِكِ",uz:"va ishlaringizga qaraydigan"},{ar:"فِي غِيَابِي",uz:"men yo‘qligimda"}],full_uz:"Va men yo‘qligimda ishlaringizga qaraydigan.",note:"شُؤُونٌ — شَأْنٌ («ish, masala») so‘zining ko‘pligi."},
{num:78,time:"00:06:51,900 --> 00:06:54,560",arabic:"أَعَانَكَ اللَّهُ يَا أَخِي.",segs:[{ar:"أَعَانَكَ اللَّهُ",uz:"Alloh sizga yordam bersin"},{ar:"يَا أَخِي",uz:"ey akam"}],full_uz:"Alloh sizga yordam bersin, akam.",note:null},
{num:79,time:"00:06:54,560 --> 00:06:56,020",arabic:"لَا تَخَفْ عَلَيَّ.",segs:null,full_uz:"Men uchun xavotir olmang.",note:"خَافَ عَلَى — «uchun xavotirlandi». Taqiqdagi لَا dan keyin تَخَافُ → تَخَفْ bo‘ladi."},
{num:80,time:"00:06:56,020 --> 00:06:59,240",arabic:"فَابْنَةُ عَمِّكَ لَا تُقَصِّرُ فِي حَقِّي.",segs:[{ar:"فَابْنَةُ عَمِّكَ",uz:"axir amakingizning qizi"},{ar:"لَا تُقَصِّرُ فِي حَقِّي",uz:"menga g‘amxo‘rlikda kamchilik qilmaydi"}],full_uz:"Axir amakingizning qizi menga g‘amxo‘rlik qilishda kamchilik qilmaydi.",note:"قَصَّرَ فِي حَقِّ شَخْصٍ — «birov oldidagi burchini yetarli bajarmadi»."},
{num:81,time:"00:06:59,240 --> 00:07:02,480",arabic:"وَهِيَ تَرْعَانِي وَتَهْتَمُّ بِي كُلَّ الْوَقْتِ.",segs:[{ar:"وَهِيَ تَرْعَانِي",uz:"u menga qaraydi"},{ar:"وَتَهْتَمُّ بِي",uz:"va menga g‘amxo‘rlik qiladi"},{ar:"كُلَّ الْوَقْتِ",uz:"doimo"}],full_uz:"U doimo menga qaraydi va g‘amxo‘rlik qiladi.",note:null},
{num:82,time:"00:07:04,000 --> 00:07:07,259",arabic:"بَارَكَ اللَّهُ فِيهَا.",segs:null,full_uz:"Alloh unga baraka bersin.",note:null},
{num:83,time:"00:07:07,259 --> 00:07:09,540",arabic:"وَأَنَا أُقَدِّرُ لَهَا ذَلِكَ.",segs:null,full_uz:"Men uning bu ishini qadrlayman.",note:"قَدَّرَ لِشَخْصٍ فِعْلَهُ — «birovning qilgan ishini qadrladi»."},
{num:84,time:"00:07:09,540 --> 00:07:12,640",arabic:"وَلَكِنِّي لَا أُرِيدُ أَنْ أُثْقِلَ عَلَى أَحَدٍ.",segs:[{ar:"وَلَكِنِّي لَا أُرِيدُ",uz:"lekin men istamayman"},{ar:"أَنْ أُثْقِلَ عَلَى أَحَدٍ",uz:"birovga yuk bo‘lishni"}],full_uz:"Lekin birovga yuk bo‘lishni istamayman.",note:"أَثْقَلَ عَلَى شَخْصٍ — «birovga og‘irlik qildi, yuk bo‘ldi»."},
{num:85,time:"00:07:12,639 --> 00:07:14,699",arabic:"حَسَنًا، كَمَا تَشَاءُ.",segs:[{ar:"حَسَنًا",uz:"xo‘p"},{ar:"كَمَا تَشَاءُ",uz:"xohlaganingizdek"}],full_uz:"Xo‘p, xohlaganingizdek.",note:null},
{num:86,time:"00:07:14,699 --> 00:07:19,560",arabic:"وَلَكِنَّكَ إِلَى الْآنَ لَمْ تَجِدِ الْجَارِيَةَ الْمُنَاسِبَةَ.",segs:[{ar:"وَلَكِنَّكَ إِلَى الْآنَ",uz:"lekin siz hozirgacha"},{ar:"لَمْ تَجِدِ",uz:"topmadingiz"},{ar:"الْجَارِيَةَ الْمُنَاسِبَةَ",uz:"munosib joriyani"}],full_uz:"Lekin siz hozirgacha munosib joriyani topmadingiz.",note:"لَمْ تَجِدْ aslida sukun bilan jazm bo‘ladi; keyingi الْ bilan tutashtirib o‘qilganda د kasra oladi."},
{num:87,time:"00:07:19,560 --> 00:07:21,759",arabic:"فَمَاذَا نَفْعَلُ؟",segs:null,full_uz:"Unda nima qilamiz?",note:null},
{num:88,time:"00:07:22,159 --> 00:07:25,139",arabic:"لَمْ أَجِدْ جَارِيَةً يَطْمَئِنُّ لَهَا قَلْبِي.",segs:[{ar:"لَمْ أَجِدْ جَارِيَةً",uz:"biror joriya topmadim"},{ar:"يَطْمَئِنُّ لَهَا قَلْبِي",uz:"ko‘nglim unga ishongan"}],full_uz:"Ko‘nglim ishongan biror joriya topmadim.",note:"يَطْمَئِنُّ لَهَا قَلْبِي — so‘zma-so‘z «qalbim undan xotirjam bo‘ladi», ya’ni unga ishonadi."},
{num:89,time:"00:07:25,139 --> 00:07:30,139",arabic:"إِلَّا تِلْكَ الْفَتَاةَ الْمِسْكِينَةَ الَّتِي حَدَّثْتُكِ عَنْهَا مِنْ قَبْلُ.",segs:[{ar:"إِلَّا تِلْكَ الْفَتَاةَ الْمِسْكِينَةَ",uz:"faqat o‘sha bechora qizdan boshqa"},{ar:"الَّتِي حَدَّثْتُكِ عَنْهَا",uz:"sizga u haqida gapirgan edim"},{ar:"مِنْ قَبْلُ",uz:"ilgari"}],full_uz:"Faqat sizga ilgari aytgan o‘sha bechora qizdan boshqa.",note:"إِلَّا oldingi inkor gapdan istisno qiladi: «...dan boshqa». مِنْ قَبْلُ — «ilgari»."},
{num:90,time:"00:07:30,139 --> 00:07:31,879",arabic:"كَمَا تُرِيدُ.",segs:null,full_uz:"Istaganingizdek.",note:null},
{num:91,time:"00:07:31,879 --> 00:07:35,659",arabic:"إِنْ كُنْتَ تَرَاهَا مُنَاسِبَةً فَلَا بَأْسَ.",segs:[{ar:"إِنْ كُنْتَ تَرَاهَا مُنَاسِبَةً",uz:"agar uni munosib deb bilsangiz"},{ar:"فَلَا بَأْسَ",uz:"unda mayli"}],full_uz:"Agar uni munosib deb bilsangiz, mayli.",note:"رَأَى bu yerda ko‘z bilan ko‘rish emas, «deb bilish, hisoblash» ma’nosida."},
{num:92,time:"00:07:35,659 --> 00:07:38,319",arabic:"أَنَا مُوَافِقَةٌ.",segs:null,full_uz:"Men roziman.",note:"Ayol kishi مُوَافِقَةٌ, erkak kishi مُوَافِقٌ deydi."},
{num:93,time:"00:07:42,639 --> 00:07:54,839",arabic:"صَدِّقِينِي يَا أُخْتَاهُ.",segs:[{ar:"صَدِّقِينِي",uz:"menga ishoning"},{ar:"يَا أُخْتَاهُ",uz:"ey singlim"}],full_uz:"Menga ishoning, singlim.",note:"صَدِّقِينِي — ayol kishiga buyruq: صَدِّقِي («ishoning») + نِي («menga»)."},
{num:94,time:"00:07:54,839 --> 00:07:58,199",arabic:"لَوْ لَمْ أَكُنْ مُتَأَكِّدًا مِنْ أَنَّهَا مُنَاسِبَةٌ...",segs:[{ar:"لَوْ لَمْ أَكُنْ مُتَأَكِّدًا",uz:"agar ishonchim komil bo‘lmaganida"},{ar:"مِنْ أَنَّهَا مُنَاسِبَةٌ",uz:"uning munosib ekaniga"}],full_uz:"Uning munosib ekaniga ishonchim komil bo‘lmaganida...",note:"مُتَأَكِّدٌ مِنْ — «...ga ishonchi komil». لَوْ shartining javobi keyingi bandda."},
{num:95,time:"00:07:58,199 --> 00:08:00,139",arabic:"مَا كُنْتُ مُصِرًّا عَلَيْهَا.",segs:null,full_uz:"Aynan uni olishda turib olmagan bo‘lardim.",note:"أَصَرَّ عَلَى — «...da qat’iy turib oldi». مُصِرٌّ — shu fe’lning ismi foili."},
{num:96,time:"00:08:00,139 --> 00:08:02,060",arabic:"وَأَنَا أَثِقُ بِاخْتِيَارِكَ.",segs:null,full_uz:"Men esa tanlovingizga ishonaman.",note:"وَثِقَ — يَثِقُ: muzoriyda boshidagi و tushadi. أَثِقُ — «men ishonaman»."},
{num:97,time:"00:08:02,060 --> 00:08:06,139",arabic:"وَأَعْرِفُ أَنَّكَ لَا تَفْعَلُ إِلَّا خَيْرًا وَصَوَابًا.",segs:[{ar:"وَأَعْرِفُ أَنَّكَ",uz:"va bilamanki, siz"},{ar:"لَا تَفْعَلُ إِلَّا",uz:"faqat qilasiz"},{ar:"خَيْرًا وَصَوَابًا",uz:"yaxshilik va to‘g‘ri ish"}],full_uz:"Siz faqat yaxshilik va to‘g‘ri ish qilishingizni bilaman.",note:"لَا ... إِلَّا ... — cheklash: «faqat ...». So‘zma-so‘z «...dan boshqasini qilmaydi»."},
{num:98,time:"00:08:08,219 --> 00:08:09,699",arabic:"أَحْضِرْهَا مَتَى شِئْتَ.",segs:[{ar:"أَحْضِرْهَا",uz:"uni olib keling"},{ar:"مَتَى شِئْتَ",uz:"qachon xohlasangiz"}],full_uz:"Uni qachon xohlasangiz olib keling.",note:null},
{num:99,time:"00:08:12,639 --> 00:08:28,300",arabic:"هَلْ تَأَكَّدْتُمْ مِنْ صِحَّةِ الْأَخْبَارِ الْوَارِدَةِ مِنَ الْقُسْطَنْطِينِيَّةِ يَا ابْنَ الرَّبِيعِ؟",segs:[{ar:"هَلْ تَأَكَّدْتُمْ",uz:"ishonch hosil qildingizmi"},{ar:"مِنْ صِحَّةِ الْأَخْبَارِ",uz:"xabarlarning to‘g‘riligiga"},{ar:"الْوَارِدَةِ مِنَ الْقُسْطَنْطِينِيَّةِ",uz:"Qustantiniyadan kelgan"},{ar:"يَا ابْنَ الرَّبِيعِ؟",uz:"ey Ibn Rabi’?"}],full_uz:"Qustantiniyadan kelgan xabarlarning to‘g‘riligiga ishonch hosil qildingizmi, Ibn Rabi’?",note:"وَارِدٌ — «kelgan, kelib tushgan». الْأَخْبَارُ g‘ayri oqil ko‘plik bo‘lgani uchun sifati الْوَارِدَةُ birlik muannasda."},
{num:100,time:"00:08:28,300 --> 00:08:29,659",arabic:"أَجَلْ يَا أَمِيرَ الْمُؤْمِنِينَ.",segs:[{ar:"أَجَلْ",uz:"ha"},{ar:"يَا أَمِيرَ الْمُؤْمِنِينَ",uz:"ey mo‘minlar amiri"}],full_uz:"Ha, ey mo‘minlar amiri.",note:null},
{num:101,time:"00:08:29,659 --> 00:08:31,379",arabic:"الْأَخْبَارُ صَحِيحَةٌ.",segs:null,full_uz:"Xabarlar to‘g‘ri.",note:null},
{num:102,time:"00:08:31,379 --> 00:08:34,460",arabic:"يَبْدُو أَنَّ الرُّومَ قَدْ خَلَعُوا مَلِكَتَهُمْ أَغُسْطَةَ.",segs:[{ar:"يَبْدُو أَنَّ الرُّومَ",uz:"aftidan, rumliklar"},{ar:"قَدْ خَلَعُوا مَلِكَتَهُمْ أَغُسْطَةَ",uz:"malikalari Ag‘ustani taxtdan tushirishgan"}],full_uz:"Aftidan, rumliklar malikalari Ag‘ustani taxtdan tushirishgan.",note:"خَلَعَ مَلِكًا — «podshohni taxtdan tushirdi». مَلِكَةٌ — «malika», مَمْلَكَةٌ esa «qirollik»."},
{num:103,time:"00:08:34,460 --> 00:08:39,939",arabic:"وَثَمَّةَ فَوْضَى فِي صُفُوفِ الرُّومِ تَكَادُ تُذْهِبُ عَرْشَهُمْ وَمُلْكَهُمْ.",segs:[{ar:"وَثَمَّةَ فَوْضَى",uz:"va tartibsizlik bor"},{ar:"فِي صُفُوفِ الرُّومِ",uz:"rumliklar safida"},{ar:"تَكَادُ تُذْهِبُ",uz:"deyarli yo‘q qilib yuboradigan"},{ar:"عَرْشَهُمْ وَمُلْكَهُمْ",uz:"ularning taxti va hukmronligini"}],full_uz:"Rumliklar safida ularning taxti va hukmronligini yo‘q qilishga yaqin tartibsizlik bor.",note:"ثَمَّةَ — «bor, mavjud». أَذْهَبَ — «ketkazdi, yo‘q qildi»; ذَهَبَ esa «ketdi»."},
{num:104,time:"00:08:39,940 --> 00:08:46,380",arabic:"وَهَلْ جُنْدُنَا فِي الثُّغُورِ عَلَى أُهْبَةِ الِاسْتِعْدَادِ؟",segs:[{ar:"وَهَلْ جُنْدُنَا فِي الثُّغُورِ",uz:"chegaralardagi askarlarimiz-chi"},{ar:"عَلَى أُهْبَةِ الِاسْتِعْدَادِ؟",uz:"to‘liq tayyormi?"}],full_uz:"Chegaralardagi askarlarimiz to‘liq tayyormi?",note:"عَلَى أُهْبَةِ الِاسْتِعْدَادِ — «shay, to‘liq tayyor». ثُغُورٌ bu yerda chegara hududlari yoki istehkomlari."},
{num:105,time:"00:08:46,380 --> 00:08:52,260",arabic:"أَجَلْ يَا مَوْلَايَ، وَقَدْ تَوَلَّى الْإِشْرَافَ عَلَى ذَلِكَ الْأَمِيرُ الْقَاسِمُ ابْنُ أَمِيرِ الْمُؤْمِنِينَ.",segs:[{ar:"أَجَلْ يَا مَوْلَايَ",uz:"ha, hukmdorim"},{ar:"وَقَدْ تَوَلَّى الْإِشْرَافَ عَلَى ذَلِكَ",uz:"buni nazorat qilishni zimmasiga olgan"},{ar:"الْأَمِيرُ الْقَاسِمُ",uz:"amir Qosim"},{ar:"ابْنُ أَمِيرِ الْمُؤْمِنِينَ",uz:"mo‘minlar amirining o‘g‘li"}],full_uz:"Ha, hukmdorim. Buni nazorat qilishni mo‘minlar amirining o‘g‘li amir Qosim zimmasiga olgan.",note:"تَوَلَّى — «zimmasiga oldi, boshqardi». الْإِشْرَافُ عَلَى — «ustidan nazorat qilish»."},
{num:106,time:"00:08:52,260 --> 00:08:57,680",arabic:"مَا لِهَؤُلَاءِ الْحَمْقَى قَدْ ثَارُوا عَلَى مَلِكَتِهِمْ؟",segs:[{ar:"مَا لِهَؤُلَاءِ الْحَمْقَى",uz:"bu ahmoqlarga nima bo‘ldi"},{ar:"قَدْ ثَارُوا عَلَى مَلِكَتِهِمْ؟",uz:"malikalariga qarshi bosh ko‘tarishibdi?"}],full_uz:"Bu ahmoqlarga nima bo‘ldiki, malikalariga qarshi bosh ko‘tarishibdi?",note:"ثَارَ عَلَى — «...ga qarshi qo‘zg‘aldi». حَمْقَى — أَحْمَقُ («ahmoq»)ning ko‘pligi."},
{num:107,time:"00:08:57,680 --> 00:09:00,100",arabic:"وَاللَّهِ لَقَدْ كَانَتْ تَسُوسُهُمْ بِعَقْلٍ وَحِكْمَةٍ.",segs:[{ar:"وَاللَّهِ",uz:"Allohga qasam"},{ar:"لَقَدْ كَانَتْ تَسُوسُهُمْ",uz:"u ularni boshqarardi"},{ar:"بِعَقْلٍ وَحِكْمَةٍ",uz:"aql va hikmat bilan"}],full_uz:"Allohga qasam, u ularni aql va hikmat bilan boshqarardi.",note:"سَاسَ — يَسُوسُ — «boshqarmoq, siyosat yuritmoq»."},
{num:108,time:"00:09:00,100 --> 00:09:05,620",arabic:"هَؤُلَاءِ الْأَعَاجِمُ يَا مَوْلَايَ يَسْتَبْدِلُونَ مُلُوكَهُمْ كَمَا يَسْتَبْدِلُونَ مَلَابِسَهُمْ.",segs:[{ar:"هَؤُلَاءِ الْأَعَاجِمُ",uz:"bu ajamlar"},{ar:"يَا مَوْلَايَ",uz:"ey hukmdorim"},{ar:"يَسْتَبْدِلُونَ مُلُوكَهُمْ",uz:"podshohlarini almashtiradilar"},{ar:"كَمَا يَسْتَبْدِلُونَ مَلَابِسَهُمْ",uz:"kiyimlarini almashtirgandek"}],full_uz:"Bu ajamlar, hukmdorim, podshohlarini kiyimlarini almashtirgandek almashtiradilar.",note:"الْأَعَاجِمُ — arab bo‘lmagan xalqlarni bildiruvchi tarixiy atama. كَمَا — «...ganidek»."},
{num:109,time:"00:09:05,620 --> 00:09:07,940",arabic:"فَمَا إِنْ يَطْمَعُ أَحَدُهُمْ فِي الْمُلْكِ...",segs:[{ar:"فَمَا إِنْ يَطْمَعُ أَحَدُهُمْ",uz:"ulardan biri havas qilishi bilanoq"},{ar:"فِي الْمُلْكِ",uz:"hukmronlikka"}],full_uz:"Ulardan biri hukmronlikka havas qilishi bilanoq...",note:"مَا إِنْ ... حَتَّى ... — «...ishi bilanoq ...». Natija 120-bandda davom etadi."},
{num:110,time:"00:09:07,940 --> 00:09:10,419",arabic:"وَمَا أَكْثَرَ الطَّامِعِينَ يَا مَوْلَايَ!",segs:[{ar:"وَمَا أَكْثَرَ الطَّامِعِينَ",uz:"tamagirlar naqadar ko‘p"},{ar:"يَا مَوْلَايَ",uz:"ey hukmdorim"}],full_uz:"Tamagirlar esa naqadar ko‘p, hukmdorim!",note:"مَا أَفْعَلَ qolipi taajjubni bildiradi: مَا أَكْثَرَ... — «naqadar ko‘p!»."},
{num:111,time:"00:09:10,419 --> 00:09:12,740",arabic:"حَتَّى يَنْقَضُّوا عَلَى مَلِكِهِمْ.",segs:[{ar:"حَتَّى يَنْقَضُّوا",uz:"darhol tashlanadilar"},{ar:"عَلَى مَلِكِهِمْ",uz:"o‘z podshohlariga"}],full_uz:"Darhol o‘z podshohlariga tashlanadilar.",note:"اِنْقَضَّ عَلَى — «ustiga tashlandi, hujum qildi»."},
{num:112,time:"00:09:12,740 --> 00:09:14,279",arabic:"وَيَقْتُلُوهُ.",segs:null,full_uz:"Va uni o‘ldiradilar.",note:null},
{num:113,time:"00:09:14,279 --> 00:09:15,500",arabic:"وَلَوْ كَانَ مَلَكًا.",segs:null,full_uz:"Hatto u farishta bo‘lsa ham.",note:"مَلَكٌ — «farishta»; مَلِكٌ — «podshoh». O‘rta harakat ma’noni o‘zgartiradi."},
{num:114,time:"00:09:15,500 --> 00:09:17,500",arabic:"وَيَسْلُبُوهُ عَرْشَهُ وَمُلْكَهُ.",segs:[{ar:"وَيَسْلُبُوهُ",uz:"va undan tortib oladilar"},{ar:"عَرْشَهُ وَمُلْكَهُ",uz:"taxti va hukmronligini"}],full_uz:"Va uning taxti hamda hukmronligini tortib oladilar.",note:"سَلَبَ — «tortib oldi, mahrum qildi». مُلْكٌ — «hukmronlik»."},
{num:115,time:"00:09:17,500 --> 00:09:18,759",arabic:"تَعْسًا لَهُمْ!",segs:null,full_uz:"Halok bo‘lsinlar!",note:"تَعْسًا لَهُ — qarg‘ish ifodasi: «holiga voy, halok bo‘lsin»."},
{num:116,time:"00:09:18,759 --> 00:09:20,539",arabic:"أَلَا يَعْقِلُونَ؟",segs:null,full_uz:"Axir aql yuritmaydilarmi?",note:null},
{num:117,time:"00:09:20,539 --> 00:09:23,740",arabic:"أَلَا يَعْلَمُونَ أَنَّ مَنْ خَلَعَ يُخْلَعُ؟",segs:[{ar:"أَلَا يَعْلَمُونَ",uz:"axir bilmaydilarmi"},{ar:"أَنَّ مَنْ خَلَعَ",uz:"taxtdan tushirgan kishining"},{ar:"يُخْلَعُ؟",uz:"o‘zi ham tushirilishini?"}],full_uz:"Birovni taxtdan tushirgan kishining o‘zi ham tushirilishini bilmaydilarmi?",note:"خَلَعَ — aniq nisbat: «tushirdi»; يُخْلَعُ — majhul nisbat: «tushiriladi»."},
{num:118,time:"00:09:23,740 --> 00:09:24,759",arabic:"وَلَوْ بَعْدَ حِينٍ.",segs:null,full_uz:"Hatto bir muddatdan keyin bo‘lsa ham.",note:null},
{num:119,time:"00:09:24,759 --> 00:09:27,460",arabic:"أَلَا يَعْلَمُونَ أَنَّ الْمُلْكَ لَا يَدُومُ...",segs:[{ar:"أَلَا يَعْلَمُونَ",uz:"axir bilmaydilarmi"},{ar:"أَنَّ الْمُلْكَ لَا يَدُومُ",uz:"hukmronlik abadiy qolmasligini"}],full_uz:"Hukmronlik abadiy qolmasligini bilmaydilarmi...",note:"دَامَ — يَدُومُ — «davom etmoq, saqlanib qolmoq»."},
{num:120,time:"00:09:27,460 --> 00:09:30,240",arabic:"إِلَّا لِصَاحِبِ الْمُلْكِ سُبْحَانَهُ وَتَعَالَى.",segs:[{ar:"إِلَّا لِصَاحِبِ الْمُلْكِ",uz:"faqat mulkning Egasigagina"},{ar:"سُبْحَانَهُ وَتَعَالَى",uz:"U pok va yuksakdir"}],full_uz:"Faqat mulkning Egasigagina abadiy qoladi. U pok va yuksakdir.",note:"Oldingi banddagi لَا ... bilan birga إِلَّا cheklashni bildiradi: «faqat ...gagina»."},
{num:121,time:"00:09:30,240 --> 00:09:33,060",arabic:"أَمْ أَنَّ الطَّمَعَ وَشَهْوَةَ الْحُكْمِ...",segs:[{ar:"أَمْ أَنَّ الطَّمَعَ",uz:"yoki tamagirlik"},{ar:"وَشَهْوَةَ الْحُكْمِ",uz:"va hokimiyatga bo‘lgan hirs"}],full_uz:"Yoki tamagirlik va hokimiyatga bo‘lgan hirs...",note:"شَهْوَةٌ faqat jismoniy mayl emas, biror narsaga kuchli hirs ma’nosida ham keladi."},
{num:122,time:"00:09:33,060 --> 00:09:35,340",arabic:"أَنْسَتْهُمُ الِاكْتِرَاثَ لِحَيَاةِ النَّاسِ؟",segs:[{ar:"أَنْسَتْهُمُ الِاكْتِرَاثَ",uz:"ularga qayg‘urishni unuttirdimi"},{ar:"لِحَيَاةِ النَّاسِ؟",uz:"odamlarning hayoti uchun?"}],full_uz:"Ularga odamlarning hayoti uchun qayg‘urishni unuttirdimi?",note:"أَنْسَى — «unuttirdi»; نَسِيَ — «unutdi». اِكْتِرَاثٌ — «ahamiyat berish, qayg‘urish»."},
{num:123,time:"00:09:35,340 --> 00:09:41,860",arabic:"رُبَّمَا اسْتَغَلَّ بَعْضُ أُمَرَائِهِمْ حَالَةَ الْفَوْضَى الدَّائِرَةَ بَيْنَهُمْ.",segs:[{ar:"رُبَّمَا اسْتَغَلَّ",uz:"ehtimol, foydalanar"},{ar:"بَعْضُ أُمَرَائِهِمْ",uz:"ularning ayrim amirlari"},{ar:"حَالَةَ الْفَوْضَى",uz:"tartibsizlik holatidan"},{ar:"الدَّائِرَةَ بَيْنَهُمْ",uz:"ular orasida yuz berayotgan"}],full_uz:"Ehtimol, ayrim amirlari ular orasida yuz berayotgan tartibsizlikdan foydalanar.",note:"رُبَّمَا bilan kelgan o‘tgan zamon fe’li kontekstga qarab hozirgi yoki kelajakdagi ehtimolni ham anglatadi."},
{num:124,time:"00:09:41,860 --> 00:09:44,300",arabic:"لِيَنْقُضَ الْعُهُودَ وَالْمَوَاثِيقَ.",segs:[{ar:"لِيَنْقُضَ",uz:"buzish uchun"},{ar:"الْعُهُودَ وَالْمَوَاثِيقَ",uz:"ahdlar va bitimlarni"}],full_uz:"Ahdlar va bitimlarni buzish uchun.",note:"نَقَضَ عَهْدًا — «ahdni buzdi». لِـ maqsad bildiradi va muzoriyni nasb qiladi."},
{num:125,time:"00:09:44,300 --> 00:09:49,620",arabic:"أَوْ رُبَّمَا اسْتَغَلُّوا ذَلِكَ لِصَرْفِ أَنْظَارِ رَعَايَاهُمْ.",segs:[{ar:"أَوْ رُبَّمَا اسْتَغَلُّوا ذَلِكَ",uz:"yoki ehtimol, bundan foydalanarlar"},{ar:"لِصَرْفِ أَنْظَارِ رَعَايَاهُمْ",uz:"fuqarolarining diqqatini chalg‘itish uchun"}],full_uz:"Yoki fuqarolarining diqqatini chalg‘itish uchun bundan foydalanarlar.",note:"صَرْفُ الْأَنْظَارِ — «diqqatni boshqa tomonga burish». رَعَايَا — رَعِيَّةٌ («fuqarolar, tobe aholi»)ning ko‘pligi."},
{num:126,time:"00:09:49,620 --> 00:09:52,280",arabic:"فَنَقَلُوا الْمَعْرَكَةَ إِلَى الثُّغُورِ.",segs:[{ar:"فَنَقَلُوا الْمَعْرَكَةَ",uz:"va jangni ko‘chirarlar"},{ar:"إِلَى الثُّغُورِ",uz:"chegara hududlariga"}],full_uz:"Va jangni chegara hududlariga ko‘chirarlar.",note:null},
{num:127,time:"00:09:52,280 --> 00:09:58,920",arabic:"الرُّومُ أَجْبَنُ مِنْ ذَلِكَ يَا ابْنَ الرَّبِيعِ.",segs:[{ar:"الرُّومُ أَجْبَنُ مِنْ ذَلِكَ",uz:"rumliklar buni qilishga haddan ziyod qo‘rqoq"},{ar:"يَا ابْنَ الرَّبِيعِ",uz:"ey Ibn Rabi’"}],full_uz:"Rumliklar bunday qilishga haddan ziyod qo‘rqoq, Ibn Rabi’.",note:"أَجْبَنُ مِنْ ذَلِكَ — so‘zma-so‘z «bundan qo‘rqoqroq», ya’ni bunday ishga jur’at qilmaydi."},
{num:128,time:"00:10:05,340 --> 00:10:13,920",arabic:"اِسْمَعْ يَا أَبَا عَبْدِ اللَّهِ.",segs:[{ar:"اِسْمَعْ",uz:"eshiting"},{ar:"يَا أَبَا عَبْدِ اللَّهِ",uz:"ey Abu Abdulloh"}],full_uz:"Eshiting, Abu Abdulloh.",note:"أَبُو izofali munodo bo‘lganda nasb holatida أَبَا shaklini oladi."},
{num:129,time:"00:10:13,920 --> 00:10:19,560",arabic:"لَقَدْ عَزَمْتُ الْخُرُوجَ حَجًّا إِلَى مَكَّةَ، شَرَّفَهَا اللَّهُ، إِنْ شَاءَ اللَّهُ.",segs:[{ar:"لَقَدْ عَزَمْتُ الْخُرُوجَ",uz:"yo‘lga chiqishga qaror qildim"},{ar:"حَجًّا إِلَى مَكَّةَ",uz:"haj uchun Makkaga"},{ar:"شَرَّفَهَا اللَّهُ",uz:"Alloh uning sharafini ziyoda qilsin"},{ar:"إِنْ شَاءَ اللَّهُ",uz:"Alloh xohlasa"}],full_uz:"Alloh xohlasa, haj uchun Makkaga yo‘lga chiqishga qaror qildim. Alloh uning sharafini ziyoda qilsin.",note:"عَزَمَ — «qat’iy qaror qildi». حَجًّا bu yerda chiqishning maqsadini bildiradi."},
{num:130,time:"00:10:19,560 --> 00:10:24,340",arabic:"تَذَكَّرْ أَنَّكَ وَعَدْتَنِي أَنْ نَخْرُجَ سَوِيًّا.",segs:[{ar:"تَذَكَّرْ",uz:"eslang"},{ar:"أَنَّكَ وَعَدْتَنِي",uz:"siz menga va’da bergandingiz"},{ar:"أَنْ نَخْرُجَ سَوِيًّا",uz:"birga yo‘lga chiqishimizni"}],full_uz:"Birga yo‘lga chiqishga menga va’da berganingizni eslang.",note:"سَوِيًّا — «birga». وَعَدْتَنِي — «menga va’da berdingiz»."},
{num:131,time:"00:10:24,340 --> 00:10:26,860",arabic:"نَحُجُّ بَيْتَ اللَّهِ.",segs:null,full_uz:"Allohning Baytini haj qilamiz.",note:null},
{num:132,time:"00:10:26,860 --> 00:10:30,340",arabic:"وَنَنْقَطِعُ إِلَى الْإِمَامِ سُفْيَانَ بْنِ عُيَيْنَةَ.",segs:[{ar:"وَنَنْقَطِعُ إِلَى",uz:"va o‘zimizni bag‘ishlaymiz"},{ar:"الْإِمَامِ سُفْيَانَ بْنِ عُيَيْنَةَ",uz:"imom Sufyon ibn Uyaynaning huzuridagi ta’limga"}],full_uz:"Va o‘zimizni imom Sufyon ibn Uyayna huzurida ta’lim olishga bag‘ishlaymiz.",note:"اِنْقَطَعَ إِلَى شَخْصٍ — «o‘zini uning suhbatiga yoki undan ta’lim olishga bag‘ishladi»."},
{num:133,time:"00:10:30,340 --> 00:10:31,340",arabic:"مَا رَأْيُكَ؟",segs:null,full_uz:"Fikringiz qanday?",note:null},
{num:134,time:"00:10:32,180 --> 00:10:33,960",arabic:"كُلُّ شَيْءٍ بِقَدَرٍ يَا ابْنَ مَعِينٍ.",segs:[{ar:"كُلُّ شَيْءٍ بِقَدَرٍ",uz:"har bir narsa taqdir bilan"},{ar:"يَا ابْنَ مَعِينٍ",uz:"ey Ibn Ma’in"}],full_uz:"Har bir narsa taqdir bilan, Ibn Ma’in.",note:null},
{num:135,time:"00:10:33,960 --> 00:10:36,460",arabic:"وَإِلَى أَنْ يَأْتِيَ مَوْعِدُهُ، إِنْ شَاءَ اللَّهُ...",segs:[{ar:"وَإِلَى أَنْ يَأْتِيَ مَوْعِدُهُ",uz:"uning vaqti kelguniga qadar"},{ar:"إِنْ شَاءَ اللَّهُ",uz:"Alloh xohlasa"}],full_uz:"Uning vaqti kelguniga qadar, Alloh xohlasa...",note:"إِلَى أَنْ + fe’l — «...guniga qadar». يَأْتِيَ — أَنْ sababli mansub."},
{num:136,time:"00:10:36,460 --> 00:10:38,879",arabic:"يَخْلُقُ اللَّهُ مَا لَا نَعْلَمُهُ.",segs:[{ar:"يَخْلُقُ اللَّهُ",uz:"Alloh yaratadi"},{ar:"مَا لَا نَعْلَمُهُ",uz:"biz bilmaydigan narsalarni"}],full_uz:"Alloh biz bilmaydigan narsalarni yaratadi.",note:null},
{num:137,time:"00:10:38,879 --> 00:11:01,940",arabic:"يَبْدُو أَنَّ نِقْفُورَ هَذَا قَدِ اسْتَأْثَرَ بِالْحُكْمِ دُونَ بَاقِي أُمَرَاءِ الرُّومِ.",segs:[{ar:"يَبْدُو أَنَّ نِقْفُورَ هَذَا",uz:"aftidan, bu Niqfur"},{ar:"قَدِ اسْتَأْثَرَ بِالْحُكْمِ",uz:"hokimiyatni o‘z qo‘liga olgan"},{ar:"دُونَ بَاقِي أُمَرَاءِ الرُّومِ",uz:"boshqa rum amirlarini chetda qoldirib"}],full_uz:"Aftidan, bu Niqfur boshqa rum amirlarini chetda qoldirib, hokimiyatni o‘z qo‘liga olgan.",note:"اِسْتَأْثَرَ بِـ — «yolg‘iz o‘zi egallab oldi». دُونَ bu yerda «boshqalarni chetda qoldirib» ma’nosida."},
{num:138,time:"00:11:01,940 --> 00:11:05,780",arabic:"سَمِعْتُ مِنْ رُومِيٍّ مُسْلِمٍ مِنْ سُكَّانِ بَغْدَادَ، حَمَاهَا اللَّهُ...",segs:[{ar:"سَمِعْتُ مِنْ رُومِيٍّ مُسْلِمٍ",uz:"bir musulmon rumlikdan eshitdim"},{ar:"مِنْ سُكَّانِ بَغْدَادَ",uz:"Bag‘dod aholisidan bo‘lgan"},{ar:"حَمَاهَا اللَّهُ",uz:"Alloh uni asrasin"}],full_uz:"Bag‘dodda yashovchi bir musulmon rumlikdan eshitdim. Alloh Bag‘dodni asrasin...",note:"سُكَّانٌ — «aholi, yashovchilar». حَمَاهَا dagi هَا Bag‘dodga ishora qiladi."},
{num:139,time:"00:11:05,780 --> 00:11:11,020",arabic:"أَنَّ نِقْفُورَ هَذَا مِنْ أَوْلَادِ جَفْنَةَ مِنْ غَسَّانَ، قَحْطَانِيُّ الْأَرُومَةِ.",segs:[{ar:"أَنَّ نِقْفُورَ هَذَا",uz:"bu Niqfur"},{ar:"مِنْ أَوْلَادِ جَفْنَةَ",uz:"Jafna avlodidan ekanini"},{ar:"مِنْ غَسَّانَ",uz:"G‘assondan"},{ar:"قَحْطَانِيُّ الْأَرُومَةِ",uz:"nasli qahtoniy"}],full_uz:"Bu Niqfur G‘assondagi Jafna avlodidan, nasli qahtoniy ekanini.",note:"أَرُومَةٌ — «asl, nasl, ildiz». قَحْطَانِيُّ الْأَرُومَةِ — «nasli Qahtonga borib taqaladigan»."},
{num:140,time:"00:11:11,020 --> 00:11:17,660",arabic:"أَيُعْقَلُ أَنْ يَرْضَى بَنُو الْأَصْفَرِ مِنَ الرُّومِ أَنْ يُوَلُّوا عَلَيْهِمْ مَلِكًا مِنْ أَصْلٍ عَرَبِيٍّ؟",segs:[{ar:"أَيُعْقَلُ",uz:"aqlga sig‘adimi"},{ar:"أَنْ يَرْضَى بَنُو الْأَصْفَرِ مِنَ الرُّومِ",uz:"rumlik Banu Asfarning rozi bo‘lishi"},{ar:"أَنْ يُوَلُّوا عَلَيْهِمْ مَلِكًا",uz:"ustilariga podshoh tayinlashga"},{ar:"مِنْ أَصْلٍ عَرَبِيٍّ؟",uz:"kelib chiqishi arab bo‘lgan?"}],full_uz:"Rumlik Banu Asfarning o‘zlariga kelib chiqishi arab bo‘lgan podshohni tayinlashga rozi bo‘lishi aqlga sig‘adimi?",note:"بَنُو الْأَصْفَرِ — rumliklarga nisbatan ishlatilgan tarixiy nom. وَلَّى عَلَيْهِمْ — «ular ustidan boshliq qilib tayinladi»."},
{num:141,time:"00:11:17,660 --> 00:11:20,320",arabic:"يُقَالُ إِنَّهُ دَاهِيَةٌ لَا يُشَقُّ لَهُ غُبَارٌ.",segs:[{ar:"يُقَالُ إِنَّهُ دَاهِيَةٌ",uz:"uni juda ayyor deyishadi"},{ar:"لَا يُشَقُّ لَهُ غُبَارٌ",uz:"unga hech kim teng kela olmaydi"}],full_uz:"Uni tengi yo‘q ayyor deyishadi.",note:"لَا يُشَقُّ لَهُ غُبَارٌ — «unga yetib bo‘lmaydi, tengi yo‘q» degan ibora; asl tasvir poygada uning changiga ham yetolmaslik."},
{num:142,time:"00:11:28,680 --> 00:11:31,180",arabic:"غَدًا صَبَاحًا.",segs:null,full_uz:"Ertaga ertalab.",note:null},
{num:143,time:"00:11:31,180 --> 00:11:34,040",arabic:"جَهِّزْ لِي مَوْكِبِي.",segs:null,full_uz:"Men uchun safar mulozimlarimni tayyorlang.",note:"مَوْكِبٌ — hukmdorga hamroh bo‘ladigan otliq va mulozimlar yurishi, tantanali safar guruhi."},
{num:144,time:"00:11:34,040 --> 00:11:38,800",arabic:"أُرِيدُ أَنْ أَذْهَبَ لِتَفَقُّدِ الثُّغُورِ.",segs:[{ar:"أُرِيدُ أَنْ أَذْهَبَ",uz:"bormoqchiman"},{ar:"لِتَفَقُّدِ الثُّغُورِ",uz:"chegara istehkomlarini ko‘zdan kechirish uchun"}],full_uz:"Chegara istehkomlarini ko‘zdan kechirish uchun bormoqchiman.",note:"تَفَقُّدٌ — joy yoki kishilarning holatini tekshirish, ko‘zdan kechirish."},
{num:145,time:"00:11:50,320 --> 00:12:05,600",arabic:"لَمْ تَقُلْ لِي اسْمَ الْفَتَاةِ.",segs:[{ar:"لَمْ تَقُلْ لِي",uz:"menga aytmadingiz"},{ar:"اسْمَ الْفَتَاةِ",uz:"qizning ismini"}],full_uz:"Menga qizning ismini aytmadingiz.",note:null},
{num:146,time:"00:12:05,600 --> 00:12:10,500",arabic:"رَغَدٌ، اسْمُهَا رَغَدٌ، وَهُوَ مُدَوَّنٌ عِنْدَكَ فِي صَكِّ مِلْكِيَّتِهَا.",segs:[{ar:"رَغَدٌ، اسْمُهَا رَغَدٌ",uz:"Rag‘ad, uning ismi Rag‘ad"},{ar:"وَهُوَ مُدَوَّنٌ عِنْدَكَ",uz:"u sizdagi hujjatda yozilgan"},{ar:"فِي صَكِّ مِلْكِيَّتِهَا",uz:"unga egalik qilish hujjatida"}],full_uz:"Rag‘ad, uning ismi Rag‘ad. Bu sizdagi unga egalik qilish hujjatida yozilgan.",note:"صَكٌّ — «rasmiy hujjat». مُدَوَّنٌ — «qayd etilgan, yozib qo‘yilgan»."},
{num:147,time:"00:12:10,500 --> 00:12:15,920",arabic:"لَكِنَّهَا فِي لَحَظَاتِ جُنُونِهَا الْقَلِيلَةِ تَعْتَقِدُ أَنَّ اسْمَهَا فَوْزٌ.",segs:[{ar:"لَكِنَّهَا",uz:"lekin u"},{ar:"فِي لَحَظَاتِ جُنُونِهَا الْقَلِيلَةِ",uz:"kamdan kam tutadigan telbalik paytlarida"},{ar:"تَعْتَقِدُ أَنَّ اسْمَهَا فَوْزٌ",uz:"ismini Favz deb o‘ylaydi"}],full_uz:"Lekin kamdan kam tutadigan telbalik paytlarida u ismini Favz deb o‘ylaydi.",note:"اِعْتَقَدَ أَنَّ — «...deb o‘yladi, ishondi». Bu gap personajning boshqa kishi haqidagi da’vosini ifodalaydi."},
{num:148,time:"00:12:15,919 --> 00:12:20,339",arabic:"أَظُنُّ، وَاللَّهُ أَعْلَمُ، أَنَّهَا كَانَتْ تَعْرِفُ فَتَاةً بِهَذَا الِاسْمِ.",segs:[{ar:"أَظُنُّ",uz:"menimcha"},{ar:"وَاللَّهُ أَعْلَمُ",uz:"Alloh yaxshiroq biladi"},{ar:"أَنَّهَا كَانَتْ تَعْرِفُ فَتَاةً",uz:"u bir qizni tanigan"},{ar:"بِهَذَا الِاسْمِ",uz:"shu ismli"}],full_uz:"Menimcha, Alloh yaxshiroq biladi, u shu ismli bir qizni tanigan.",note:"وَاللَّهُ أَعْلَمُ — «Alloh yaxshiroq biladi», fikr qat’iy emasligini bildiruvchi kirish iborasi."},
{num:149,time:"00:12:20,339 --> 00:12:23,979",arabic:"وَتَتَمَنَّى أَنْ تَكُونَ مَكَانَهَا فِي كُلِّ شَيْءٍ.",segs:[{ar:"وَتَتَمَنَّى أَنْ تَكُونَ مَكَانَهَا",uz:"va uning o‘rnida bo‘lishni orzu qiladi"},{ar:"فِي كُلِّ شَيْءٍ",uz:"har jihatdan"}],full_uz:"Va har jihatdan uning o‘rnida bo‘lishni orzu qiladi.",note:null},
{num:150,time:"00:12:27,679 --> 00:12:28,740",arabic:"لَا بَأْسَ.",segs:null,full_uz:"Mayli.",note:null},
{num:151,time:"00:12:28,740 --> 00:12:31,899",arabic:"أَشْكُرُكَ لِأَنَّكَ لَفَتَّ نَظَرِي إِلَى هَذَا الْأَمْرِ.",segs:[{ar:"أَشْكُرُكَ",uz:"sizga rahmat aytaman"},{ar:"لِأَنَّكَ لَفَتَّ نَظَرِي",uz:"diqqatimni qaratganingiz uchun"},{ar:"إِلَى هَذَا الْأَمْرِ",uz:"bu masalaga"}],full_uz:"Diqqatimni bu masalaga qaratganingiz uchun rahmat.",note:"لَفَتَ نَظَرَ شَخْصٍ إِلَى شَيْءٍ — «birovning diqqatini biror narsaga qaratdi»."},
{num:152,time:"00:12:31,899 --> 00:12:34,299",arabic:"فَهَكَذَا أَعْرِفُ كَيْفَ أُعَامِلُهَا.",segs:[{ar:"فَهَكَذَا أَعْرِفُ",uz:"shunday qilib bilaman"},{ar:"كَيْفَ أُعَامِلُهَا",uz:"unga qanday muomala qilishni"}],full_uz:"Shunday qilib, unga qanday muomala qilishni bilaman.",note:"عَامَلَ — يُعَامِلُ — «muomala qilmoq». أُعَامِلُهَا — «unga muomala qilaman»."},
{num:153,time:"00:12:34,299 --> 00:12:39,939",arabic:"وَالْآنَ هَلْ أَسْتَطِيعُ أَنْ آخُذَهَا وَنَذْهَبَ؟",segs:[{ar:"وَالْآنَ",uz:"endi"},{ar:"هَلْ أَسْتَطِيعُ أَنْ آخُذَهَا",uz:"uni olishim mumkinmi"},{ar:"وَنَذْهَبَ؟",uz:"va ketishimiz?"}],full_uz:"Endi uni olib ketsak bo‘ladimi?",note:"آخُذُ — «men olaman». أَنْ dan keyin آخُذَ shaklida mansub bo‘ladi."},
{num:154,time:"00:12:39,939 --> 00:12:41,139",arabic:"حَتْمًا، بِالتَّأْكِيدِ.",segs:null,full_uz:"Albatta, shubhasiz.",note:null},
{num:155,time:"00:12:41,139 --> 00:12:46,639",arabic:"حَنْظَلَةُ، قُلْ لِرَغَدٍ أَنْ تُجَهِّزَ نَفْسَهَا لِكَيْ تَذْهَبَ مَعَ سَيِّدِهَا إِلَى بَيْتِهِ.",segs:[{ar:"حَنْظَلَةُ",uz:"Hanzala"},{ar:"قُلْ لِرَغَدٍ",uz:"Rag‘adga ayting"},{ar:"أَنْ تُجَهِّزَ نَفْسَهَا",uz:"o‘zini tayyorlasin"},{ar:"لِكَيْ تَذْهَبَ",uz:"borishi uchun"},{ar:"مَعَ سَيِّدِهَا",uz:"xo‘jayini bilan"},{ar:"إِلَى بَيْتِهِ",uz:"uning uyiga"}],full_uz:"Hanzala, Rag‘adga ayting, xo‘jayini bilan uning uyiga borish uchun tayyorlansin.",note:"جَهَّزَ نَفْسَهُ — «tayyorlandi». لِكَيْ maqsadni bildiradi: «...ishi uchun»."},
{num:156,time:"00:12:46,639 --> 00:13:10,840",arabic:"هَيَّا يَا فَوْزُ.",segs:[{ar:"هَيَّا",uz:"qani, yuring"},{ar:"يَا فَوْزُ",uz:"ey Favz"}],full_uz:"Qani, yuring, Favz.",note:null},
{num:157,time:"00:13:10,840 --> 00:13:13,240",arabic:"لَقَدْ حَانَ مَوْعِدُ رَحِيلِكِ.",segs:[{ar:"لَقَدْ حَانَ",uz:"yetib keldi"},{ar:"مَوْعِدُ رَحِيلِكِ",uz:"ketishingizning vaqti"}],full_uz:"Ketishingizning vaqti yetib keldi.",note:"حَانَ الْوَقْتُ — «vaqt yetdi». رَحِيلٌ — «jo‘nab ketish»."},
{num:158,time:"00:13:13,240 --> 00:13:19,120",arabic:"لَوْ تَعْلَمِينَ كَمْ أَنَا حَزِينٌ لِفِرَاقِكِ يَا فَوْزُ!",segs:[{ar:"لَوْ تَعْلَمِينَ",uz:"qaniydi bilsangiz"},{ar:"كَمْ أَنَا حَزِينٌ",uz:"qanchalik qayg‘udaman"},{ar:"لِفِرَاقِكِ",uz:"sizdan ayrilayotganimdan"},{ar:"يَا فَوْزُ",uz:"ey Favz"}],full_uz:"Sizdan ayrilayotganimdan qanchalik qayg‘uda ekanimni qaniydi bilsangiz, Favz!",note:"لَوْ تَعْلَمِينَ bu yerda «qaniydi bilsangiz» ma’nosida. كَمْ qayg‘uning darajasini bildiradi."},
{num:159,time:"00:13:19,120 --> 00:13:24,240",arabic:"حَزِينٌ كَسَعَادَتِي لِخَلَاصِكِ مِنْ هَذَا الْبَيْتِ وَزَوْجِي زُمُرُّدَةَ.",segs:[{ar:"حَزِينٌ كَسَعَادَتِي",uz:"quvonchim darajasida qayg‘udaman"},{ar:"لِخَلَاصِكِ",uz:"qutulayotganingizdan"},{ar:"مِنْ هَذَا الْبَيْتِ",uz:"bu uydan"},{ar:"وَزَوْجِي زُمُرُّدَةَ",uz:"va xotinim Zumraddan"}],full_uz:"Bu uydan va xotinim Zumraddan qutulayotganingizdan qanchalik quvonsam, shunchalik qayg‘udaman.",note:"زَوْجٌ klassik arabchada erga ham, xotinga ham nisbatan ishlatiladi. خَلَاصٌ — «qutulish»."},
{num:160,time:"00:13:24,240 --> 00:13:26,360",arabic:"لَقَدْ أَحْبَبْتُكِ كَأُخْتٍ لِي.",segs:[{ar:"لَقَدْ أَحْبَبْتُكِ",uz:"sizni yaxshi ko‘rdim"},{ar:"كَأُخْتٍ لِي",uz:"o‘z singlimdek"}],full_uz:"Sizni o‘z singlimdek yaxshi ko‘rdim.",note:null},
{num:161,time:"00:13:26,360 --> 00:13:30,899",arabic:"لَكِنَّ خَوْفِيَ الْجَبَانَ هُوَ مَنْ مَنَعَنِي مِنَ الْبَوْحِ.",segs:[{ar:"لَكِنَّ خَوْفِيَ الْجَبَانَ",uz:"lekin qo‘rqoqona qo‘rquvim"},{ar:"هُوَ مَنْ مَنَعَنِي",uz:"aynan meni to‘sdi"},{ar:"مِنَ الْبَوْحِ",uz:"ochiq aytishdan"}],full_uz:"Lekin qo‘rqoqona qo‘rquvim meni buni ochiq aytishdan to‘sdi.",note:"مَنَعَ مِنْ — «...dan to‘sdi». بَوْحٌ — ichidagi gapni yoki sirni ochiq aytish."},
{num:162,time:"00:13:30,899 --> 00:13:33,060",arabic:"وَلَجَمَ لِسَانِي كُلَّ هَذِهِ السَّنَوَاتِ.",segs:[{ar:"وَلَجَمَ لِسَانِي",uz:"va tilimni tiydi"},{ar:"كُلَّ هَذِهِ السَّنَوَاتِ",uz:"shu yillarning barchasida"}],full_uz:"Va shu yillarning barchasida tilimni tiydi.",note:"لَجَمَ aslida «yugan soldi». لَجَمَ لِسَانَهُ ko‘chma ma’noda «tilini tiydi, gapirtirmadi»."},
{num:163,time:"00:13:33,060 --> 00:13:37,779",arabic:"كُلُّ مَا أَتَمَنَّاهُ أَنْ تُسَامِحِينِي عَلَى مَا فَعَلْنَاهُ بِكِ.",segs:[{ar:"كُلُّ مَا أَتَمَنَّاهُ",uz:"butun istagim"},{ar:"أَنْ تُسَامِحِينِي",uz:"meni kechirishingiz"},{ar:"عَلَى مَا فَعَلْنَاهُ بِكِ",uz:"sizga qilgan ishlarimiz uchun"}],full_uz:"Butun istagim — sizga qilgan ishlarimiz uchun meni kechirishingiz.",note:"تُسَامِحِينِي tarkibida أَنْ sababli raf’ nuni tushgan, lekin «meni» qo‘shimchasidagi himoya nuni saqlangan."},
{num:164,time:"00:13:37,779 --> 00:13:39,100",arabic:"لَا تُكْمِلْ.",segs:null,full_uz:"Davom ettirmang.",note:null},
{num:165,time:"00:13:39,100 --> 00:13:43,700",arabic:"كَانَتْ أَفْعَالُكَ تُخْبِرُنِي بِمَا تُكِنُّهُ لِي مِنْ شَفَقَةٍ وَحَنَانٍ.",segs:[{ar:"كَانَتْ أَفْعَالُكَ تُخْبِرُنِي",uz:"qilgan ishlaringiz menga bildirardi"},{ar:"بِمَا تُكِنُّهُ لِي",uz:"menga nisbatan ichingizda saqlagan narsangizni"},{ar:"مِنْ شَفَقَةٍ وَحَنَانٍ",uz:"rahm-shafqat va mehrni"}],full_uz:"Qilgan ishlaringiz menga nisbatan ichingizda saqlagan rahm-shafqat va mehringizni bildirardi.",note:"أَكَنَّ — يُكِنُّ — «ichida yashirdi, saqladi». تُكِنُّهُ لِي — «menga nisbatan qalbingizda saqlaysiz»."},
{num:166,time:"00:13:43,700 --> 00:13:47,080",arabic:"لَنْ أَنْسَى مَا قَدَّمْتَهُ لِي أَبَدًا.",segs:[{ar:"لَنْ أَنْسَى",uz:"unutmayman"},{ar:"مَا قَدَّمْتَهُ لِي",uz:"men uchun qilganlaringizni"},{ar:"أَبَدًا",uz:"hech qachon"}],full_uz:"Men uchun qilganlaringizni hech qachon unutmayman.",note:"لَنْ kelasi zamondagi inkorni bildiradi. أَنْسَى fe’lining nasb belgisi oxirgi alifda ko‘rinmaydi."},
{num:167,time:"00:13:47,080 --> 00:13:53,120",arabic:"وَلَكِنْ إِنْ أَرَدْتَ نَصِيحَتِي...",segs:[{ar:"وَلَكِنْ",uz:"lekin"},{ar:"إِنْ أَرَدْتَ نَصِيحَتِي",uz:"maslahatimni istasangiz"}],full_uz:"Lekin maslahatimni istasangiz...",note:null},
{num:168,time:"00:13:53,120 --> 00:13:56,379",arabic:"لَا تَجْعَلِ الْخَوْفَ يَغْتَالُ قَلْبَكَ الطَّيِّبَ.",segs:[{ar:"لَا تَجْعَلِ الْخَوْفَ",uz:"qo‘rquvga yo‘l qo‘ymang"},{ar:"يَغْتَالُ قَلْبَكَ الطَّيِّبَ",uz:"mehribon qalbingizni o‘ldirishiga"}],full_uz:"Qo‘rquv mehribon qalbingizni o‘ldirishiga yo‘l qo‘ymang.",note:"اِغْتَالَ — «yashirincha o‘ldirdi»; bu yerda ko‘chma ma’noda. تَجْعَلْ tutashtirib o‘qilganda تَجْعَلِ bo‘ladi."},
{num:169,time:"00:13:56,379 --> 00:13:59,740",arabic:"فَآفَةُ الرِّجَالِ الْخَوْفُ.",segs:[{ar:"فَآفَةُ الرِّجَالِ",uz:"chunki erkaklarning ofati"},{ar:"الْخَوْفُ",uz:"qo‘rquvdir"}],full_uz:"Chunki erkaklarning ofati qo‘rquvdir.",note:"آفَةٌ — «ofat, halokatga yoki buzilishga sabab bo‘luvchi narsa»."},
{num:170,time:"00:13:59,740 --> 00:14:00,980",arabic:"هَيَّا يَا حَنْظَلَةُ.",segs:[{ar:"هَيَّا",uz:"qani, yuring"},{ar:"يَا حَنْظَلَةُ",uz:"ey Hanzala"}],full_uz:"Qani, yuring, Hanzala.",note:null},
{num:171,time:"00:14:00,980 --> 00:14:04,000",arabic:"لَا نُرِيدُ أَنْ نُؤَخِّرَ السَّيِّدَ أَكْثَرَ مِنْ هَذَا.",segs:[{ar:"لَا نُرِيدُ أَنْ نُؤَخِّرَ السَّيِّدَ",uz:"xo‘jayinni kutdirishni istamaymiz"},{ar:"أَكْثَرَ مِنْ هَذَا",uz:"bundan ortiq"}],full_uz:"Xo‘jayinni bundan ortiq kutdirishni istamaymiz.",note:"أَخَّرَ — «kechiktirdi, kutdirdi». تَأَخَّرَ esa «kechikdi»."},
{num:172,time:"00:14:04,000 --> 00:14:10,200",arabic:"كُلُّ مَا أَتَمَنَّاهُ أَنْ يُعَوِّضَكِ اللَّهُ عَنْ بُؤْسِ أَيَّامِكِ مَعَنَا.",segs:[{ar:"كُلُّ مَا أَتَمَنَّاهُ",uz:"butun tilagim"},{ar:"أَنْ يُعَوِّضَكِ اللَّهُ",uz:"Alloh sizga evazini bersin"},{ar:"عَنْ بُؤْسِ أَيَّامِكِ",uz:"og‘ir kunlaringizning"},{ar:"مَعَنَا",uz:"biz bilan o‘tgan"}],full_uz:"Butun tilagim — Alloh biz bilan o‘tgan og‘ir kunlaringizning o‘rniga sizga yaxshilik bersin.",note:"عَوَّضَ شَخْصًا عَنْ شَيْءٍ — «birovga biror narsaning o‘rnini qopladi, evaz berdi». بُؤْسٌ — «og‘ir turmush, baxtsizlik»."},
{num:173,time:"00:14:10,200 --> 00:14:11,940",arabic:"حَمَاكِ اللَّهُ.",segs:null,full_uz:"Alloh sizni asrasin.",note:null},
{num:174,time:"00:14:11,940 --> 00:14:13,539",arabic:"هَيَّا بِنَا.",segs:null,full_uz:"Qani, ketdik.",note:null},
{num:175,time:"00:14:14,360 --> 00:14:20,559",arabic:"إِنَّ الْقُرْآنَ مَخْلُوقٌ.",segs:null,full_uz:"Albatta, Qur’on yaratilgandir.",note:"مَخْلُوقٌ — خَلَقَ fe’lining ismi maf’uli: «yaratilgan». Bu jumlada so‘zlovchining qarashi bayon qilinmoqda."},
{num:176,time:"00:14:20,559 --> 00:14:23,740",arabic:"خَلَقَهُ اللَّهُ فِي نَفْسِ جِبْرِيلَ.",segs:[{ar:"خَلَقَهُ اللَّهُ",uz:"uni Alloh yaratgan"},{ar:"فِي نَفْسِ جِبْرِيلَ",uz:"Jabroilning ichida"}],full_uz:"Uni Alloh Jabroilning ichida yaratgan.",note:"نَفْسٌ bu yerda «ichki olam, ich» ma’nosida."},
{num:177,time:"00:14:23,740 --> 00:14:28,740",arabic:"فَنَقَلَ جِبْرِيلُ مَا خُلِقَ فِي نَفْسِهِ.",segs:[{ar:"فَنَقَلَ جِبْرِيلُ",uz:"so‘ng Jabroil yetkazgan"},{ar:"مَا خُلِقَ فِي نَفْسِهِ",uz:"o‘z ichida yaratilgan narsani"}],full_uz:"So‘ng Jabroil o‘z ichida yaratilgan narsani yetkazgan.",note:"خُلِقَ — majhul nisbat: «yaratildi»; خَلَقَ — «yaratdi»."},
{num:178,time:"00:14:28,740 --> 00:14:30,899",arabic:"فَأَلْقَاهُ إِلَى الرَّسُولِ.",segs:[{ar:"فَأَلْقَاهُ",uz:"so‘ng uni yetkazgan"},{ar:"إِلَى الرَّسُولِ",uz:"Rasulga"}],full_uz:"So‘ng uni Rasulga yetkazgan.",note:"أَلْقَى إِلَى bu yerda «yetkazdi, bayon qildi» ma’nosida."},
{num:179,time:"00:14:30,899 --> 00:14:37,899",arabic:"فَكَانَ دَلَالَةً لَنَا عَلَى الْأَحْكَامِ لِنَرْجِعَ إِلَيْهِ فِي الْحَلَالِ وَالْحَرَامِ.",segs:[{ar:"فَكَانَ دَلَالَةً لَنَا",uz:"shunday qilib, biz uchun ko‘rsatma bo‘lgan"},{ar:"عَلَى الْأَحْكَامِ",uz:"hukmlarga oid"},{ar:"لِنَرْجِعَ إِلَيْهِ",uz:"unga murojaat qilishimiz uchun"},{ar:"فِي الْحَلَالِ وَالْحَرَامِ",uz:"halol va harom masalalarida"}],full_uz:"Shunday qilib, halol va harom masalalarida unga murojaat qilishimiz uchun bizga hukmlarni ko‘rsatuvchi bo‘lgan.",note:"رَجَعَ إِلَى manba bilan ishlatilganda «murojaat qildi» degani. لِنَرْجِعَ — «murojaat qilishimiz uchun»."},
{num:180,time:"00:14:38,579 --> 00:14:43,899",arabic:"إِنَّ الْقُرْآنَ يُخْلَقُ فِي أَحْوَالٍ مُخْتَلِفَةٍ.",segs:[{ar:"إِنَّ الْقُرْآنَ يُخْلَقُ",uz:"albatta, Qur’on yaratiladi"},{ar:"فِي أَحْوَالٍ مُخْتَلِفَةٍ",uz:"turli holatlarda"}],full_uz:"Albatta, Qur’on turli holatlarda yaratiladi.",note:"يُخْلَقُ — majhul nisbatdagi muzoriy: «yaratiladi». أَحْوَالٌ — حَالٌ so‘zining ko‘pligi."},
{num:181,time:"00:14:44,620 --> 00:14:51,240",arabic:"مِنْ جِهَةِ تَكْلِيمِ مُوسَى، خَلَقَ اللَّهُ الْكَلَامَ فِي الشَّجَرَةِ.",segs:[{ar:"مِنْ جِهَةِ تَكْلِيمِ مُوسَى",uz:"Musoga gapirish masalasida"},{ar:"خَلَقَ اللَّهُ الْكَلَامَ",uz:"Alloh kalomni yaratgan"},{ar:"فِي الشَّجَرَةِ",uz:"daraxtda"}],full_uz:"Musoga gapirish masalasida, Alloh kalomni daraxtda yaratgan.",note:"تَكْلِيمٌ — كَلَّمَ («gapirdi, so‘zladi») fe’lining masdari. Bu izofada مُوسَى gapirilgan kishini bildiradi."},
{num:182,time:"00:14:51,240 --> 00:14:52,899",arabic:"أَيْنَ خَلَقَهُ؟",segs:null,full_uz:"Uni qayerda yaratgan?",note:null},
{num:183,time:"00:14:52,899 --> 00:14:54,519",arabic:"فِي الشَّجَرَةِ.",segs:null,full_uz:"Daraxtda.",note:null},
{num:184,time:"00:14:54,519 --> 00:15:02,639",arabic:"لَقَدْ خَرَجْنَا وَأَنْتِ لَمْ تَنْبِسِي بِبِنْتِ شَفَةٍ.",segs:[{ar:"لَقَدْ خَرَجْنَا",uz:"chiqdik"},{ar:"وَأَنْتِ لَمْ تَنْبِسِي",uz:"siz esa og‘iz ochmadingiz"},{ar:"بِبِنْتِ شَفَةٍ",uz:"bir og‘iz so‘zga ham"}],full_uz:"Chiqdik, siz esa bir og‘iz ham gapirmadingiz.",note:"لَمْ يَنْبِسْ بِبِنْتِ شَفَةٍ — «bir og‘iz ham gapirmadi» degan turg‘un ibora. لَمْ تَنْبِسِي da jazm sababli ن tushgan."},
{num:185,time:"00:15:02,639 --> 00:15:05,480",arabic:"أَفَلَمْ تَسْأَلِي نَفْسَكِ لِمَ عُدْتُ؟",segs:[{ar:"أَفَلَمْ تَسْأَلِي نَفْسَكِ",uz:"o‘zingizdan so‘ramadingizmi"},{ar:"لِمَ عُدْتُ؟",uz:"nega qaytganimni?"}],full_uz:"Nega qaytganimni o‘zingizdan so‘ramadingizmi?",note:"لِمَ = لِـ + مَا: «nega?». عُدْتُ — «men qaytdim»; عُدْتَ — «siz qaytdingiz»."},
{num:186,time:"00:15:05,480 --> 00:15:08,939",arabic:"مُجَرَّدُ أَنَّكَ عُدْتَ، فَهَذَا يَعْنِي أَنَّكَ وَافَقْتَ.",segs:[{ar:"مُجَرَّدُ أَنَّكَ عُدْتَ",uz:"qaytganingizning o‘zi"},{ar:"فَهَذَا يَعْنِي",uz:"bu shuni anglatadi"},{ar:"أَنَّكَ وَافَقْتَ",uz:"rozi bo‘lganingizni"}],full_uz:"Qaytganingizning o‘zi rozi bo‘lganingizni anglatadi.",note:"مُجَرَّدُ أَنَّ... — «...ning o‘ziyoq». وَافَقَ — «rozi bo‘ldi»."},
{num:187,time:"00:15:08,939 --> 00:15:12,100",arabic:"لَنْ تَكُونِي فِي دَارِي إِلَّا عَزِيزَةً مُكَرَّمَةً.",segs:[{ar:"لَنْ تَكُونِي فِي دَارِي",uz:"mening uyimda bo‘lmaysiz"},{ar:"إِلَّا عَزِيزَةً مُكَرَّمَةً",uz:"faqat aziz va hurmatli holdan boshqa"}],full_uz:"Mening uyimda siz faqat aziz va hurmatli bo‘lasiz.",note:"لَنْ ... إِلَّا ... cheklashni bildiradi. تَكُونِي — لَنْ sababli ن tushgan mansub shakl."},
{num:188,time:"00:15:12,100 --> 00:15:14,980",arabic:"لَكِنْ إِنْ وَافَقْتِ أَنْتِ عَلَى شَرْطِي.",segs:[{ar:"لَكِنْ إِنْ وَافَقْتِ أَنْتِ",uz:"lekin o‘zingiz rozi bo‘lsangiz"},{ar:"عَلَى شَرْطِي",uz:"mening shartimga"}],full_uz:"Lekin siz ham mening shartimga rozi bo‘lsangiz.",note:"وَافَقَ عَلَى — «...ga rozi bo‘ldi». أَنْتِ olmoshi bu yerda murojaat qilinayotgan kishini ta’kidlaydi."},
{num:189,time:"00:15:14,980 --> 00:15:18,799",arabic:"مَا هُوَ شَرْطُكَ؟",segs:null,full_uz:"Shartingiz nima?",note:null},
{num:190,time:"00:15:19,799 --> 00:15:23,740",arabic:"أُخْتِي وَحِيدَتِي، وَهِيَ مَنْ تَبَقَّى لِي مِنْ عَائِلَتِي.",segs:[{ar:"أُخْتِي وَحِيدَتِي",uz:"singlim mening yagonam"},{ar:"وَهِيَ مَنْ تَبَقَّى لِي",uz:"menga qolgan yagona kishi u"},{ar:"مِنْ عَائِلَتِي",uz:"oilamdan"}],full_uz:"Singlim mening yagonam, oilamdan menga qolgan yagona kishi u.",note:"تَبَقَّى — «qoldi, qolgan bo‘ldi». مَنْ bu yerda «...gan kishi» ma’nosidagi nisbiy olmosh."},
{num:191,time:"00:15:23,740 --> 00:15:28,279",arabic:"أُرِيدُكِ أَنْ تَرْعَيْهَا وَتَهْتَمِّي بِكُلِّ مَا تَطْلُبُهُ مِنْكِ.",segs:[{ar:"أُرِيدُكِ أَنْ تَرْعَيْهَا",uz:"unga qarashingizni istayman"},{ar:"وَتَهْتَمِّي",uz:"va e’tibor berishingizni"},{ar:"بِكُلِّ مَا تَطْلُبُهُ مِنْكِ",uz:"u sizdan so‘raydigan hamma narsaga"}],full_uz:"Unga qarashingizni va sizdan so‘raydigan hamma narsaga e’tibor berishingizni istayman.",note:"تَرْعَيْهَا — ayol kishiga «unga qarashingiz». أَنْ sababli تَرْعَيْنَ shaklidagi ن tushadi."},
{num:192,time:"00:15:28,279 --> 00:15:31,620",arabic:"وَتُعَوِّضِيهَا عَنْ حَالِهَا حُبًّا وَحَنَانًا وَحُسْنَ رِعَايَةٍ.",segs:[{ar:"وَتُعَوِّضِيهَا عَنْ حَالِهَا",uz:"va ahvoli evaziga unga berishingizni"},{ar:"حُبًّا وَحَنَانًا",uz:"muhabbat va mehr"},{ar:"وَحُسْنَ رِعَايَةٍ",uz:"hamda yaxshi g‘amxo‘rlik"}],full_uz:"Va og‘ir ahvoli o‘rnini muhabbat, mehr hamda yaxshi g‘amxo‘rlik bilan qoplashingizni istayman.",note:"حُسْنُ رِعَايَةٍ — «yaxshi g‘amxo‘rlik». حُسْنٌ izofada keyingi ishning yaxshi bajarilishini bildiradi."},
{num:193,time:"00:15:31,620 --> 00:15:36,240",arabic:"فَإِنْ كَانَتْ سَعِيدَةً فَسَتَرَيْنَ السَّعَادَةَ.",segs:[{ar:"فَإِنْ كَانَتْ سَعِيدَةً",uz:"agar u baxtli bo‘lsa"},{ar:"فَسَتَرَيْنَ السَّعَادَةَ",uz:"siz ham baxt ko‘rasiz"}],full_uz:"Agar u baxtli bo‘lsa, siz ham baxt ko‘rasiz.",note:"سَتَرَيْنَ — ayol kishiga «siz ko‘rasiz». Shart javobi سَـ bilan boshlangani uchun oldidan فَ kelgan."},
{num:194,time:"00:15:36,240 --> 00:15:39,519",arabic:"وَإِنْ قَصَّرْتِ فِيمَا تَطْلُبُهُ مِنْكِ...",segs:[{ar:"وَإِنْ قَصَّرْتِ",uz:"agar kamchilik qilsangiz"},{ar:"فِيمَا تَطْلُبُهُ مِنْكِ",uz:"u sizdan so‘ragan narsalarda"}],full_uz:"Agar u sizdan so‘ragan narsalarni bajarishda kamchilik qilsangiz...",note:"قَصَّرَ فِي — «yetarlicha bajarmadi, beparvolik qildi»."},
{num:195,time:"00:15:39,519 --> 00:15:42,639",arabic:"حِينَهَا لَا أَعْلَمُ مَاذَا يُمْكِنُ أَنْ أَفْعَلَ.",segs:[{ar:"حِينَهَا لَا أَعْلَمُ",uz:"unda bilmayman"},{ar:"مَاذَا يُمْكِنُ أَنْ أَفْعَلَ",uz:"nima qilib qo‘yishim mumkinligini"}],full_uz:"Unda nima qilib qo‘yishim mumkinligini bilmayman.",note:null},
{num:196,time:"00:15:42,639 --> 00:15:46,180",arabic:"أَعِدُكَ أَنِّي لَنْ أَدَّخِرَ جُهْدًا لِأَجْلِهَا.",segs:[{ar:"أَعِدُكَ",uz:"sizga va’da beraman"},{ar:"أَنِّي لَنْ أَدَّخِرَ جُهْدًا",uz:"hech qanday kuchimni ayamasligimga"},{ar:"لِأَجْلِهَا",uz:"uning uchun"}],full_uz:"Uning uchun hech qanday kuchimni ayamaslikka sizga va’da beraman.",note:"لَا يَدَّخِرُ جُهْدًا — «kuchini ayamaydi, bor imkoniyatini ishga soladi»."},
{num:197,time:"00:16:23,740 --> 00:16:34,779",arabic:"أَلَمْ تَنَمْ بَعْدُ يَا فِرَاسُ؟",segs:[{ar:"أَلَمْ تَنَمْ بَعْدُ",uz:"hali uxlamadingizmi"},{ar:"يَا فِرَاسُ؟",uz:"ey Firos?"}],full_uz:"Hali uxlamadingizmi, Firos?",note:"Inkor bilan بَعْدُ — «hali». تَنَامُ fe’li لَمْ bilan jazm bo‘lganda تَنَمْ bo‘ladi."},
{num:198,time:"00:16:34,779 --> 00:16:36,779",arabic:"لَا يَا أُمِّي.",segs:[{ar:"لَا",uz:"yo‘q"},{ar:"يَا أُمِّي",uz:"ey onajon"}],full_uz:"Yo‘q, onajon.",note:null},
{num:199,time:"00:16:36,779 --> 00:16:38,419",arabic:"أَتُرِيدِينَ شَيْئًا؟",segs:null,full_uz:"Biror narsa istaysizmi?",note:null},
{num:200,time:"00:16:38,419 --> 00:16:41,600",arabic:"أَلَا يَكْفِيكَ الْعَمَلُ طِيلَةَ النَّهَارِ؟",segs:[{ar:"أَلَا يَكْفِيكَ الْعَمَلُ",uz:"ishlash sizga yetmaydimi"},{ar:"طِيلَةَ النَّهَارِ؟",uz:"kun bo‘yi?"}],full_uz:"Kun bo‘yi ishlashingiz yetmaydimi?",note:"طِيلَةَ النَّهَارِ — «kun bo‘yi». يَكْفِيكَ — «sizga yetadi»."},
{num:201,time:"00:16:41,600 --> 00:16:45,460",arabic:"لَا عَلَيْكِ، سَأَنْتَهِي بَعْدَ قَلِيلٍ.",segs:[{ar:"لَا عَلَيْكِ",uz:"xavotir olmang"},{ar:"سَأَنْتَهِي بَعْدَ قَلِيلٍ",uz:"birozdan keyin tugataman"}],full_uz:"Xavotir olmang, birozdan keyin tugataman.",note:"لَا عَلَيْكَ / لَا عَلَيْكِ — «tashvishlanmang, xavotir olmang»."},
{num:202,time:"00:16:45,460 --> 00:16:46,519",arabic:"تُصْبِحِينَ بِخَيْرٍ.",segs:null,full_uz:"Xayrli tun.",note:"Ayol kishiga aytiladi; so‘zma-so‘z «tongni yaxshilikda ottiring». Erkakka تُصْبِحُ بِخَيْرٍ deyiladi."},
{num:203,time:"00:16:46,519 --> 00:16:49,259",arabic:"كَانَ اللَّهُ بِعَوْنِكَ يَا فِرَاسُ.",segs:[{ar:"كَانَ اللَّهُ بِعَوْنِكَ",uz:"Alloh sizga yordamchi bo‘lsin"},{ar:"يَا فِرَاسُ",uz:"ey Firos"}],full_uz:"Alloh sizga yordamchi bo‘lsin, Firos.",note:null},
{num:204,time:"00:16:49,259 --> 00:16:50,639",arabic:"تُصْبِحُ بِخَيْرٍ.",segs:null,full_uz:"Xayrli tun.",note:null},
{num:205,time:"00:16:50,639 --> 00:17:15,700",arabic:"أَيُعْقَلُ أَنْ أُعَرِّضَ نَفْسِي لِلتَّهْلُكَةِ؟",segs:[{ar:"أَيُعْقَلُ",uz:"aqlga sig‘adimi"},{ar:"أَنْ أُعَرِّضَ نَفْسِي",uz:"o‘zimni duchor qilishim"},{ar:"لِلتَّهْلُكَةِ؟",uz:"halokatga?"}],full_uz:"O‘zimni halokatga duchor qilishim aqlga sig‘adimi?",note:"عَرَّضَ نَفْسَهُ لِـ — «o‘zini ...ga duchor qildi». تَهْلُكَةٌ — «halokat»."},
{num:206,time:"00:17:15,700 --> 00:17:20,180",arabic:"وَيَذْهَبَ أَبُو سَرْحَانَ وَحْدَهُ بِحُظْوَةٍ وَمَجْدٍ فِي بِلَاطِ أَمِيرِ الْمُؤْمِنِينَ؟",segs:[{ar:"وَيَذْهَبَ أَبُو سَرْحَانَ وَحْدَهُ",uz:"Abu Sarhon esa yolg‘iz o‘zi ega bo‘lishi"},{ar:"بِحُظْوَةٍ وَمَجْدٍ",uz:"iltifot va shon-shuhratga"},{ar:"فِي بِلَاطِ أَمِيرِ الْمُؤْمِنِينَ؟",uz:"mo‘minlar amirining saroyida?"}],full_uz:"Abu Sarhon esa mo‘minlar amirining saroyida iltifot va shon-shuhratga yolg‘iz o‘zi ega bo‘ladimi?",note:"حُظْوَةٌ — «e’tibor, iltifot, yaqinlik». بِلَاطٌ bu yerda «hukmdor saroyi»."},
{num:207,time:"00:17:20,180 --> 00:17:25,980",arabic:"هَذَا كَنْزٌ أَثْمَنُ مِنْ أَنْ تَضَعَهُ بَيْنَ يَدَيْ أَبِي سَرْحَانَ يَا فِرَاسُ.",segs:[{ar:"هَذَا كَنْزٌ أَثْمَنُ",uz:"bu ancha qimmatli xazina"},{ar:"مِنْ أَنْ تَضَعَهُ",uz:"uni qo‘yishingiz uchun"},{ar:"بَيْنَ يَدَيْ أَبِي سَرْحَانَ",uz:"Abu Sarhonning qo‘liga"},{ar:"يَا فِرَاسُ",uz:"ey Firos"}],full_uz:"Bu Abu Sarhonning qo‘liga topshirish uchun haddan ziyod qimmatli xazina, Firos.",note:"بَيْنَ يَدَيْ shaxs bilan kelganda «oldida, qo‘lida, ixtiyorida» ma’nolarini beradi."},
{num:208,time:"00:17:25,980 --> 00:17:31,060",arabic:"هَذَا الْكَنْزُ يَجِبُ أَنْ تُوصِلَهُ بِنَفْسِكَ إِلَى الْقَصْرِ.",segs:[{ar:"هَذَا الْكَنْزُ",uz:"bu xazinani"},{ar:"يَجِبُ أَنْ تُوصِلَهُ",uz:"yetkazishingiz kerak"},{ar:"بِنَفْسِكَ",uz:"shaxsan o‘zingiz"},{ar:"إِلَى الْقَصْرِ",uz:"saroyga"}],full_uz:"Bu xazinani saroyga shaxsan o‘zingiz yetkazishingiz kerak.",note:"أَوْصَلَ — «yetkazdi»; وَصَلَ — «yetib bordi»."},
{num:209,time:"00:17:31,060 --> 00:17:35,940",arabic:"وَلَكِنْ كَيْفَ السَّبِيلُ إِلَى ذَلِكَ يَا فِرَاسُ؟",segs:[{ar:"وَلَكِنْ كَيْفَ السَّبِيلُ إِلَى ذَلِكَ",uz:"lekin bunga qanday yo‘l topiladi"},{ar:"يَا فِرَاسُ؟",uz:"ey Firos?"}],full_uz:"Lekin bunga qanday yo‘l topiladi, Firos?",note:"السَّبِيلُ إِلَى — «...ga olib boradigan yo‘l, ...ning chorasi»."},
{num:210,time:"00:17:35,940 --> 00:17:38,799",arabic:"مَا بِكَ يَا أَحْمَقُ؟",segs:[{ar:"مَا بِكَ",uz:"sizga nima bo‘ldi"},{ar:"يَا أَحْمَقُ؟",uz:"ey ahmoq?"}],full_uz:"Sizga nima bo‘ldi, ey ahmoq?",note:null},
{num:211,time:"00:17:38,799 --> 00:17:44,600",arabic:"سَتَنْسَى مَا قَالَهُ الْمَرِيسِيُّ وَأَنْتَ سَادِرٌ فِي أَوْهَامِكَ وَأَحْلَامِكَ الزَّائِفَةِ.",segs:[{ar:"سَتَنْسَى",uz:"unutib qo‘yasiz"},{ar:"مَا قَالَهُ الْمَرِيسِيُّ",uz:"Marisiy aytgan gaplarni"},{ar:"وَأَنْتَ سَادِرٌ",uz:"siz esa g‘aflat bilan berilib ketgansiz"},{ar:"فِي أَوْهَامِكَ",uz:"xayollaringizga"},{ar:"وَأَحْلَامِكَ الزَّائِفَةِ",uz:"va yolg‘on orzularingizga"}],full_uz:"Xayollaringiz va yolg‘on orzularingizga berilib, Marisiy aytgan gaplarni unutib qo‘yasiz.",note:"سَادِرٌ — o‘z holatida beparvo davom etayotgan kishi. وَأَنْتَ... bu yerda holni bildiradi."},
{num:212,time:"00:17:44,600 --> 00:17:47,360",arabic:"أَنْهِ مَا حَفِظْتَهُ مِنْ مَقَالَةِ الْمُعْتَزِلَةِ.",segs:[{ar:"أَنْهِ مَا حَفِظْتَهُ",uz:"yodlaganlaringizni tugating"},{ar:"مِنْ مَقَالَةِ الْمُعْتَزِلَةِ",uz:"mu’tazilaning qarashlaridan"}],full_uz:"Mu’tazilaning qarashlaridan yodlaganlaringizni yozishni tugating.",note:"أَنْهِ — أَنْهَى («tugatdi») fe’lining buyrug‘i; oxirgi illat harfi tushgan. مَقَالَةٌ bu yerda «qarash, ta’limot»."},
{num:213,time:"00:17:47,359 --> 00:17:53,279",arabic:"وَبَعْدَهَا فَكِّرْ كَمَا تَشَاءُ فِي كَيْفِيَّةِ إِيصَالِهِ إِلَى الْقَصْرِ.",segs:[{ar:"وَبَعْدَهَا فَكِّرْ",uz:"shundan keyin o‘ylang"},{ar:"كَمَا تَشَاءُ",uz:"xohlaganingizcha"},{ar:"فِي كَيْفِيَّةِ إِيصَالِهِ",uz:"uni qanday yetkazish haqida"},{ar:"إِلَى الْقَصْرِ",uz:"saroyga"}],full_uz:"Shundan keyin uni saroyga qanday yetkazish haqida xohlaganingizcha o‘ylang.",note:"كَيْفِيَّةٌ — «qandaylik, usul». إِيصَالٌ — أَوْصَلَ fe’lining masdari: «yetkazish»."},
{num:214,time:"00:17:55,240 --> 00:18:07,240",arabic:"هَا قَدْ جِئْتُكِ بِجَارِيَتِكِ رَغَدٍ.",segs:[{ar:"هَا قَدْ جِئْتُكِ",uz:"mana, oldingizga keldim"},{ar:"بِجَارِيَتِكِ رَغَدٍ",uz:"joriyangiz Rag‘adni olib"}],full_uz:"Mana, joriyangiz Rag‘adni olib keldim.",note:"جَاءَ بِـ — «olib keldi». هَا قَدْ... — «mana, ... bo‘ldi» deb e’tiborni natijaga qaratadi."},
{num:215,time:"00:18:07,240 --> 00:18:12,399",arabic:"أَتَمَنَّى عَلَى سَيِّدَتِي أَنْ تُنَادِيَنِي بِاسْمِ فَوْزٍ وَلَيْسَ رَغَدٍ.",segs:[{ar:"أَتَمَنَّى عَلَى سَيِّدَتِي",uz:"bekamdan iltimos qilaman"},{ar:"أَنْ تُنَادِيَنِي",uz:"meni chaqirishlarini"},{ar:"بِاسْمِ فَوْزٍ",uz:"Favz ismi bilan"},{ar:"وَلَيْسَ رَغَدٍ",uz:"Rag‘ad emas"}],full_uz:"Bekamdan meni Rag‘ad emas, Favz deb chaqirishlarini iltimos qilaman.",note:"سَيِّدَتِي — «bekam, xonimim». So‘zlovchi murojaat qilayotgan ayolni hurmat bilan uchinchi shaxsda tilga olmoqda."},
{num:216,time:"00:18:12,399 --> 00:18:17,099",arabic:"وَلِمَ أُنَادِيكِ بِاسْمِ فَوْزٍ إِنْ كَانَ اسْمُكِ رَغَدًا؟",segs:[{ar:"وَلِمَ أُنَادِيكِ",uz:"nega sizni chaqiraman"},{ar:"بِاسْمِ فَوْزٍ",uz:"Favz deb"},{ar:"إِنْ كَانَ اسْمُكِ رَغَدًا؟",uz:"agar ismingiz Rag‘ad bo‘lsa?"}],full_uz:"Ismingiz Rag‘ad bo‘lsa, nega sizni Favz deb chaqirishim kerak?",note:"كَانَ اسْمُكِ رَغَدًا da اسْمُكِ — كَانَning ismi, رَغَدًا — mansub xabari."},
{num:217,time:"00:18:17,099 --> 00:18:31,500",arabic:"هَذِهِ قِصَّةٌ طَوِيلَةٌ، سَأُخْبِرُكِ بِهَا فِيمَا بَعْدُ.",segs:[{ar:"هَذِهِ قِصَّةٌ طَوِيلَةٌ",uz:"bu uzun hikoya"},{ar:"سَأُخْبِرُكِ بِهَا",uz:"sizga uni aytib beraman"},{ar:"فِيمَا بَعْدُ",uz:"keyinroq"}],full_uz:"Bu uzun hikoya, sizga keyinroq aytib beraman.",note:"فِيمَا بَعْدُ — «keyinroq, keyinchalik»."},
{num:218,time:"00:18:31,500 --> 00:18:36,659",arabic:"وَهَلْ لِأَمْثَالِهَا مِنَ الْجَوَارِي قِصَصٌ تُرْوَى؟",segs:[{ar:"وَهَلْ لِأَمْثَالِهَا",uz:"unga o‘xshaganlarning ham bormi"},{ar:"مِنَ الْجَوَارِي",uz:"joriyalar orasidan"},{ar:"قِصَصٌ تُرْوَى؟",uz:"aytib beriladigan hikoyalari?"}],full_uz:"Unga o‘xshagan joriyalarning ham aytib beradigan hikoyalari bormi?",note:"جَوَارٍ / الْجَوَارِي — جَارِيَةٌ so‘zining ko‘pligi. تُرْوَى — «hikoya qilinadi», majhul nisbat."},
{num:219,time:"00:18:36,659 --> 00:18:38,859",arabic:"قَدْ تَكُونُ لِي قِصَّةٌ طَوِيلَةٌ ظَالِمَةٌ.",segs:[{ar:"قَدْ تَكُونُ لِي",uz:"balki mening ham bordir"},{ar:"قِصَّةٌ طَوِيلَةٌ ظَالِمَةٌ",uz:"uzun, zulmli hikoyam"}],full_uz:"Balki mening ham uzun, zulmli hikoyam bordir.",note:"قَدْ muzoriy bilan kelganda ehtimolni bildirishi mumkin: «balki»."},
{num:220,time:"00:18:38,859 --> 00:18:41,619",arabic:"جَعَلَتْ مِنِّي جَارِيَةً بَعْدَ أَنْ كُنْتُ فَتَاةً حُرَّةً.",segs:[{ar:"جَعَلَتْ مِنِّي جَارِيَةً",uz:"meni joriyaga aylantirgan"},{ar:"بَعْدَ أَنْ كُنْتُ",uz:"bo‘lganimdan keyin"},{ar:"فَتَاةً حُرَّةً",uz:"ozod qiz"}],full_uz:"Ozod qiz bo‘lganimdan keyin meni joriyaga aylantirgan hikoya.",note:"جَعَلَ مِنْهُ... — «uni ...ga aylantirdi». حُرَّةٌ — «ozod», muannas shakl."},
{num:221,time:"00:18:41,619 --> 00:18:44,199",arabic:"كُلُّهُنَّ يَزْعُمْنَ ذَلِكَ.",segs:null,full_uz:"Ularning hammasi shunday da’vo qiladi.",note:"يَزْعُمْنَ — ayollar ko‘pligiga tegishli fe’l. Oxiridagi نَ — nun an-nisva."},
{num:222,time:"00:18:44,200 --> 00:18:47,900",arabic:"الْمُهِمُّ أَنَّكِ الْآنَ عِنْدِي جَارِيَةٌ.",segs:[{ar:"الْمُهِمُّ أَنَّكِ الْآنَ",uz:"muhimi, siz hozir"},{ar:"عِنْدِي جَارِيَةٌ",uz:"mening qo‘limda joriyasiz"}],full_uz:"Muhimi, siz hozir mening qo‘limda joriyasiz.",note:null},
{num:223,time:"00:18:47,900 --> 00:18:55,200",arabic:"وَأَنْتِ هُنَا فِي هَذَا الْبَيْتِ لِخِدْمَتِنَا فَحَسْبُ.",segs:[{ar:"وَأَنْتِ هُنَا",uz:"siz bu yerdasiz"},{ar:"فِي هَذَا الْبَيْتِ",uz:"bu uyda"},{ar:"لِخِدْمَتِنَا فَحَسْبُ",uz:"faqat bizga xizmat qilish uchun"}],full_uz:"Siz bu uyda faqat bizga xizmat qilish uchun turibsiz.",note:"فَحَسْبُ — «xolos, faqat shuning o‘zi»."},
{num:224,time:"00:18:55,200 --> 00:19:01,200",arabic:"أَمْ أَرَاكِ تَعْتَرِضِينَ عَلَى هَذَا أَيْضًا؟",segs:[{ar:"أَمْ أَرَاكِ تَعْتَرِضِينَ",uz:"yoki e’tiroz bildirayotganingizni ko‘ryapmanmi"},{ar:"عَلَى هَذَا أَيْضًا؟",uz:"bunga ham?"}],full_uz:"Yoki bunga ham e’tiroz bildiryapsizmi?",note:"اِعْتَرَضَ عَلَى — «...ga e’tiroz bildirdi»."},
{num:225,time:"00:19:06,200 --> 00:19:09,700",arabic:"أَلَمْ تَسْمَعْ أَنَّهُ جَاءَ إِلَى تَاجِرٍ آخَرَ فِي بَغْدَادَ؟",segs:[{ar:"أَلَمْ تَسْمَعْ",uz:"eshitmadingizmi"},{ar:"أَنَّهُ جَاءَ إِلَى تَاجِرٍ آخَرَ",uz:"uning boshqa savdogar oldiga kelganini"},{ar:"فِي بَغْدَادَ؟",uz:"Bag‘dodda?"}],full_uz:"Uning Bag‘dodda boshqa savdogar oldiga kelganini eshitmadingizmi?",note:null},
{num:226,time:"00:19:09,700 --> 00:19:12,160",arabic:"لَا، لَوْ أَنَّهُ أَتَى بَغْدَادَ لَعَرَّجَ عَلَيَّ.",segs:[{ar:"لَا",uz:"yo‘q"},{ar:"لَوْ أَنَّهُ أَتَى بَغْدَادَ",uz:"agar u Bag‘dodga kelganida"},{ar:"لَعَرَّجَ عَلَيَّ",uz:"mening oldimga ham kirgan bo‘lardi"}],full_uz:"Yo‘q, agar u Bag‘dodga kelganida, mening oldimga ham kirgan bo‘lardi.",note:"عَرَّجَ عَلَى شَخْصٍ — «yo‘l-yo‘lakay birovning oldiga kirdi»."},
{num:227,time:"00:19:12,160 --> 00:19:14,680",arabic:"جَزَاكَ اللَّهُ خَيْرًا.",segs:null,full_uz:"Alloh sizni yaxshilik bilan mukofotlasin.",note:null},
{num:228,time:"00:19:14,680 --> 00:19:15,340",arabic:"السَّلَامُ عَلَيْكُمْ.",segs:null,full_uz:"Assalomu alaykum.",note:null},
{num:229,time:"00:19:15,340 --> 00:19:16,300",arabic:"وَعَلَيْكُمُ السَّلَامُ.",segs:null,full_uz:"Va alaykum assalom.",note:null},
{num:230,time:"00:19:28,420 --> 00:19:30,960",arabic:"وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ.",segs:[{ar:"وَعَلَيْكُمُ السَّلَامُ",uz:"sizga ham tinchlik bo‘lsin"},{ar:"وَرَحْمَةُ اللَّهِ",uz:"va Allohning rahmati"}],full_uz:"Sizga ham tinchlik va Allohning rahmati bo‘lsin.",note:null},
{num:231,time:"00:19:30,960 --> 00:19:33,840",arabic:"كَيْفَ حَالُ زِينَةِ شَبَابِ بَغْدَادَ؟",segs:[{ar:"كَيْفَ حَالُ",uz:"ahvoli qanday"},{ar:"زِينَةِ شَبَابِ بَغْدَادَ؟",uz:"Bag‘dod yoshlarining ziynati bo‘lganlarning?"}],full_uz:"Bag‘dod yoshlarining ziynati bo‘lganlarning ahvoli qanday?",note:"زِينَةٌ — «ziynat, bezak»; bu yerda kishilarni maqtash uchun ishlatilgan."},
{num:232,time:"00:19:33,840 --> 00:19:35,820",arabic:"وَدُرَرِهَا الْمُتَلَأْلِئَةِ؟",segs:null,full_uz:"Va uning porlab turgan durlarining-chi?",note:"دُرَرٌ — دُرَّةٌ («dur»)ning ko‘pligi. مُتَلَأْلِئَةٌ — «porlab, tovlanib turgan»."},
{num:233,time:"00:19:35,820 --> 00:19:38,320",arabic:"بَارَكَ اللَّهُ فِيكَ يَا أَبَا مَحْفُوظٍ.",segs:[{ar:"بَارَكَ اللَّهُ فِيكَ",uz:"Alloh sizga baraka bersin"},{ar:"يَا أَبَا مَحْفُوظٍ",uz:"ey Abu Mahfuz"}],full_uz:"Alloh sizga baraka bersin, Abu Mahfuz.",note:null},
{num:234,time:"00:19:38,320 --> 00:19:40,880",arabic:"مِنْ أَيْنَ لَنَا أَنْ نَكُونَ كَمَا وَصَفْتَ؟",segs:[{ar:"مِنْ أَيْنَ لَنَا أَنْ نَكُونَ",uz:"qayerdan ham shunday bo‘la olaylik"},{ar:"كَمَا وَصَفْتَ؟",uz:"siz ta’riflagandek?"}],full_uz:"Qayerdan ham siz ta’riflagandek bo‘la olaylik?",note:"مِنْ أَيْنَ لَنَا... bu yerda kamtarlik bilan «bizga yo‘l bo‘lsin, qanday ham ... bo‘laylik» ma’nosida."},
{num:235,time:"00:19:40,880 --> 00:19:47,000",arabic:"وَهَلْ هُنَاكَ أَزْيَنُ مِنْ حَمَلَةِ حَدِيثِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟",segs:[{ar:"وَهَلْ هُنَاكَ أَزْيَنُ",uz:"bundan ham ziynatliroq kishilar bormi"},{ar:"مِنْ حَمَلَةِ حَدِيثِ رَسُولِ اللَّهِ",uz:"Alloh Rasulining hadislarini saqlovchilardan"},{ar:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",uz:"Alloh unga salovot va salom yo‘llasin"}],full_uz:"Alloh Rasulining hadislarini saqlovchilardan ham ziynatliroq kishilar bormi? Alloh unga salovot va salom yo‘llasin.",note:"حَمَلَةٌ — حَامِلٌ ning ko‘pligi. حَمَلَةُ الْحَدِيثِ — hadisni yodlab, saqlab va yetkazib yuruvchilar."},
{num:236,time:"00:19:47,000 --> 00:19:48,620",arabic:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.",segs:null,full_uz:"Alloh unga salovot va salom yo‘llasin.",note:null},
{num:237,time:"00:19:48,620 --> 00:19:54,820",arabic:"إِنَّنِي حِينَ تَقَعُ عَيْنِي عَلَى أَحَدِكُمْ...",segs:[{ar:"إِنَّنِي حِينَ تَقَعُ عَيْنِي",uz:"mening ko‘zim tushganida"},{ar:"عَلَى أَحَدِكُمْ",uz:"sizlardan biringizga"}],full_uz:"Mening ko‘zim sizlardan biringizga tushganida...",note:"وَقَعَتْ عَيْنُهُ عَلَى — «ko‘zi tushdi». Javob keyingi bandda davom etadi."},
{num:238,time:"00:19:54,820 --> 00:20:01,120",arabic:"فَكَأَنَّنِي رَأَيْتُ رَجُلًا مِنْ صَحَابَةِ الرَّسُولِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.",segs:[{ar:"فَكَأَنَّنِي رَأَيْتُ رَجُلًا",uz:"go‘yo bir kishini ko‘rgandek bo‘laman"},{ar:"مِنْ صَحَابَةِ الرَّسُولِ مُحَمَّدٍ",uz:"Rasul Muhammadning sahobalaridan"},{ar:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",uz:"Alloh unga salovot va salom yo‘llasin"}],full_uz:"Go‘yo Rasul Muhammadning sahobalaridan birini ko‘rgandek bo‘laman. Alloh unga salovot va salom yo‘llasin.",note:"كَأَنَّنِي — «go‘yo men». كَأَنَّ o‘xshatish va tasavvurni bildiradi."},
{num:239,time:"00:20:03,360 --> 00:20:07,140",arabic:"بَارَكَ اللَّهُ فِيكَ يَا أَبَا مَحْفُوظٍ عَلَى حُسْنِ ظَنِّكَ فِينَا.",segs:[{ar:"بَارَكَ اللَّهُ فِيكَ",uz:"Alloh sizga baraka bersin"},{ar:"يَا أَبَا مَحْفُوظٍ",uz:"ey Abu Mahfuz"},{ar:"عَلَى حُسْنِ ظَنِّكَ فِينَا",uz:"biz haqimizdagi yaxshi fikringiz uchun"}],full_uz:"Biz haqimizdagi yaxshi fikringiz uchun Alloh sizga baraka bersin, Abu Mahfuz.",note:"حُسْنُ الظَّنِّ — «yaxshi fikrda bo‘lish»."},
{num:240,time:"00:20:07,140 --> 00:20:10,620",arabic:"وَلَكِنْ أَيْنَ نَحْنُ مِنْ هَؤُلَاءِ الْقَوْمِ؟",segs:[{ar:"وَلَكِنْ أَيْنَ نَحْنُ",uz:"lekin biz qayerdamiz"},{ar:"مِنْ هَؤُلَاءِ الْقَوْمِ؟",uz:"o‘sha kishilarga nisbatan?"}],full_uz:"Lekin biz o‘sha kishilarga qayerdan ham teng kela olaylik?",note:"أَيْنَ فُلَانٌ مِنْ فُلَانٍ؟ — ikki kishining darajasi orasidagi katta farqni bildiruvchi ibora."},
{num:241,time:"00:20:10,619 --> 00:20:15,699",arabic:"إِنَّ أَحَدَنَا لَوِ اجْتَهَدَ دَهْرًا مَا بَلَغَ مُدَّ أَحَدِهِمْ وَلَا نَصِيفَهُ.",segs:[{ar:"إِنَّ أَحَدَنَا",uz:"albatta, bizlardan birimiz"},{ar:"لَوِ اجْتَهَدَ دَهْرًا",uz:"bir umr harakat qilsa ham"},{ar:"مَا بَلَغَ مُدَّ أَحَدِهِمْ",uz:"ulardan birining bir muddiga ham yetolmaydi"},{ar:"وَلَا نَصِيفَهُ",uz:"uning yarmiga ham"}],full_uz:"Bizlardan birimiz bir umr harakat qilsa ham, ulardan birining bir mudd miqdoridagi ehsoniga ham, uning yarmiga ham yetolmaydi.",note:"مُدٌّ — qadimgi hajm o‘lchovi; bu yerda ehson miqdori nazarda tutilgan. نَصِيفٌ — «yarim»."},
{num:242,time:"00:20:15,699 --> 00:20:19,899",arabic:"فَمَا بَالُكَ بِمَنْ نَظَرَ إِلَى وَجْهِ رَسُولِ اللَّهِ؟",segs:[{ar:"فَمَا بَالُكَ بِمَنْ",uz:"unday kishini qanday deb o‘ylaysizki"},{ar:"نَظَرَ إِلَى وَجْهِ رَسُولِ اللَّهِ؟",uz:"Alloh Rasulining yuzlariga qaragan?"}],full_uz:"Alloh Rasulining yuzlarini ko‘rgan kishi haqida nima deysiz?",note:"فَمَا بَالُكَ بِـ... — «unda ... haqida nima deysiz?»; bir holatning ulug‘ligi yoki kuchliligiga e’tibor qaratadi."},
{num:243,time:"00:20:19,899 --> 00:20:21,759",arabic:"أَيَشْقَى بَعْدَهَا؟",segs:null,full_uz:"Shundan keyin u badbaxt bo‘ladimi?",note:"شَقِيَ — يَشْقَى — «baxtsiz bo‘lmoq, mashaqqat chekmoq»."},
{num:244,time:"00:20:21,759 --> 00:20:25,219",arabic:"اللَّهُمَّ صَلِّ وَسَلِّمْ عَلَى مَنْ صَلَّتْ عَلَيْهِ الْمَلَائِكَةُ.",segs:[{ar:"اللَّهُمَّ صَلِّ وَسَلِّمْ",uz:"Allohim, salovot va salom yo‘lla"},{ar:"عَلَى مَنْ",uz:"o‘sha kishiga"},{ar:"صَلَّتْ عَلَيْهِ الْمَلَائِكَةُ",uz:"unga farishtalar salovot aytgan"}],full_uz:"Allohim, farishtalar salovot aytgan kishiga salovot va salom yo‘lla.",note:"صَلِّ — صَلَّى fe’lining buyruq shakli; oxirgi illat harfi tushadi. اللَّهُمَّ — «Allohim»."},
{num:245,time:"00:20:29,559 --> 00:20:39,619",arabic:"تَفَضَّلِي سَيِّدَتِي، هَذَا طَعَامُكِ، أَرْجُو أَنْ يَنَالَ رِضَاكِ.",segs:[{ar:"تَفَضَّلِي سَيِّدَتِي",uz:"marhamat, bekam"},{ar:"هَذَا طَعَامُكِ",uz:"bu sizning taomingiz"},{ar:"أَرْجُو أَنْ يَنَالَ رِضَاكِ",uz:"sizga ma’qul kelishini umid qilaman"}],full_uz:"Marhamat, bekam, bu taomingiz. Sizga ma’qul kelishini umid qilaman.",note:"نَالَ رِضَا شَخْصٍ — «birovning roziligiga erishdi, unga ma’qul keldi»."},
{num:246,time:"00:20:39,619 --> 00:20:48,019",arabic:"إِنْ أَرَدْتِ سَيِّدَتِي أَطْعَمْتُكِ بِيَدِي.",segs:[{ar:"إِنْ أَرَدْتِ سَيِّدَتِي",uz:"istasangiz, bekam"},{ar:"أَطْعَمْتُكِ بِيَدِي",uz:"sizga o‘z qo‘lim bilan yediraman"}],full_uz:"Istasangiz, bekam, sizga o‘z qo‘lim bilan yediraman.",note:"Shart gapda o‘tgan zamon shakli kelajakdagi ishni bildirishi mumkin: أَطْعَمْتُكِ — bu yerda «yediraman»."},
{num:247,time:"00:20:48,019 --> 00:20:51,959",arabic:"أَسْتَطِيعُ أَنْ آكُلَ وَحْدِي.",segs:[{ar:"أَسْتَطِيعُ أَنْ آكُلَ",uz:"ovqatlana olaman"},{ar:"وَحْدِي",uz:"o‘zim"}],full_uz:"O‘zim ovqatlana olaman.",note:"آكُلُ — «men yeyman». أَنْ dan keyin آكُلَ bo‘ladi."},
{num:248,time:"00:20:51,959 --> 00:21:01,299",arabic:"لِمَاذَا تَقِفِينَ عِنْدَكِ أَيَّتُهَا الْجَارِيَةُ؟",segs:[{ar:"لِمَاذَا تَقِفِينَ عِنْدَكِ",uz:"nega o‘sha yerda turibsiz"},{ar:"أَيَّتُهَا الْجَارِيَةُ؟",uz:"ey joriya?"}],full_uz:"Nega o‘sha yerda turibsiz, ey joriya?",note:"أَيَّتُهَا — muannasga murojaat shakli. Muzakkar shakli أَيُّهَا."},
{num:249,time:"00:21:01,299 --> 00:21:05,579",arabic:"إِنَّ أَعْمَالَ الدَّارِ لَا تَنْتَهِي.",segs:[{ar:"إِنَّ أَعْمَالَ الدَّارِ",uz:"axir uy ishlari"},{ar:"لَا تَنْتَهِي",uz:"tugamaydi"}],full_uz:"Axir uy ishlari tugamaydi.",note:null},
{num:250,time:"00:21:05,579 --> 00:21:07,979",arabic:"هَيَّا، اِنْصَرِفِي إِلَى أَعْمَالِكِ.",segs:[{ar:"هَيَّا",uz:"qani"},{ar:"اِنْصَرِفِي إِلَى أَعْمَالِكِ",uz:"ishlaringizga boring"}],full_uz:"Qani, ishlaringizga boring.",note:"اِنْصَرَفَ إِلَى عَمَلِهِ — «o‘z ishiga qaytdi, ishiga kirishdi»."},
{num:251,time:"00:21:07,980 --> 00:21:10,839",arabic:"كَمَا تَشَائِينَ سَيِّدَتِي.",segs:[{ar:"كَمَا تَشَائِينَ",uz:"xohlaganingizdek"},{ar:"سَيِّدَتِي",uz:"bekam"}],full_uz:"Xohlaganingizdek, bekam.",note:null},
{num:252,time:"00:21:10,839 --> 00:21:13,660",arabic:"إِنِ احْتَجْتِ شَيْئًا نَادِينِي.",segs:[{ar:"إِنِ احْتَجْتِ شَيْئًا",uz:"biror narsa kerak bo‘lsa"},{ar:"نَادِينِي",uz:"meni chaqiring"}],full_uz:"Biror narsa kerak bo‘lsa, meni chaqiring.",note:"نَادِينِي — ayol kishiga buyruq: «meni chaqiring». Erkak kishiga نَادِنِي deyiladi."},
{num:253,time:"00:21:13,660 --> 00:21:14,720",arabic:"أَكُونُ...",segs:null,full_uz:"Bo‘laman...",note:null},
{num:254,time:"00:21:34,720 --> 00:21:41,100",arabic:"وَلِلْمُعْتَزِلَةِ شَنَاعَاتٌ فِي إِنْكَارِهِمُ الْحَدِيثَ وَعَدَمِ الْتِفَاتِهِمْ إِلَيْهِ.",segs:[{ar:"وَلِلْمُعْتَزِلَةِ شَنَاعَاتٌ",uz:"mu’tazilaning qabih ishlari bor"},{ar:"فِي إِنْكَارِهِمُ الْحَدِيثَ",uz:"hadisni inkor qilishlarida"},{ar:"وَعَدَمِ الْتِفَاتِهِمْ إِلَيْهِ",uz:"va unga e’tibor bermasliklarida"}],full_uz:"Mu’tazilaning hadisni inkor qilish va unga e’tibor bermaslik borasida qabih ishlari bor.",note:"عَدَمُ + masdar ishning yo‘qligini bildiradi: عَدَمُ الْتِفَاتِهِمْ — «ularning e’tibor bermasligi»."},
{num:255,time:"00:21:41,099 --> 00:21:47,279",arabic:"الْمُعْتَزِلَةُ بَنَوْا مَذْهَبَهُمْ فِي إِنْكَارِ السُّنَّةِ عَلَى أَمْرَيْنِ.",segs:[{ar:"الْمُعْتَزِلَةُ بَنَوْا مَذْهَبَهُمْ",uz:"mu’tazila o‘z mazhabini qurgan"},{ar:"فِي إِنْكَارِ السُّنَّةِ",uz:"sunnatni inkor qilish borasida"},{ar:"عَلَى أَمْرَيْنِ",uz:"ikki narsaga asoslab"}],full_uz:"Mu’tazila sunnatni inkor qilish borasidagi mazhabini ikki narsaga asoslab qurgan.",note:"بَنَى عَلَى — «...ga asosladi». أَمْرَيْنِ — ikkilikning jar shakli: «ikki narsa»."},
{num:256,time:"00:21:47,279 --> 00:21:54,079",arabic:"الْأَوَّلُ التَّشْكِيكُ فِي عَدَالَةِ النَّقَلَةِ، لَا سِيَّمَا الصَّحَابَةِ.",segs:[{ar:"الْأَوَّلُ التَّشْكِيكُ",uz:"birinchisi — shubha uyg‘otish"},{ar:"فِي عَدَالَةِ النَّقَلَةِ",uz:"rivoyat yetkazuvchilarning ishonchliligiga"},{ar:"لَا سِيَّمَا الصَّحَابَةِ",uz:"ayniqsa sahobalarning"}],full_uz:"Birinchisi — rivoyat yetkazuvchilarning, ayniqsa sahobalarning ishonchliligiga shubha uyg‘otish.",note:"نَقَلَةٌ — «naql qiluvchilar». عَدَالَةٌ hadis ilmida roviyning diniy-axloqiy ishonchliligini bildiradi. لَا سِيَّمَا — «ayniqsa»."},
{num:257,time:"00:21:54,079 --> 00:21:57,199",arabic:"وَالثَّانِي تَقْدِيمُ عُقُولِهِمْ عَلَى شَرْعِ اللَّهِ.",segs:[{ar:"وَالثَّانِي",uz:"ikkinchisi esa"},{ar:"تَقْدِيمُ عُقُولِهِمْ",uz:"o‘z aqllarini ustun qo‘yish"},{ar:"عَلَى شَرْعِ اللَّهِ",uz:"Allohning shariatidan"}],full_uz:"Ikkinchisi esa o‘z aqllarini Allohning shariatidan ustun qo‘yish.",note:"قَدَّمَ شَيْئًا عَلَى شَيْءٍ — «bir narsani boshqasidan ustun qo‘ydi»."},
{num:258,time:"00:21:57,199 --> 00:22:01,980",arabic:"لَقَدْ وَصَلَ الْغُلُوُّ بِعَمْرِو بْنِ عُبَيْدٍ الْمُعْتَزِلِيِّ...",segs:[{ar:"لَقَدْ وَصَلَ الْغُلُوُّ",uz:"haddan oshish shu darajaga yetkazgan"},{ar:"بِعَمْرِو بْنِ عُبَيْدٍ الْمُعْتَزِلِيِّ",uz:"mu’taziliy Amr ibn Ubaydni"}],full_uz:"Haddan oshish mu’taziliy Amr ibn Ubaydni shu darajaga yetkazganki...",note:"غُلُوٌّ — «haddan oshish». عَمْرٌ ismi yozuvda عَمْرُو tarzida keladi; oxirgi و talaffuz qilinmaydi."},
{num:259,time:"00:22:01,980 --> 00:22:06,399",arabic:"وَقَدْ ذَكَرُوا لَهُ حَدِيثًا عَنْ رَسُولِ اللَّهِ، أَنَّهُ قَالَ...",segs:[{ar:"وَقَدْ ذَكَرُوا لَهُ حَدِيثًا",uz:"unga bir hadisni aytishganida"},{ar:"عَنْ رَسُولِ اللَّهِ",uz:"Alloh Rasulidan rivoyat qilingan"},{ar:"أَنَّهُ قَالَ",uz:"u shunday degan"}],full_uz:"Unga Alloh Rasulidan rivoyat qilingan bir hadisni aytishganida, u shunday degan...",note:"أَنَّهُ قَالَ dagi olmosh oldingi bandda tilga olingan kishiga qaytadi; keyingi band uning gapi."},
{num:260,time:"00:22:06,400 --> 00:22:13,460",arabic:"لَوْ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ هَذَا الْحَدِيثَ لَرَدَدْتُهُ.",segs:[{ar:"لَوْ سَمِعْتُ رَسُولَ اللَّهِ",uz:"agar Alloh Rasulini eshitganimda"},{ar:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",uz:"Alloh unga salovot va salom yo‘llasin"},{ar:"يَقُولُ هَذَا الْحَدِيثَ",uz:"bu hadisni aytayotganini"},{ar:"لَرَدَدْتُهُ",uz:"uni rad etgan bo‘lardim"}],full_uz:"Alloh Rasulining bu hadisni aytayotganini eshitganimda ham, uni rad etgan bo‘lardim. Alloh unga salovot va salom yo‘llasin.",note:"لَوْ ... لَـ ... faraziy shart va javobni bildiradi. رَدَدْتُ — رَدَّ fe’lining «men rad etdim» shakli."},
{num:261,time:"00:22:13,460 --> 00:22:16,180",arabic:"نَعُوذُ بِاللَّهِ مِنْ هَذَا الضَّلَالِ.",segs:[{ar:"نَعُوذُ بِاللَّهِ",uz:"Allohdan panoh so‘raymiz"},{ar:"مِنْ هَذَا الضَّلَالِ",uz:"bu adashishdan"}],full_uz:"Bu adashishdan Allohdan panoh so‘raymiz.",note:"عَاذَ بِـ ... مِنْ ... — «...dan ...ning panohini so‘radi»."},
{num:262,time:"00:22:16,180 --> 00:22:19,780",arabic:"قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ...",segs:[{ar:"قَالَ رَسُولُ اللَّهِ",uz:"Alloh Rasuli aytdilar"},{ar:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",uz:"Alloh unga salovot va salom yo‘llasin"}],full_uz:"Alloh Rasuli aytdilar, Alloh unga salovot va salom yo‘llasin...",note:null},
{num:263,time:"00:22:19,780 --> 00:22:24,980",arabic:"لَا أُلْفِيَنَّ أَحَدَكُمْ مُتَّكِئًا عَلَى أَرِيكَتِهِ...",segs:[{ar:"لَا أُلْفِيَنَّ أَحَدَكُمْ",uz:"sizlardan biringizni aslo ko‘rmayin"},{ar:"مُتَّكِئًا عَلَى أَرِيكَتِهِ",uz:"o‘z so‘risiga suyanib yotgan holda"}],full_uz:"Sizlardan biringizni o‘z so‘risiga suyanib yotgan holda aslo ko‘rmayin...",note:"أَلْفَى — «topdi, bir holatda ko‘rdi». أُلْفِيَنَّ dagi نَّ kuchli ta’kid bildiradi. مُتَّكِئًا — hol."},
{num:264,time:"00:22:24,980 --> 00:22:30,820",arabic:"يَأْتِيهِ الْأَمْرُ مِنْ أَمْرِي مِمَّا أَمَرْتُ بِهِ أَوْ نَهَيْتُ عَنْهُ...",segs:[{ar:"يَأْتِيهِ الْأَمْرُ مِنْ أَمْرِي",uz:"unga mening ko‘rsatmalarimdan bir ko‘rsatma yetib keladi"},{ar:"مِمَّا أَمَرْتُ بِهِ",uz:"men buyurgan narsalarimdan"},{ar:"أَوْ نَهَيْتُ عَنْهُ",uz:"yoki qaytargan narsalarimdan"}],full_uz:"Unga men buyurgan yoki qaytargan narsalarimga oid bir ko‘rsatma yetib keladi...",note:"أَمَرَ بِـ — «buyurdi»; نَهَى عَنْ — «qaytardi, taqiqladi»."},
{num:265,time:"00:22:30,820 --> 00:22:35,540",arabic:"فَيَقُولُ: لَا أَدْرِي، مَا وَجَدْنَا فِي كِتَابِ اللَّهِ اتَّبَعْنَاهُ.",segs:[{ar:"فَيَقُولُ: لَا أَدْرِي",uz:"shunda u: «Bilmayman», deydi"},{ar:"مَا وَجَدْنَا فِي كِتَابِ اللَّهِ",uz:"Allohning Kitobida nimani topsak"},{ar:"اتَّبَعْنَاهُ",uz:"o‘shanga ergashamiz"}],full_uz:"Shunda u: «Bilmayman, Allohning Kitobida nimani topsak, o‘shanga ergashamiz», deydi.",note:"مَا وَجَدْنَا ... اتَّبَعْنَاهُ — «nimani topsak, o‘shanga ergashamiz». هُ olmoshi مَا ga qaytadi."},
{num:266,time:"00:22:35,539 --> 00:22:43,039",arabic:"سُبْحَانَ اللَّهِ، أَدْرَكْنَا هَذَا الزَّمَانَ الَّذِي يُنْكِرُ فِيهِ الْبَعْضُ حُجِّيَّةَ السُّنَّةِ.",segs:[{ar:"سُبْحَانَ اللَّهِ",uz:"Alloh pokdir"},{ar:"أَدْرَكْنَا هَذَا الزَّمَانَ",uz:"bu zamonga ham yetib keldik"},{ar:"الَّذِي يُنْكِرُ فِيهِ الْبَعْضُ",uz:"unda ayrimlar inkor qiladigan"},{ar:"حُجِّيَّةَ السُّنَّةِ",uz:"sunnatning hujjat ekanini"}],full_uz:"Subhanalloh, ayrimlar sunnatning hujjat ekanini inkor qiladigan zamonga ham yetib keldik.",note:"حُجِّيَّةٌ — bir narsaning dalil va asos bo‘la olish xususiyati. أَدْرَكَ الزَّمَانَ — «o‘sha davrga yetishdi»."},
{num:267,time:"00:22:43,039 --> 00:22:52,500",arabic:"لَا رَيْبَ أَنَّ الِاعْتِصَامَ بِكِتَابِ اللَّهِ وَالسُّنَّةِ هُوَ مِنْ أَعْظَمِ مَا مَنَّ اللَّهُ بِهِ عَلَى هَذِهِ الْأُمَّةِ.",segs:[{ar:"لَا رَيْبَ",uz:"shubha yo‘q"},{ar:"أَنَّ الِاعْتِصَامَ",uz:"mahkam tutish"},{ar:"بِكِتَابِ اللَّهِ وَالسُّنَّةِ",uz:"Allohning Kitobi va sunnatni"},{ar:"هُوَ مِنْ أَعْظَمِ",uz:"eng ulug‘laridandir"},{ar:"مَا مَنَّ اللَّهُ بِهِ",uz:"Alloh in’om qilgan narsalarning"},{ar:"عَلَى هَذِهِ الْأُمَّةِ",uz:"bu ummatga"}],full_uz:"Shubhasiz, Allohning Kitobi va sunnatni mahkam tutish Alloh bu ummatga in’om qilgan eng ulug‘ ne’matlardandir.",note:"اِعْتَصَمَ بِـ — «mahkam tutdi». مَنَّ اللَّهُ عَلَيْهِ بِشَيْءٍ — «Alloh unga bir narsani in’om qildi»."},
{num:268,time:"00:22:52,500 --> 00:23:01,039",arabic:"لَمْ أَعْثُرْ عَلَى ذَلِكَ الرَّجُلِ إِلَّا بَعْدَ أَنْ طُفْتُ نِصْفَ أَسْوَاقِ بَغْدَادَ.",segs:[{ar:"لَمْ أَعْثُرْ عَلَى ذَلِكَ الرَّجُلِ",uz:"o‘sha kishini topmadim"},{ar:"إِلَّا بَعْدَ أَنْ طُفْتُ",uz:"faqat aylanib chiqqanimdan keyingina topdim"},{ar:"نِصْفَ أَسْوَاقِ بَغْدَادَ",uz:"Bag‘dod bozorlarining yarmini"}],full_uz:"O‘sha kishini Bag‘dod bozorlarining yarmini aylanib chiqqanimdan keyingina topdim.",note:"لَمْ ... إِلَّا بَعْدَ... — «faqat ...dan keyingina». طُفْتُ — طَافَ («aylandi») fe’lining birinchi shaxs shakli."},
{num:269,time:"00:23:01,039 --> 00:23:03,539",arabic:"وَمَاذَا قَالَ لَكَ؟",segs:null,full_uz:"U sizga nima dedi?",note:null},
{num:270,time:"00:23:03,539 --> 00:23:06,920",arabic:"لَقَدْ تَذَكَّرَ أَبَاكِ حِينَ ذَكَرْتُ اسْمَهُ.",segs:[{ar:"لَقَدْ تَذَكَّرَ أَبَاكِ",uz:"u otangizni esladi"},{ar:"حِينَ ذَكَرْتُ اسْمَهُ",uz:"uning ismini aytganimda"}],full_uz:"Ismini aytganimda, u otangizni esladi.",note:"ذَكَرَ — «tilga oldi»; تَذَكَّرَ — «esladi». Bu gapda ikkala fe’l ham ishlatilgan."},
{num:271,time:"00:23:06,920 --> 00:23:09,319",arabic:"هَاهْ؟ أَحَقًّا مَا تَقُولُ؟",segs:[{ar:"هَاهْ؟",uz:"ha?"},{ar:"أَحَقًّا مَا تَقُولُ؟",uz:"aytayotganingiz rostmi?"}],full_uz:"Ha? Aytayotganingiz rostmi?",note:null},
{num:272,time:"00:23:09,619 --> 00:23:13,720",arabic:"وَيَبْدُو أَنَّ أَبَاكِ قَدْ عَادَ لِلْبَحْثِ عَنْكُمَا كَثِيرًا.",segs:[{ar:"وَيَبْدُو أَنَّ أَبَاكِ",uz:"aftidan, otangiz"},{ar:"قَدْ عَادَ كَثِيرًا",uz:"ko‘p marta qaytib kelgan"},{ar:"لِلْبَحْثِ عَنْكُمَا",uz:"ikkovingizni qidirish uchun"}],full_uz:"Aftidan, otangiz ikkovingizni qidirish uchun ko‘p marta qaytib kelgan.",note:"عَنْكُمَا — «siz ikkovingizni». ـكُمَا ikkilikdagi murojaat olmoshi."},
{num:273,time:"00:23:13,720 --> 00:23:16,539",arabic:"عَنْكُمَا؟",segs:null,full_uz:"Ikkovingizni?",note:"So‘zlovchi oldingi gapdagi ikkilik olmoshini hayrat bilan takrorlamoqda."},
{num:274,time:"00:23:17,619 --> 00:23:21,519",arabic:"يَبْدُو أَنَّ أُخْتَكِ فَوْزًا ضَاعَتْ أَيْضًا.",segs:[{ar:"يَبْدُو أَنَّ أُخْتَكِ فَوْزًا",uz:"aftidan, opangiz Favz"},{ar:"ضَاعَتْ أَيْضًا",uz:"ham yo‘qolgan"}],full_uz:"Aftidan, opangiz Favz ham yo‘qolgan.",note:"ضَاعَ — «yo‘qoldi, adashib qoldi». فَوْزًا — أُخْتَكِ ga ergashgani uchun mansub."},
{num:275,time:"00:23:22,759 --> 00:23:24,240",arabic:"ضَاعَتْ أُخْتُهَا أَيْضًا؟",segs:null,full_uz:"Uning opasi ham yo‘qolganmi?",note:null},
{num:276,time:"00:23:24,240 --> 00:23:25,659",arabic:"أَجَلْ يَا أُمِّي.",segs:[{ar:"أَجَلْ",uz:"ha"},{ar:"يَا أُمِّي",uz:"ey onajon"}],full_uz:"Ha, onajon.",note:null},
{num:277,time:"00:23:25,659 --> 00:23:27,819",arabic:"فَحِينَ عَادَ وَالِدُ شَهْنَازَ إِلَى التَّاجِرِ...",segs:[{ar:"فَحِينَ عَادَ وَالِدُ شَهْنَازَ",uz:"Shahnozning otasi qaytib kelganida"},{ar:"إِلَى التَّاجِرِ",uz:"savdogarning oldiga"}],full_uz:"Shahnozning otasi savdogarning oldiga qaytib kelganida...",note:null},
{num:278,time:"00:23:27,819 --> 00:23:29,519",arabic:"كَانَ يَسْأَلُهُ عَنِ الْفَتَاتَيْنِ.",segs:[{ar:"كَانَ يَسْأَلُهُ",uz:"undan so‘rardi"},{ar:"عَنِ الْفَتَاتَيْنِ",uz:"ikkala qiz haqida"}],full_uz:"Undan ikkala qiz haqida so‘rardi.",note:"الْفَتَاتَيْنِ — فَتَاةٌ so‘zining ikkilik jar shakli."},
{num:279,time:"00:23:29,519 --> 00:23:33,859",arabic:"وَقَالَ لَهُ التَّاجِرُ إِنَّ إِحْدَى الْفَتَاتَيْنِ قَدْ عَادَتْ وَسَأَلَتْ عَنْهُ.",segs:[{ar:"وَقَالَ لَهُ التَّاجِرُ",uz:"savdogar unga aytgan"},{ar:"إِنَّ إِحْدَى الْفَتَاتَيْنِ قَدْ عَادَتْ",uz:"ikkala qizdan biri qaytib kelganini"},{ar:"وَسَأَلَتْ عَنْهُ",uz:"va uni so‘raganini"}],full_uz:"Savdogar unga ikkala qizdan biri qaytib kelib, uni so‘raganini aytgan.",note:"إِحْدَى الْفَتَاتَيْنِ — «ikki qizdan biri». إِحْدَى muannasdagi «biri» ma’nosini beradi."},
{num:280,time:"00:23:33,859 --> 00:23:36,259",arabic:"إِنَّهَا فَوْزٌ وَلَا شَكَّ.",segs:[{ar:"إِنَّهَا فَوْزٌ",uz:"u Favz"},{ar:"وَلَا شَكَّ",uz:"shubhasiz"}],full_uz:"U, shubhasiz, Favz.",note:null},
{num:281,time:"00:23:36,259 --> 00:23:39,119",arabic:"فَأَنَا لَمْ أَعُدْ إِلَى ذَلِكَ التَّاجِرِ أَبَدًا.",segs:[{ar:"فَأَنَا لَمْ أَعُدْ",uz:"chunki men qaytmadim"},{ar:"إِلَى ذَلِكَ التَّاجِرِ",uz:"o‘sha savdogarning oldiga"},{ar:"أَبَدًا",uz:"hech qachon"}],full_uz:"Chunki men o‘sha savdogarning oldiga hech qachon qaytmadim.",note:"أَعُودُ → لَمْ أَعُدْ: jazmda ajvaf fe’lning o‘rta illat harfi tushadi."},
{num:282,time:"00:23:39,119 --> 00:23:44,879",arabic:"وَأَخْبَرَنِي ذَلِكَ التَّاجِرُ أَنَّ أَبَاكِ عَادَ كَثِيرًا لِيَسْأَلَ عَنْكُمَا.",segs:[{ar:"وَأَخْبَرَنِي ذَلِكَ التَّاجِرُ",uz:"o‘sha savdogar menga aytdi"},{ar:"أَنَّ أَبَاكِ عَادَ كَثِيرًا",uz:"otangiz ko‘p marta qaytib kelganini"},{ar:"لِيَسْأَلَ عَنْكُمَا",uz:"ikkovingiz haqida so‘rash uchun"}],full_uz:"O‘sha savdogar menga otangiz ikkovingiz haqida so‘rash uchun ko‘p marta qaytib kelganini aytdi.",note:null},
{num:283,time:"00:23:44,879 --> 00:23:47,799",arabic:"وَلَكِنَّ أَخْبَارَهُ انْقَطَعَتْ مُنْذُ ثَلَاثِ سَنَوَاتٍ.",segs:[{ar:"وَلَكِنَّ أَخْبَارَهُ انْقَطَعَتْ",uz:"lekin undan xabar kelmay qolgan"},{ar:"مُنْذُ ثَلَاثِ سَنَوَاتٍ",uz:"uch yildan beri"}],full_uz:"Lekin uch yildan beri undan xabar kelmay qolgan.",note:"اِنْقَطَعَتْ أَخْبَارُهُ — «undan xabar kelmay qoldi». مُنْذُ — «...dan beri»."},
{num:284,time:"00:23:59,519 --> 00:24:03,440",arabic:"لَا حَوْلَ وَلَا قُوَّةَ.",segs:null,full_uz:"Kuch ham, quvvat ham yo‘q.",note:"Bu «Allohsiz hech qanday kuch-quvvat yo‘q» ma’nosidagi zikrning qisqa aytilgan qismi."},
{num:285,time:"00:24:03,440 --> 00:24:07,059",arabic:"كَانَ اللَّهُ فِي عَوْنِكِ.",segs:null,full_uz:"Alloh sizga yordamchi bo‘lsin.",note:null},
{num:286,time:"00:24:07,059 --> 00:24:10,220",arabic:"إِلَى السَّاعَةِ لَمْ تُخْبِرْنِي بِقَرَارِكَ يَا ابْنَ حَنْبَلٍ.",segs:[{ar:"إِلَى السَّاعَةِ",uz:"hozirgacha"},{ar:"لَمْ تُخْبِرْنِي بِقَرَارِكَ",uz:"menga qaroringizni aytmadingiz"},{ar:"يَا ابْنَ حَنْبَلٍ",uz:"ey Ibn Hanbal"}],full_uz:"Hozirgacha menga qaroringizni aytmadingiz, Ibn Hanbal.",note:"إِلَى السَّاعَةِ — «shu paytgacha, hozirgacha»."},
{num:287,time:"00:24:10,220 --> 00:24:14,359",arabic:"هَلْ سَتُرَافِقُنِي إِلَى مَكَّةَ الْمُكَرَّمَةِ أَمْ لَا؟",segs:[{ar:"هَلْ سَتُرَافِقُنِي",uz:"menga hamroh bo‘lasizmi"},{ar:"إِلَى مَكَّةَ الْمُكَرَّمَةِ",uz:"Makkai mukarramaga"},{ar:"أَمْ لَا؟",uz:"yoki yo‘qmi?"}],full_uz:"Makkai mukarramaga menga hamroh bo‘lasizmi yoki yo‘qmi?",note:"رَافَقَ — «hamroh bo‘ldi». Bu fe’l bevosita to‘ldiruvchi oladi: رَافَقَنِي — «menga hamroh bo‘ldi»."},
{num:288,time:"00:24:14,359 --> 00:24:16,480",arabic:"مَا زِلْتُ فِي حَيْرَةٍ مِنْ أَمْرِي يَا ابْنَ مَعِينٍ.",segs:[{ar:"مَا زِلْتُ فِي حَيْرَةٍ مِنْ أَمْرِي",uz:"hali ham nima qilishni bilmay ikkilanib turibman"},{ar:"يَا ابْنَ مَعِينٍ",uz:"ey Ibn Ma’in"}],full_uz:"Hali ham nima qilishni bilmay ikkilanib turibman, Ibn Ma’in.",note:"فِي حَيْرَةٍ مِنْ أَمْرِهِ — «nima qilishini bilmay hayron yoki ikkilanib turibdi»."},
{num:289,time:"00:24:16,480 --> 00:24:20,960",arabic:"الدَّعْوَةُ إِلَى بَلَدِ اللَّهِ الْحَرَامِ فِي صُحْبَةٍ أَنْتَ فِيهَا لَا تُرَدُّ.",segs:[{ar:"الدَّعْوَةُ إِلَى بَلَدِ اللَّهِ الْحَرَامِ",uz:"Allohning muqaddas shahriga taklif"},{ar:"فِي صُحْبَةٍ أَنْتَ فِيهَا",uz:"siz ham bor hamrohlar bilan"},{ar:"لَا تُرَدُّ",uz:"rad etilmaydi"}],full_uz:"Siz ham bor hamrohlar bilan Allohning muqaddas shahriga borish taklifi rad etilmaydi.",note:"الْحَرَامُ bu yerda «muqaddas, hurmati saqlanadigan». تُرَدُّ — majhul nisbat: «rad etiladi»."},
{num:290,time:"00:24:20,960 --> 00:24:25,119",arabic:"وَلَكِنْ كَيْفَ سَأَتْرُكُ أُمِّي وَحْدَهَا؟",segs:[{ar:"وَلَكِنْ كَيْفَ سَأَتْرُكُ أُمِّي",uz:"lekin onamni qanday tashlab ketaman"},{ar:"وَحْدَهَا؟",uz:"yolg‘iz?"}],full_uz:"Lekin onamni qanday yolg‘iz tashlab ketaman?",note:null},
{num:291,time:"00:24:25,119 --> 00:24:26,460",arabic:"لَا أَظُنُّنِي أَسْتَطِيعُ ذَلِكَ.",segs:[{ar:"لَا أَظُنُّنِي",uz:"o‘zimni deb o‘ylamayman"},{ar:"أَسْتَطِيعُ ذَلِكَ",uz:"bunga qodirman"}],full_uz:"Bunga qodirman deb o‘ylamayman.",note:"أَظُنُّنِي — «o‘zimni ... deb o‘ylayman»; fe’lga birikkan نِي birinchi shaxsni bildiradi."},
{num:292,time:"00:24:26,460 --> 00:24:28,639",arabic:"لَا تُبَالِغْ كَثِيرًا يَا ابْنَ حَنْبَلٍ.",segs:[{ar:"لَا تُبَالِغْ كَثِيرًا",uz:"juda oshirib yubormang"},{ar:"يَا ابْنَ حَنْبَلٍ",uz:"ey Ibn Hanbal"}],full_uz:"Juda oshirib yubormang, Ibn Hanbal.",note:"بَالَغَ — «oshirib yubordi, haddan ziyod e’tibor berdi»."},
{num:293,time:"00:24:28,640 --> 00:24:30,700",arabic:"لَا تُبَالِغْ كَثِيرًا فِي هَذَا الْأَمْرِ.",segs:[{ar:"لَا تُبَالِغْ كَثِيرًا",uz:"juda oshirib yubormang"},{ar:"فِي هَذَا الْأَمْرِ",uz:"bu masalada"}],full_uz:"Bu masalada juda oshirib yubormang.",note:null},
{num:294,time:"00:24:30,700 --> 00:24:36,540",arabic:"كُلُّنَا يَعْلَمُ أَنَّ سَعَادَةَ أُمِّكَ أَنْ تَرَاكَ وَأَنْتَ تُكْمِلُ سَبِيلَ الْعِلْمِ الَّذِي بَدَأْتَهُ.",segs:[{ar:"كُلُّنَا يَعْلَمُ",uz:"hammamiz bilamiz"},{ar:"أَنَّ سَعَادَةَ أُمِّكَ",uz:"onangizning baxti"},{ar:"أَنْ تَرَاكَ",uz:"sizni ko‘rishida ekanini"},{ar:"وَأَنْتَ تُكْمِلُ سَبِيلَ الْعِلْمِ",uz:"ilm yo‘lini davom ettirayotgan holda"},{ar:"الَّذِي بَدَأْتَهُ",uz:"o‘zingiz boshlagan"}],full_uz:"Onangizning baxti sizni boshlagan ilm yo‘lingizni davom ettirayotgan holda ko‘rishida ekanini hammamiz bilamiz.",note:"وَأَنْتَ تُكْمِلُ — hol gap: «siz davom ettirayotgan holda». الَّذِي سَبِيلَ الْعِلْمِ birikmasini izohlaydi."},
{num:295,time:"00:24:36,540 --> 00:24:39,620",arabic:"وَأَنْ تُصْبِحَ شَيْخًا يُعَلِّمُ النَّاسَ الْعِلْمَ.",segs:[{ar:"وَأَنْ تُصْبِحَ شَيْخًا",uz:"va shayx bo‘lishingizda"},{ar:"يُعَلِّمُ النَّاسَ الْعِلْمَ",uz:"odamlarga ilm o‘rgatadigan"}],full_uz:"Va odamlarga ilm o‘rgatadigan shayx bo‘lishingizda.",note:"عَلَّمَ ikki to‘ldiruvchi olishi mumkin: يُعَلِّمُ النَّاسَ الْعِلْمَ — «odamlarga ilm o‘rgatadi»."},
{num:296,time:"00:24:39,620 --> 00:24:44,020",arabic:"لَا أَنْ تَجْلِسَ إِلَى جِوَارِهَا كَأَيِّ أُمٍّ وَأَيِّ طِفْلٍ.",segs:[{ar:"لَا أَنْ تَجْلِسَ إِلَى جِوَارِهَا",uz:"uning yonida o‘tirishingizda emas"},{ar:"كَأَيِّ أُمٍّ وَأَيِّ طِفْلٍ",uz:"oddiy bir ona va bola kabi"}],full_uz:"Oddiy bir ona va bola kabi uning yonida o‘tirishingizda emas.",note:"إِلَى جِوَارِ — «yonida». كَأَيِّ — «har qanday ... kabi, oddiy ... kabi»."},
{num:297,time:"00:24:44,020 --> 00:24:47,300",arabic:"أَكْرَمَكَ اللَّهُ، أَعْرِفُ ذَلِكَ جَيِّدًا.",segs:[{ar:"أَكْرَمَكَ اللَّهُ",uz:"Alloh sizni aziz qilsin"},{ar:"أَعْرِفُ ذَلِكَ جَيِّدًا",uz:"buni yaxshi bilaman"}],full_uz:"Alloh sizni aziz qilsin, buni yaxshi bilaman.",note:null},
{num:298,time:"00:24:47,300 --> 00:24:50,900",arabic:"وَلَكِنْ لَيْسَ مِنَ الْبِرِّ أَنْ أُفَكِّرَ فِي نَفْسِي وَحَسْبُ.",segs:[{ar:"وَلَكِنْ لَيْسَ مِنَ الْبِرِّ",uz:"lekin yaxshilikdan emas"},{ar:"أَنْ أُفَكِّرَ فِي نَفْسِي وَحَسْبُ",uz:"faqat o‘zimni o‘ylashim"}],full_uz:"Lekin faqat o‘zimni o‘ylashim ota-onaga yaxshilik qilishdan emas.",note:"الْبِرُّ bu kontekstda ota-onaga yaxshilik va hurmat ko‘rsatishni bildiradi. وَحَسْبُ — «xolos»."},
{num:299,time:"00:24:50,900 --> 00:24:53,780",arabic:"وَأَنْ أَنْسَى حَقَّ أُمِّي عَلَيَّ وَإِنْ لَمْ تُجَاهِرْ بِهِ.",segs:[{ar:"وَأَنْ أَنْسَى حَقَّ أُمِّي عَلَيَّ",uz:"va onamning mendagi haqqini unutishim"},{ar:"وَإِنْ لَمْ تُجَاهِرْ بِهِ",uz:"u buni ochiq aytmasa ham"}],full_uz:"Va onam ochiq aytmasa ham, uning mendagi haqqini unutishim ham yaxshilikdan emas.",note:"حَقُّهُ عَلَيَّ — «uning mening zimmamdagi haqqi». وَإِنْ — «garchi, ...sa ham»."},
{num:300,time:"00:24:53,780 --> 00:24:58,520",arabic:"كَمَا تَشَاءُ، فَكِّرْ فِيمَا قُلْتُ لَكَ، وَسَأَنْتَظِرُ جَوَابَكَ.",segs:[{ar:"كَمَا تَشَاءُ",uz:"xohlaganingizdek"},{ar:"فَكِّرْ فِيمَا قُلْتُ لَكَ",uz:"sizga aytganlarim haqida o‘ylang"},{ar:"وَسَأَنْتَظِرُ جَوَابَكَ",uz:"men esa javobingizni kutaman"}],full_uz:"Xohlaganingizdek. Sizga aytganlarim haqida o‘ylang, men javobingizni kutaman.",note:null},
{num:301,time:"00:24:58,519 --> 00:25:02,559",arabic:"سَأَفْعَلُ إِنْ شَاءَ اللَّهُ.",segs:[{ar:"سَأَفْعَلُ",uz:"shunday qilaman"},{ar:"إِنْ شَاءَ اللَّهُ",uz:"Alloh xohlasa"}],full_uz:"Alloh xohlasa, shunday qilaman.",note:null},
{num:302,time:"00:25:02,559 --> 00:25:04,180",arabic:"أَعِدُكَ بِذَلِكَ.",segs:null,full_uz:"Sizga shuni va’da beraman.",note:"وَعَدَ — يَعِدُ — «va’da bermoq». Muzoriyda boshidagi و tushadi: أَعِدُ."},
{num:303,time:"00:25:04,180 --> 00:25:05,440",arabic:"وَالْآنَ يَا ابْنَ حَنْبَلٍ...",segs:[{ar:"وَالْآنَ",uz:"endi esa"},{ar:"يَا ابْنَ حَنْبَلٍ",uz:"ey Ibn Hanbal"}],full_uz:"Endi esa, Ibn Hanbal...",note:null},
{num:304,time:"00:25:05,440 --> 00:25:08,680",arabic:"اِئْذَنْ لِي، لَدَيَّ عَمَلٌ أُنْجِزُهُ.",segs:[{ar:"اِئْذَنْ لِي",uz:"menga ruxsat bering"},{ar:"لَدَيَّ عَمَلٌ",uz:"mening ishim bor"},{ar:"أُنْجِزُهُ",uz:"bajaradigan"}],full_uz:"Menga ruxsat bering, bajaradigan ishim bor.",note:"اِئْذَنْ — أَذِنَ («ruxsat berdi») fe’lining buyrug‘i. أَنْجَزَ — «bajardi, oxiriga yetkazdi»."},
{num:305,time:"00:25:28,519 --> 00:25:30,960",arabic:"لَقَدْ سَمِعْتُ مَا دَارَ بَيْنَكَ وَبَيْنَ يَحْيَى.",segs:[{ar:"لَقَدْ سَمِعْتُ",uz:"eshitdim"},{ar:"مَا دَارَ بَيْنَكَ وَبَيْنَ يَحْيَى",uz:"siz bilan Yahyo o‘rtasida bo‘lgan suhbatni"}],full_uz:"Siz bilan Yahyo o‘rtasida bo‘lgan suhbatni eshitdim.",note:"دَارَ بَيْنَهُمَا حَدِيثٌ — «ikkovi o‘rtasida suhbat bo‘ldi»."},
{num:306,time:"00:25:30,960 --> 00:25:35,779",arabic:"أَنَا أَعْرِفُ أَنَّكَ تَفْعَلُ الْكَثِيرَ مِنْ أَجْلِي.",segs:[{ar:"أَنَا أَعْرِفُ",uz:"men bilaman"},{ar:"أَنَّكَ تَفْعَلُ الْكَثِيرَ",uz:"siz ko‘p ish qilayotganingizni"},{ar:"مِنْ أَجْلِي",uz:"men uchun"}],full_uz:"Men uchun ko‘p ish qilayotganingizni bilaman.",note:"مِنْ أَجْلِ — «uchun, deb». مِنْ أَجْلِي — «men uchun, meni deb»."},
{num:307,time:"00:25:35,779 --> 00:25:39,019",arabic:"وَأَنَّكَ عُدْتَ مِنْ رِحْلَتِكَ إِلَى وَاسِطٍ.",segs:[{ar:"وَأَنَّكَ عُدْتَ",uz:"va qaytganingizni"},{ar:"مِنْ رِحْلَتِكَ إِلَى وَاسِطٍ",uz:"Vositga qilgan safaringizdan"}],full_uz:"Va Vositga qilgan safaringizdan qaytganingizni.",note:null},
{num:308,time:"00:25:39,019 --> 00:25:42,660",arabic:"وَأَنَّكَ لَا تُرِيدُ الِارْتِحَالَ إِلَى مَكَّةَ مِنْ أَجْلِي.",segs:[{ar:"وَأَنَّكَ لَا تُرِيدُ الِارْتِحَالَ",uz:"va safarga chiqishni istamayotganingizni"},{ar:"إِلَى مَكَّةَ",uz:"Makkaga"},{ar:"مِنْ أَجْلِي",uz:"meni deb"}],full_uz:"Va meni deb Makkaga safarga chiqishni istamayotganingizni.",note:"اِرْتِحَالٌ — «safarga chiqish, jo‘nab ketish»; اِرْتَحَلَ fe’lining masdari."},
{num:309,time:"00:25:42,660 --> 00:25:45,079",arabic:"وَلَكِنْ يَا وَلَدِي...",segs:[{ar:"وَلَكِنْ",uz:"lekin"},{ar:"يَا وَلَدِي",uz:"ey bolam"}],full_uz:"Lekin, bolam...",note:null},
{num:310,time:"00:25:45,079 --> 00:25:48,200",arabic:"سَعَادَةُ الْأُمِّ فِي أَنْ تَرَى وَلَدَهَا...",segs:[{ar:"سَعَادَةُ الْأُمِّ",uz:"onaning baxti"},{ar:"فِي أَنْ تَرَى وَلَدَهَا",uz:"farzandini ko‘rishida"}],full_uz:"Onaning baxti farzandini ko‘rishida...",note:null},
{num:311,time:"00:25:48,200 --> 00:25:50,119",arabic:"نَجْمًا...",segs:null,full_uz:"Yulduz bo‘lib...",note:null},
{num:312,time:"00:25:50,119 --> 00:25:51,220",arabic:"سَاطِعًا...",segs:null,full_uz:"Porloq...",note:"سَاطِعٌ — «porloq, yorqin». Oldingi banddagi نَجْمًا ning sifati bo‘lgani uchun mansub."},
{num:313,time:"00:25:51,220 --> 00:25:52,900",arabic:"يَتَلَأْلَأُ فِي دُنْيَا النَّاسِ.",segs:[{ar:"يَتَلَأْلَأُ",uz:"porlab turgan"},{ar:"فِي دُنْيَا النَّاسِ",uz:"odamlar dunyosida"}],full_uz:"Odamlar dunyosida porlab turgan.",note:"تَلَأْلَأَ — يَتَلَأْلَأُ — «porlamoq, tovlanmoq»."},
{num:314,time:"00:25:52,900 --> 00:25:57,019",arabic:"لَا أَنْ تَرَاهُ إِلَى جِوَارِهَا خَافِتًا...",segs:[{ar:"لَا أَنْ تَرَاهُ",uz:"uni ko‘rishida emas"},{ar:"إِلَى جِوَارِهَا",uz:"o‘z yonida"},{ar:"خَافِتًا",uz:"xira holda"}],full_uz:"Uni o‘z yonida xira holda ko‘rishida emas...",note:"خَافِتٌ — «xira, sust». Bu yerda oldingi «porloq yulduz» tasviriga qarama-qarshi qo‘llangan."},
{num:315,time:"00:25:57,019 --> 00:25:57,839",arabic:"كَاسِفَ الْبَالِ.",segs:null,full_uz:"Ko‘ngli g‘ash holda.",note:"كَاسِفُ الْبَالِ — «xafa, ko‘ngli g‘ash»."},
{num:316,time:"00:25:57,839 --> 00:26:05,839",arabic:"ثُمَّ كَيْفَ لِي أَنْ أَقْبَلَ أَنْ تَبْقَى إِلَى جِوَارِي وَرِفَاقُكَ فِي الدَّرْبِ...",segs:[{ar:"ثُمَّ كَيْفَ لِي أَنْ أَقْبَلَ",uz:"yana qanday rozi bo‘la olaman"},{ar:"أَنْ تَبْقَى إِلَى جِوَارِي",uz:"yonimda qolishingizga"},{ar:"وَرِفَاقُكَ فِي الدَّرْبِ",uz:"yo‘ldoshlaringiz esa"}],full_uz:"Yana qanday qilib yonimda qolishingizga rozi bo‘la olaman, yo‘ldoshlaringiz esa...",note:"كَيْفَ لِي أَنْ... — «qanday qilib ... qila olaman?». رِفَاقٌ — رَفِيقٌ («hamroh»)ning ko‘pligi."},
{num:317,time:"00:26:05,839 --> 00:26:09,879",arabic:"يَسْتَأْثِرُونَ دُونَكَ بِعُلَمَاءِ الْحِجَازِ وَغَيْرِهَا.",segs:[{ar:"يَسْتَأْثِرُونَ دُونَكَ",uz:"sizni chetda qoldirib, yolg‘iz o‘zlari bahramand bo‘ladilar"},{ar:"بِعُلَمَاءِ الْحِجَازِ وَغَيْرِهَا",uz:"Hijoz va boshqa joylarning olimlaridan"}],full_uz:"Hijoz va boshqa joylarning olimlaridan sizsiz, yolg‘iz o‘zlari bahramand bo‘ladilar.",note:"اِسْتَأْثَرَ بِـ — «bir narsadan boshqalarni chetda qoldirib, o‘zi foydalanib qoldi»."},
{num:318,time:"00:26:09,879 --> 00:26:14,980",arabic:"حَتَّى إِنْ كُنْتِ تَسْتَطِيعِينَ احْتِمَالَ فِرَاقِي يَا أُمَّاهُ، فَأَنَا مَنْ لَا يَسْتَطِيعُ ذَلِكَ.",segs:[{ar:"حَتَّى إِنْ كُنْتِ تَسْتَطِيعِينَ",uz:"hatto siz qodir bo‘lsangiz ham"},{ar:"احْتِمَالَ فِرَاقِي",uz:"mendan ayriliqqa chidashga"},{ar:"يَا أُمَّاهُ",uz:"ey onajon"},{ar:"فَأَنَا مَنْ لَا يَسْتَطِيعُ ذَلِكَ",uz:"men bunga qodir emasman"}],full_uz:"Mendan ayriliqqa siz chiday olsangiz ham, onajon, men bunga chiday olmayman.",note:"اِحْتِمَالٌ bu yerda «ehtimol» emas, «chidash, ko‘tarish» ma’nosida."},
{num:319,time:"00:26:14,980 --> 00:26:19,519",arabic:"وَأَيُّ أُمٍّ تَسْتَطِيعُ احْتِمَالَ فِرَاقِ فِلْذَةِ كَبِدِهَا؟",segs:[{ar:"وَأَيُّ أُمٍّ تَسْتَطِيعُ",uz:"qaysi ona qodir bo‘la oladi"},{ar:"احْتِمَالَ فِرَاقِ",uz:"ayriliqqa chidashga"},{ar:"فِلْذَةِ كَبِدِهَا؟",uz:"jigarbandining?"}],full_uz:"Qaysi ona jigarbandining ayrilig‘iga chiday oladi?",note:"فِلْذَةُ كَبِدِهَا — so‘zma-so‘z «jigarining bir bo‘lagi»; mehr bilan farzandni bildiradi."},
{num:320,time:"00:26:19,519 --> 00:26:23,859",arabic:"اِعْلَمْ يَا بُنَيَّ أَنَّ كُلَّ لَحْظَةٍ تَمُرُّ فِي غِيَابِكَ...",segs:[{ar:"اِعْلَمْ يَا بُنَيَّ",uz:"bilib qo‘ying, bolajonim"},{ar:"أَنَّ كُلَّ لَحْظَةٍ تَمُرُّ",uz:"o‘tadigan har bir lahzani"},{ar:"فِي غِيَابِكَ",uz:"siz yo‘qligingizda"}],full_uz:"Bilib qo‘ying, bolajonim, siz yo‘qligingizda o‘tadigan har bir lahzani...",note:"بُنَيَّ — اِبْنٌ so‘zining erkalash shakli: «bolajonim, o‘g‘ilcham»."},
{num:321,time:"00:26:23,859 --> 00:26:27,559",arabic:"أَحْسَبُهَا وَكَأَنَّهَا دَهْرٌ بِأَكْمَلِهِ.",segs:[{ar:"أَحْسَبُهَا",uz:"uni his qilaman"},{ar:"وَكَأَنَّهَا دَهْرٌ بِأَكْمَلِهِ",uz:"go‘yo butun bir umrdek"}],full_uz:"Go‘yo butun bir umrdek his qilaman.",note:"بِأَكْمَلِهِ — «butunicha, to‘lig‘icha». دَهْرٌ — uzoq vaqt, umr."},
{num:322,time:"00:26:27,559 --> 00:26:35,000",arabic:"وَلَكِنْ يَا بُنَيَّ عَلَيْكَ أَنْ تَنْسَى كُلَّ هَذَا.",segs:[{ar:"وَلَكِنْ يَا بُنَيَّ",uz:"lekin, bolajonim"},{ar:"عَلَيْكَ أَنْ تَنْسَى",uz:"unutishingiz kerak"},{ar:"كُلَّ هَذَا",uz:"bularning barchasini"}],full_uz:"Lekin, bolajonim, bularning barchasini unutishingiz kerak.",note:"عَلَيْكَ أَنْ + fe’l — «siz ... qilishingiz kerak»."},
{num:323,time:"00:26:35,000 --> 00:26:40,500",arabic:"وَأَنْ تَضَعَ نُصْبَ عَيْنَيْكَ مَا تُفَكِّرُ بِهِ فَقَطْ.",segs:[{ar:"وَأَنْ تَضَعَ نُصْبَ عَيْنَيْكَ",uz:"va ko‘z oldingizga qo‘yishingiz kerak"},{ar:"مَا تُفَكِّرُ بِهِ فَقَطْ",uz:"faqat o‘ylayotgan maqsadingizni"}],full_uz:"Va ko‘z oldingizga faqat o‘ylayotgan maqsadingizni qo‘yishingiz kerak.",note:"وَضَعَ نُصْبَ عَيْنَيْهِ — «doimo ko‘z oldida tutdi, asosiy maqsad qilib oldi»."},
{num:324,time:"00:26:40,500 --> 00:26:42,599",arabic:"وَمَا تَصْبُو إِلَيْهِ.",segs:null,full_uz:"Va intilayotgan narsangizni.",note:"صَبَا إِلَى — يَصْبُو إِلَى — «intilmoq, ko‘ngli tortmoq»."},
{num:325,time:"00:26:42,599 --> 00:26:46,000",arabic:"إِنْ كُنْتَ تُرِيدُ سَعَادَتِي.",segs:[{ar:"إِنْ كُنْتَ تُرِيدُ",uz:"agar istasangiz"},{ar:"سَعَادَتِي",uz:"mening baxtimni"}],full_uz:"Agar mening baxtimni istasangiz.",note:null},
{num:326,time:"00:26:46,000 --> 00:26:51,819",arabic:"وَهَذَا مَعْنَاهُ أَنْ تُرَافِقَ ابْنَ مَعِينٍ فِي رِحْلَتِهِ.",segs:[{ar:"وَهَذَا مَعْنَاهُ",uz:"buning ma’nosi"},{ar:"أَنْ تُرَافِقَ ابْنَ مَعِينٍ",uz:"Ibn Ma’inga hamroh bo‘lishingiz"},{ar:"فِي رِحْلَتِهِ",uz:"uning safarida"}],full_uz:"Bu Ibn Ma’inga safarida hamroh bo‘lishingiz kerak degani.",note:null},
{num:327,time:"00:26:51,819 --> 00:26:56,500",arabic:"هَلْ فَهِمْتَ يَا وَلَدِي؟",segs:[{ar:"هَلْ فَهِمْتَ",uz:"tushundingizmi"},{ar:"يَا وَلَدِي؟",uz:"ey bolam?"}],full_uz:"Tushundingizmi, bolam?",note:null},
{num:328,time:"00:26:57,559 --> 00:27:16,039",arabic:"إِنَّ أَفْعَالَ الْخَلْقِ جَمِيعَهَا مِنْ حَرَكَاتٍ وَسُكُونٍ فِي الْأَقْوَالِ وَالْأَفْعَالِ...",segs:[{ar:"إِنَّ أَفْعَالَ الْخَلْقِ جَمِيعَهَا",uz:"albatta, maxluqlarning barcha ishlari"},{ar:"مِنْ حَرَكَاتٍ وَسُكُونٍ",uz:"harakat va harakatsizlikdan iborat"},{ar:"فِي الْأَقْوَالِ وَالْأَفْعَالِ",uz:"so‘zlar va xatti-harakatlardagi"}],full_uz:"Albatta, maxluqlarning so‘zlari va xatti-harakatlaridagi harakat hamda harakatsizlikdan iborat barcha ishlari...",note:"جَمِيعَهَا oldingi أَفْعَالَ so‘zini ta’kidlaydi: «ularning barchasi». سُكُونٌ — «harakatsizlik, tinch holat»."},
{num:329,time:"00:27:16,039 --> 00:27:19,059",arabic:"لَيْسَتْ مِنْ خَلْقِ اللَّهِ عَزَّ وَجَلَّ.",segs:[{ar:"لَيْسَتْ مِنْ خَلْقِ اللَّهِ",uz:"Alloh yaratgan narsalardan emas"},{ar:"عَزَّ وَجَلَّ",uz:"U aziz va ulug‘dir"}],full_uz:"Alloh yaratgan narsalardan emas. U aziz va ulug‘dir.",note:"لَيْسَتْ oldingi banddagi أَفْعَالٌ ga tegishli. G‘ayri oqil ko‘plik bilan birlik muannas shakli ishlatiladi."},
{num:330,time:"00:27:19,059 --> 00:27:21,559",arabic:"لِمَاذَا؟",segs:null,full_uz:"Nega?",note:null},
{num:331,time:"00:27:21,559 --> 00:27:26,220",arabic:"لِأَنَّهُ لَا يَنْبَغِي لِلَّهِ إِلَّا فِعْلُ الْأَصْلَحِ لِعِبَادِهِ.",segs:[{ar:"لِأَنَّهُ لَا يَنْبَغِي لِلَّهِ",uz:"chunki Allohga munosib emas"},{ar:"إِلَّا فِعْلُ الْأَصْلَحِ",uz:"faqat eng yaxshisini qilishdan boshqasi"},{ar:"لِعِبَادِهِ",uz:"bandalari uchun"}],full_uz:"Chunki Allohga bandalari uchun faqat eng yaxshisini qilish munosibdir.",note:"الْأَصْلَحُ — «eng yaxshi, eng manfaatli». لَا ... إِلَّا ... cheklashni bildiradi."},
{num:332,time:"00:27:26,220 --> 00:27:32,100",arabic:"وَكَثِيرٌ مِنْ أَفْعَالِ الْخَلْقِ لَيْسَتْ صَالِحَةً.",segs:[{ar:"وَكَثِيرٌ مِنْ أَفْعَالِ الْخَلْقِ",uz:"maxluqlarning ko‘pgina ishlari esa"},{ar:"لَيْسَتْ صَالِحَةً",uz:"yaxshi emas"}],full_uz:"Maxluqlarning ko‘pgina ishlari esa yaxshi emas.",note:null},
{num:333,time:"00:27:32,100 --> 00:27:39,480",arabic:"هَا قَدْ أَصْبَحْتَ وَاحِدًا مِنْهُمْ وَتَعْرِفُ عَنْهُمْ كُلَّ شَيْءٍ.",segs:[{ar:"هَا قَدْ أَصْبَحْتَ وَاحِدًا مِنْهُمْ",uz:"mana, ulardan biriga aylandingiz"},{ar:"وَتَعْرِفُ عَنْهُمْ كُلَّ شَيْءٍ",uz:"va ular haqida hamma narsani bilasiz"}],full_uz:"Mana, ulardan biriga aylandingiz va ular haqida hamma narsani bilasiz.",note:null},
{num:334,time:"00:27:39,480 --> 00:27:41,640",arabic:"فَمَا الَّذِي تَنْتَظِرُهُ؟",segs:null,full_uz:"Unda nimani kutyapsiz?",note:null},
{num:335,time:"00:27:41,640 --> 00:27:45,839",arabic:"الْمَجْدُ يَنْتَظِرُكَ وَالتَّأَخُّرُ عَنِ انْتِهَازِهِ يُرْدِيكَ.",segs:[{ar:"الْمَجْدُ يَنْتَظِرُكَ",uz:"shon-shuhrat sizni kutmoqda"},{ar:"وَالتَّأَخُّرُ عَنِ انْتِهَازِهِ",uz:"uni qo‘lga kiritishda kechikish esa"},{ar:"يُرْدِيكَ",uz:"sizni halok qiladi"}],full_uz:"Shon-shuhrat sizni kutmoqda, uni qo‘lga kiritishda kechikish esa sizni halok qiladi.",note:"اِنْتَهَزَ — «fursatdan foydalandi». أَرْدَى — يُرْدِي — «halok qilmoq»."},
{num:336,time:"00:27:45,839 --> 00:27:49,640",arabic:"قَدْ وَاتَتْكَ الْفُرْصَةُ فَاغْتَنِمْهَا.",segs:[{ar:"قَدْ وَاتَتْكَ الْفُرْصَةُ",uz:"imkoniyat sizga yuzlandi"},{ar:"فَاغْتَنِمْهَا",uz:"bas, undan foydalaning"}],full_uz:"Imkoniyat tug‘ildi, undan foydalaning.",note:"وَاتَتْهُ الْفُرْصَةُ — «unga qulay imkoniyat tug‘ildi». اِغْتَنَمَ — «g‘animat bildi, foydalanib qoldi»."},
{num:337,time:"00:27:56,220 --> 00:27:58,000",arabic:"مِسْكِينَةٌ يَا فَوْزُ.",segs:[{ar:"مِسْكِينَةٌ",uz:"bechorasiz"},{ar:"يَا فَوْزُ",uz:"ey Favz"}],full_uz:"Bechora Favz.",note:null},
{num:338,time:"00:27:58,000 --> 00:28:01,299",arabic:"إِذَنْ فَقَدْ جَرَى لَكِ مَا جَرَى لِي.",segs:[{ar:"إِذَنْ فَقَدْ جَرَى لَكِ",uz:"demak, sizning boshingizga ham tushibdi"},{ar:"مَا جَرَى لِي",uz:"mening boshimga tushgan narsa"}],full_uz:"Demak, mening boshimga tushgan narsa sizning boshingizga ham tushibdi.",note:"جَرَى لَهُ — «uning boshiga tushdi, u bilan sodir bo‘ldi»."},
{num:339,time:"00:28:01,299 --> 00:28:06,279",arabic:"أَرْجُو أَلَّا يَكُونَ قَدْ أَصَابَكِ مَكْرُوهٌ.",segs:[{ar:"أَرْجُو",uz:"umid qilaman"},{ar:"أَلَّا يَكُونَ قَدْ أَصَابَكِ مَكْرُوهٌ",uz:"sizga biror yomonlik yetmagan bo‘lsin"}],full_uz:"Umid qilamanki, sizga biror yomonlik yetmagandir.",note:"أَصَابَهُ مَكْرُوهٌ — «unga yomonlik yoki kulfat yetdi». أَلَّا = أَنْ + لَا."},
{num:340,time:"00:28:06,279 --> 00:28:19,960",arabic:"تُرَى هَلِ اهْتَدَيْتِ إِلَى أَبِيكِ؟",segs:[{ar:"تُرَى",uz:"qiziq"},{ar:"هَلِ اهْتَدَيْتِ إِلَى أَبِيكِ؟",uz:"otangizni topdingizmi?"}],full_uz:"Qiziq, otangizni topdingizmi?",note:"تُرَى savol oldidan o‘ychanlikni bildiradi: «qiziq, ...mikan?». اِهْتَدَى إِلَى — «yo‘lini topdi, izlab topdi»."},
{num:341,time:"00:28:19,960 --> 00:28:22,160",arabic:"أَمْ أَنَّكِ مِثْلِي...",segs:null,full_uz:"Yoki siz ham men kabi...",note:null},
{num:342,time:"00:28:22,160 --> 00:28:25,579",arabic:"تَتَلَقَّفُكِ الطُّرُقَاتُ وَالْبُيُوتُ.",segs:[{ar:"تَتَلَقَّفُكِ",uz:"sizni biridan biri qabul qilib olmoqda"},{ar:"الطُّرُقَاتُ وَالْبُيُوتُ",uz:"ko‘chalar va uylar"}],full_uz:"Ko‘chama-ko‘cha, uyma-uy sarson bo‘lib yuribsiz.",note:"تَلَقَّفَ — «tezda tutib oldi, ilib oldi». Bu yerda ko‘chalar va uylar orasida sarson yurish tasvirlangan."},
{num:343,time:"00:28:25,579 --> 00:28:29,879",arabic:"وَلَا أَدْرِي كَيْفَ هُوَ مَصِيرُكِ الْآنَ يَا أُخْتَاهُ.",segs:[{ar:"وَلَا أَدْرِي",uz:"bilmayman"},{ar:"كَيْفَ هُوَ مَصِيرُكِ الْآنَ",uz:"hozir taqdiringiz qanday kechayotganini"},{ar:"يَا أُخْتَاهُ",uz:"ey opajon"}],full_uz:"Hozir taqdiringiz qanday kechayotganini bilmayman, opajon.",note:"مَصِيرٌ — «taqdir, oqibat, borib yetiladigan holat»."},
{num:344,time:"00:32:55,579 --> 00:32:56,579",arabic:"أَسْمِعْنَا مَا عِنْدَكَ.",segs:[{ar:"أَسْمِعْنَا",uz:"bizga aytib bering"},{ar:"مَا عِنْدَكَ",uz:"sizdagi gaplarni"}],full_uz:"Bizga bor gaplaringizni aytib bering.",note:"أَسْمَعَ — «eshittirdi». أَسْمِعْنَا — so‘zma-so‘z «bizga eshittiring»."},
{num:345,time:"00:33:01,579 --> 00:33:02,579",arabic:"بِأَمْرِ مَوْلَايَ.",segs:null,full_uz:"Hukmdorimning amri bilan.",note:null},
{num:346,time:"00:33:08,579 --> 00:33:09,579",arabic:"مَا الْعَمَلُ؟",segs:null,full_uz:"Nima qilish kerak?",note:"مَا الْعَمَلُ؟ — «nima qilamiz, qanday chora bor?» degan odatiy savol."},
{num:347,time:"00:33:10,579 --> 00:33:11,579",arabic:"إِنَّهَا لَا تَكْفِي.",segs:null,full_uz:"Bu yetmaydi.",note:null},
{num:348,time:"00:33:16,579 --> 00:33:17,579",arabic:"مَا هَذَا؟",segs:null,full_uz:"Bu nima?",note:null},
{num:349,time:"00:33:17,579 --> 00:33:18,579",arabic:"مِائَةُ دِرْهَمٍ.",segs:null,full_uz:"Yuz dirham.",note:"مِائَةٌ dan keyingi sanalmish birlik va majrur keladi: مِائَةُ دِرْهَمٍ."},
{num:350,time:"00:33:21,579 --> 00:33:23,579",arabic:"وَأَظُنُّ أَنَّهَا إِلَى مَا مَعَكَ مِنْ نُقُودٍ تَكْفِي.",segs:[{ar:"وَأَظُنُّ أَنَّهَا",uz:"menimcha, bu"},{ar:"إِلَى مَا مَعَكَ مِنْ نُقُودٍ",uz:"yoningizdagi pulga qo‘shilsa"},{ar:"تَكْفِي",uz:"yetadi"}],full_uz:"Menimcha, bu yoningizdagi pulga qo‘shilsa, yetadi.",note:"إِلَى bu yerda qo‘shishni anglatadi: «...ga qo‘shib, ...bilan birga»."},
{num:351,time:"00:33:25,579 --> 00:33:32,259",arabic:"مَا بِكَ لَا تَتَكَلَّمُ؟",segs:[{ar:"مَا بِكَ",uz:"sizga nima bo‘ldi"},{ar:"لَا تَتَكَلَّمُ؟",uz:"gapirmayapsiz?"}],full_uz:"Nima bo‘ldi, nega gapirmayapsiz?",note:null},
{num:352,time:"00:33:32,259 --> 00:33:35,119",arabic:"هَلْ تَكْفِي أَمْ لَا؟",segs:null,full_uz:"Yetadimi yoki yo‘qmi?",note:null},
{num:353,time:"00:33:35,119 --> 00:33:36,359",arabic:"لَنْ آخُذَهَا يَا أُمِّي.",segs:[{ar:"لَنْ آخُذَهَا",uz:"buni olmayman"},{ar:"يَا أُمِّي",uz:"ey onajon"}],full_uz:"Buni olmayman, onajon.",note:null},
{num:354,time:"00:33:36,359 --> 00:33:37,740",arabic:"فَهَذِهِ نَفَقَتُكِ.",segs:null,full_uz:"Axir bu sizning xarajat pulingiz.",note:"نَفَقَةٌ — tirikchilik uchun sarflanadigan pul, xarajat."},
{num:355,time:"00:33:37,740 --> 00:33:40,019",arabic:"نَفَقَتِي؟",segs:null,full_uz:"Mening xarajat pulim?",note:null},
{num:356,time:"00:33:40,019 --> 00:33:42,179",arabic:"وَمَا نَفَقَتِي أَيُّهَا الْفَتَى الشَّيْخُ؟",segs:[{ar:"وَمَا نَفَقَتِي",uz:"mening xarajatim qancha bo‘lardi"},{ar:"أَيُّهَا الْفَتَى الشَّيْخُ؟",uz:"ey yosh shayx?"}],full_uz:"Mening xarajatim qancha bo‘lardi, ey yosh shayx?",note:"الْفَتَى الشَّيْخُ — yosh bo‘lsa-da, kattalardek mulohaza qiladigan kishiga mehr yoki hazil bilan murojaat."},
{num:357,time:"00:33:42,179 --> 00:33:45,779",arabic:"الْعَجُوزُ تَكْفِيهَا التَّمْرَةُ أَوِ التَّمْرَتَانِ.",segs:[{ar:"الْعَجُوزُ تَكْفِيهَا",uz:"kampirga yetadi"},{ar:"التَّمْرَةُ أَوِ التَّمْرَتَانِ",uz:"bitta yoki ikkita xurmo"}],full_uz:"Kampirga bitta yoki ikkita xurmo yetadi.",note:"التَّمْرَتَانِ — ikkilikning raf’ shakli. أَوْ keyingi الْ bilan tutashtirilganda أَوِ deb o‘qiladi."},
{num:358,time:"00:33:45,779 --> 00:33:48,079",arabic:"وَأَسْكُنُ فِي دَارِ أَبِيكَ.",segs:[{ar:"وَأَسْكُنُ",uz:"va yashayman"},{ar:"فِي دَارِ أَبِيكَ",uz:"otangizning uyida"}],full_uz:"Otangizning uyida yashayman.",note:null},
{num:359,time:"00:33:48,079 --> 00:33:50,519",arabic:"وَلَدَيَّ الْأُجْرَةُ مِنْ دُكَّانِ أَبِيكَ.",segs:[{ar:"وَلَدَيَّ الْأُجْرَةُ",uz:"ijara haqim ham bor"},{ar:"مِنْ دُكَّانِ أَبِيكَ",uz:"otangizning do‘konidan"}],full_uz:"Otangizning do‘konidan keladigan ijara haqim ham bor.",note:"أُجْرَةٌ — «haq, ijara puli, ish haqi»; ma’no kontekstga qarab aniqlanadi."},
{num:360,time:"00:33:50,519 --> 00:33:52,079",arabic:"فَمَا حَاجَتِي بِمِائَةِ دِرْهَمٍ؟",segs:[{ar:"فَمَا حَاجَتِي",uz:"unda menga nima ehtiyoj bor"},{ar:"بِمِائَةِ دِرْهَمٍ؟",uz:"yuz dirhamga?"}],full_uz:"Unda menga yuz dirhamning nima keragi bor?",note:null},
{num:361,time:"00:33:52,740 --> 00:33:53,639",arabic:"وَلَكِنْ يَا أُمِّي...",segs:[{ar:"وَلَكِنْ",uz:"lekin"},{ar:"يَا أُمِّي",uz:"ey onajon"}],full_uz:"Lekin, onajon...",note:null},
{num:362,time:"00:33:53,640 --> 00:33:55,960",arabic:"لَا تَسْتَدْرِكْ دَائِمًا عَلَى كَلَامِي.",segs:[{ar:"لَا تَسْتَدْرِكْ دَائِمًا",uz:"doim tuzatish kiritavermang"},{ar:"عَلَى كَلَامِي",uz:"gapimga"}],full_uz:"Gapimga doim e’tiroz bildiravermang.",note:"اِسْتَدْرَكَ عَلَى كَلَامِهِ — «uning gapiga tuzatish yoki e’tiroz bildirdi»."},
{num:363,time:"00:33:55,960 --> 00:33:59,500",arabic:"هَلْ تُرِيدُ الْخُرُوجَ إِلَى مَكَّةَ الْمُكَرَّمَةِ أَمْ لَا؟",segs:[{ar:"هَلْ تُرِيدُ الْخُرُوجَ",uz:"yo‘lga chiqishni istaysizmi"},{ar:"إِلَى مَكَّةَ الْمُكَرَّمَةِ",uz:"Makkai mukarramaga"},{ar:"أَمْ لَا؟",uz:"yoki yo‘qmi?"}],full_uz:"Makkai mukarramaga yo‘lga chiqishni istaysizmi yoki yo‘qmi?",note:null},
{num:364,time:"00:33:59,500 --> 00:34:00,380",arabic:"أَجَلْ، غَيْرَ أَنَّ...",segs:[{ar:"أَجَلْ",uz:"ha"},{ar:"غَيْرَ أَنَّ",uz:"lekin"}],full_uz:"Ha, lekin...",note:"غَيْرَ أَنَّ — «lekin, biroq»."},
{num:365,time:"00:34:00,380 --> 00:34:02,360",arabic:"إِذَنْ خُذْهَا دُونَ نِقَاشٍ.",segs:[{ar:"إِذَنْ خُذْهَا",uz:"unda buni oling"},{ar:"دُونَ نِقَاشٍ",uz:"tortishmasdan"}],full_uz:"Unda buni tortishmasdan oling.",note:null},
{num:366,time:"00:34:02,360 --> 00:34:05,840",arabic:"هَيَّا أَيُّهَا الْفَتَى.",segs:[{ar:"هَيَّا",uz:"qani"},{ar:"أَيُّهَا الْفَتَى",uz:"ey yigit"}],full_uz:"Qani, ey yigit.",note:null},
{num:367,time:"00:34:05,840 --> 00:34:11,140",arabic:"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ.",segs:[{ar:"لَا حَوْلَ وَلَا قُوَّةَ",uz:"hech qanday kuch-quvvat yo‘q"},{ar:"إِلَّا بِاللَّهِ",uz:"faqat Allohning yordami bilangina"}],full_uz:"Kuch-quvvat faqat Allohning yordami bilandir.",note:"Bu zikr ojizlikni tan olish va Allohdan madad so‘rashni bildiradi."},
{num:368,time:"00:34:11,140 --> 00:34:15,140",arabic:"مَاذَا أَفْعَلُ بِهَذَا الْفَتَى الْعَنِيدِ؟",segs:[{ar:"مَاذَا أَفْعَلُ",uz:"nima qilay"},{ar:"بِهَذَا الْفَتَى الْعَنِيدِ؟",uz:"bu qaysar yigitni?"}],full_uz:"Bu qaysar yigitni nima qilay?",note:"عَنِيدٌ — «qaysar, o‘z gapidan qaytmaydigan»."},
{num:369,time:"00:34:15,140 --> 00:34:15,640",arabic:"خُذْ.",segs:null,full_uz:"Oling.",note:"خُذْ — أَخَذَ («oldi») fe’lining buyruq shakli."},
{num:370,time:"00:34:15,639 --> 00:34:24,699",arabic:"أَخْبَارُكُمْ مَوْثُوقَةٌ يَا أَبَا الْعَبَّاسِ؟",segs:[{ar:"أَخْبَارُكُمْ مَوْثُوقَةٌ",uz:"xabarlaringiz ishonchlimi"},{ar:"يَا أَبَا الْعَبَّاسِ؟",uz:"ey Abu Abbos?"}],full_uz:"Xabarlaringiz ishonchlimi, Abu Abbos?",note:"مَوْثُوقٌ — «ishonchli». So‘roq ba’zan alohida so‘roq yuklamasisiz, ohang orqali ifodalanadi."},
{num:371,time:"00:34:24,699 --> 00:34:29,879",arabic:"ابْنُ الرَّبِيعِ لَا يَرْفَعُ إِلَى مَوْلَاهُ الرَّشِيدِ إِلَّا بَعْدَ تَمْحِيصٍ وَتَبَيُّنٍ.",segs:[{ar:"ابْنُ الرَّبِيعِ لَا يَرْفَعُ",uz:"Ibn Rabi’ taqdim etmaydi"},{ar:"إِلَى مَوْلَاهُ الرَّشِيدِ",uz:"hukmdori Rashidga"},{ar:"إِلَّا بَعْدَ تَمْحِيصٍ وَتَبَيُّنٍ",uz:"faqat sinchiklab tekshirib, aniqlik kiritgandan keyingina"}],full_uz:"Ibn Rabi’ hukmdori Rashidga xabarni faqat sinchiklab tekshirib, aniqlik kiritgandan keyingina taqdim etadi.",note:"رَفَعَ إِلَى yuqori mansabdor bilan kelganda «ma’lum qildi, taqdim etdi». تَمْحِيصٌ — sinchiklab tekshirish."},
{num:372,time:"00:34:29,879 --> 00:34:36,879",arabic:"وَقَدْ تَأَكَّدْنَا مِنْ صِحَّتِهَا بِطُرُقٍ شَتَّى وَبِعُيُونٍ رَاصِدَةٍ لَا تُخْطِئُ.",segs:[{ar:"وَقَدْ تَأَكَّدْنَا مِنْ صِحَّتِهَا",uz:"ularning to‘g‘riligiga ishonch hosil qildik"},{ar:"بِطُرُقٍ شَتَّى",uz:"turli yo‘llar bilan"},{ar:"وَبِعُيُونٍ رَاصِدَةٍ",uz:"va kuzatuvchi xufiyalar orqali"},{ar:"لَا تُخْطِئُ",uz:"xato qilmaydigan"}],full_uz:"Ularning to‘g‘riligiga turli yo‘llar va xato qilmaydigan kuzatuvchi xufiyalar orqali ishonch hosil qildik.",note:"عُيُونٌ aslida «ko‘zlar», bu yerda «xufiyalar, ma’lumot yig‘uvchilar». شَتَّى — «turli, xilma-xil»."},
{num:373,time:"00:34:36,879 --> 00:34:43,019",arabic:"وَقَدِ انْتَهَيْنَا إِلَى أَنَّ بَيْتَ الْعَنْكَبُوتِ يَنْسُجُهُ بِشْرٌ الْمَرِيسِيُّ...",segs:[{ar:"وَقَدِ انْتَهَيْنَا إِلَى أَنَّ",uz:"shunday xulosaga keldikki"},{ar:"بَيْتَ الْعَنْكَبُوتِ",uz:"o‘rgimchak uyasini"},{ar:"يَنْسُجُهُ بِشْرٌ الْمَرِيسِيُّ",uz:"Bishr Marisiy to‘qimoqda"}],full_uz:"Shunday xulosaga keldikki, o‘rgimchak uyasini Bishr Marisiy to‘qimoqda...",note:"اِنْتَهَى إِلَى أَنَّ — «...degan xulosaga keldi». نَسَجَ — يَنْسُجُ — «to‘qimoq»."},
{num:374,time:"00:34:43,019 --> 00:34:45,400",arabic:"وَثُمَامَةُ بْنُ الْأَشْرَسِ...",segs:null,full_uz:"Va Sumoma ibn Ashras...",note:null},
{num:375,time:"00:34:45,400 --> 00:34:48,840",arabic:"وَغَيْرُهُمَا مِمَّنْ وَرَدَتْ أَسْمَاؤُهُمْ فِي الرِّقَاعِ.",segs:[{ar:"وَغَيْرُهُمَا",uz:"va ulardan boshqa kishilar"},{ar:"مِمَّنْ وَرَدَتْ أَسْمَاؤُهُمْ",uz:"ismlari keltirilganlardan"},{ar:"فِي الرِّقَاعِ",uz:"yozuvlarda"}],full_uz:"Va yozuvlarda ismlari keltirilgan boshqa kishilar.",note:"رِقَاعٌ — رُقْعَةٌ ning ko‘pligi; bu yerda xat yoki qayd yozilgan qog‘ozlar."},
{num:376,time:"00:34:48,840 --> 00:34:53,239",arabic:"وَهُمْ يَقُومُونَ بِنَشْرِ تَعَالِيمِهِمْ...",segs:[{ar:"وَهُمْ يَقُومُونَ بِنَشْرِ",uz:"ular tarqatmoqdalar"},{ar:"تَعَالِيمِهِمْ",uz:"o‘z ta’limotlarini"}],full_uz:"Ular o‘z ta’limotlarini tarqatmoqdalar...",note:"قَامَ بِـ + masdar bir ishni bajarishni bildiradi: يَقُومُونَ بِنَشْرِ — «tarqatmoqdalar»."},
{num:377,time:"00:34:53,239 --> 00:34:56,539",arabic:"وَآرَائِهِمْ بَيْنَ الْفِتْيَةِ وَالْيَافِعِينَ.",segs:[{ar:"وَآرَائِهِمْ",uz:"va o‘z qarashlarini"},{ar:"بَيْنَ الْفِتْيَةِ وَالْيَافِعِينَ",uz:"yigitlar va o‘smirlar orasida"}],full_uz:"Va o‘z qarashlarini yigitlar hamda o‘smirlar orasida.",note:"آرَاءٌ — رَأْيٌ («fikr»)ning ko‘pligi. يَافِعٌ — o‘smirlik yoshidagi kishi."},
{num:378,time:"00:34:56,539 --> 00:34:59,980",arabic:"وَلَا سِيَّمَا طُلَّابِ الْفِقْهِ وَالْحَدِيثِ.",segs:[{ar:"وَلَا سِيَّمَا",uz:"ayniqsa"},{ar:"طُلَّابِ الْفِقْهِ وَالْحَدِيثِ",uz:"fiqh va hadis talabalarining"}],full_uz:"Ayniqsa fiqh va hadis talabalari orasida.",note:null},
{num:379,time:"00:34:59,980 --> 00:35:01,619",arabic:"أَعْدَاءُ اللَّهِ!",segs:null,full_uz:"Allohning dushmanlari!",note:null},
{num:380,time:"00:35:01,619 --> 00:35:04,679",arabic:"يَنْشُرُونَ الْبِدَعَ وَالضَّلَالَ.",segs:[{ar:"يَنْشُرُونَ",uz:"tarqatmoqdalar"},{ar:"الْبِدَعَ وَالضَّلَالَ",uz:"bid’atlar va adashishni"}],full_uz:"Bid’atlar va adashishni tarqatmoqdalar.",note:"بِدَعٌ — بِدْعَةٌ so‘zining ko‘pligi."},
{num:381,time:"00:35:04,679 --> 00:35:09,139",arabic:"كَمْ مِنَ الْمَكَائِدِ تُحَاكُ لِهَذَا الدِّينِ وَأَهْلِهِ يَا ابْنَ الرَّبِيعِ!",segs:[{ar:"كَمْ مِنَ الْمَكَائِدِ تُحَاكُ",uz:"qanchadan qancha fitnalar to‘qilmoqda"},{ar:"لِهَذَا الدِّينِ وَأَهْلِهِ",uz:"bu din va uning ahliga qarshi"},{ar:"يَا ابْنَ الرَّبِيعِ",uz:"ey Ibn Rabi’"}],full_uz:"Bu din va uning ahliga qarshi qanchadan qancha fitnalar to‘qilmoqda, Ibn Rabi’!",note:"كَمْ مِنْ bu yerda ko‘plik va hayratni bildiradi. تُحَاكُ — «to‘qilmoqda», majhul nisbat."},
{num:382,time:"00:35:09,139 --> 00:35:10,820",arabic:"كَمْ؟",segs:null,full_uz:"Qancha?",note:null},
{num:383,time:"00:35:10,820 --> 00:35:11,400",arabic:"وَاللَّهِ!",segs:null,full_uz:"Allohga qasam!",note:null},
{num:384,time:"00:35:11,400 --> 00:35:17,780",arabic:"وَاللَّهِ لَأَقْطَعَنَّ دَابِرَ كُلِّ مَنْ أَفْسَدَ عَلَى النَّاسِ عَقِيدَتَهُمْ وَدِينَهُمْ.",segs:[{ar:"وَاللَّهِ",uz:"Allohga qasam"},{ar:"لَأَقْطَعَنَّ دَابِرَ",uz:"albatta, ildizini quritaman"},{ar:"كُلِّ مَنْ أَفْسَدَ عَلَى النَّاسِ",uz:"odamlarga buzib bergan har bir kishining"},{ar:"عَقِيدَتَهُمْ وَدِينَهُمْ",uz:"ularning aqidasi va dinini"}],full_uz:"Allohga qasam, odamlarning aqidasi va dinini buzgan har bir kishining ildizini quritaman.",note:"قَطَعَ دَابِرَهُ — «ildizini quritdi». لَـ va نَّ qasam javobida kuchli ta’kid hosil qiladi."},
{num:385,time:"00:35:17,780 --> 00:35:20,960",arabic:"إِلَّا كَلَامَ اللَّهِ يَا ابْنَ الرَّبِيعِ!",segs:[{ar:"إِلَّا كَلَامَ اللَّهِ",uz:"Allohning kalomiga esa tegishmasin"},{ar:"يَا ابْنَ الرَّبِيعِ",uz:"ey Ibn Rabi’"}],full_uz:"Allohning kalomiga esa tegishmasin, Ibn Rabi’!",note:"إِلَّا كَلَامَ اللَّهِ bu yerda keskin ogohlantirish bo‘lib, to‘liq aytilmagan gapning ma’nosi kontekstdan anglashiladi."},
{num:386,time:"00:35:22,300 --> 00:35:24,599",arabic:"لَقَدْ أَخَذْنَا حِذْرَنَا يَا مَوْلَايَ.",segs:[{ar:"لَقَدْ أَخَذْنَا حِذْرَنَا",uz:"ehtiyot choralarini ko‘rdik"},{ar:"يَا مَوْلَايَ",uz:"ey hukmdorim"}],full_uz:"Ehtiyot choralarini ko‘rdik, hukmdorim.",note:"أَخَذَ حِذْرَهُ — «ehtiyotini qildi, ehtiyot choralarini ko‘rdi»."},
{num:387,time:"00:35:24,599 --> 00:35:28,519",arabic:"وَنَنْتَظِرُ أَمْرَ أَمِيرِ الْمُؤْمِنِينَ لِلْقَبْضِ عَلَيْهِمْ.",segs:[{ar:"وَنَنْتَظِرُ",uz:"va kutmoqdamiz"},{ar:"أَمْرَ أَمِيرِ الْمُؤْمِنِينَ",uz:"mo‘minlar amirining buyrug‘ini"},{ar:"لِلْقَبْضِ عَلَيْهِمْ",uz:"ularni hibsga olish uchun"}],full_uz:"Ularni hibsga olish uchun mo‘minlar amirining buyrug‘ini kutmoqdamiz.",note:"قَبَضَ عَلَى شَخْصٍ — «bir kishini qo‘lga oldi, hibsga oldi»."},
{num:388,time:"00:35:28,519 --> 00:35:30,559",arabic:"أَعِدَّ لَهُمُ الْعُدَّةَ يَا ابْنَ الرَّبِيعِ.",segs:[{ar:"أَعِدَّ لَهُمُ الْعُدَّةَ",uz:"ularga qarshi tayyorgarlik ko‘ring"},{ar:"يَا ابْنَ الرَّبِيعِ",uz:"ey Ibn Rabi’"}],full_uz:"Ularga qarshi tayyorgarlik ko‘ring, Ibn Rabi’.",note:"أَعَدَّ الْعُدَّةَ — «kerakli tayyorgarlikni ko‘rdi». أَعِدَّ — buyruq shakli."},
{num:389,time:"00:35:30,559 --> 00:35:35,039",arabic:"أَعِدَّ لَهُمُ الْعُدَّةَ، وَلَا يَفْلِتَنَّ أَحَدٌ مِنْ قَبْضَتِكُمْ.",segs:[{ar:"أَعِدَّ لَهُمُ الْعُدَّةَ",uz:"ularga qarshi tayyorgarlik ko‘ring"},{ar:"وَلَا يَفْلِتَنَّ أَحَدٌ",uz:"hech kim aslo qochib qutulmasin"},{ar:"مِنْ قَبْضَتِكُمْ",uz:"qo‘lingizdan"}],full_uz:"Ularga qarshi tayyorgarlik ko‘ring, hech kim qo‘lingizdan aslo qochib qutulmasin.",note:"أَفْلَتَ — يُفْلِتُ — «qochib qutulmoq». Taqiqdagi نَّ buyruqni qat’iylashtiradi."},
{num:390,time:"00:35:35,039 --> 00:35:37,480",arabic:"الْمُعْتَزِلَةُ!",segs:null,full_uz:"Mu’tazila!",note:null},
{num:391,time:"00:35:37,480 --> 00:35:40,860",arabic:"الْمُعْتَزِلَةُ يَا ابْنَ الرَّبِيعِ!",segs:[{ar:"الْمُعْتَزِلَةُ",uz:"mu’tazila"},{ar:"يَا ابْنَ الرَّبِيعِ",uz:"ey Ibn Rabi’"}],full_uz:"Mu’tazila, Ibn Rabi’!",note:null},
{num:392,time:"00:35:41,620 --> 00:35:42,820",arabic:"أَمْرُكَ مَوْلَايَ.",segs:[{ar:"أَمْرُكَ",uz:"buyrug‘ingiz bosh ustiga"},{ar:"مَوْلَايَ",uz:"hukmdorim"}],full_uz:"Buyrug‘ingiz bosh ustiga, hukmdorim.",note:"أَمْرُكَ — buyruqqa itoatni bildiruvchi qisqa javob."},
{num:393,time:"00:35:42,820 --> 00:35:50,820",arabic:"هَؤُلَاءِ الْمَخْذُولُونَ...",segs:null,full_uz:"Bu yordamsiz qoldirilganlar...",note:"مَخْذُولٌ — «yordamsiz qoldirilgan, qo‘llab-quvvatlanmagan». Bu yerda qoralash ma’nosida ishlatilgan."},
{num:394,time:"00:35:50,820 --> 00:35:57,860",arabic:"تَرَكُوا الْبَيِّنَ الْمُحْكَمَ وَأَخَذُوا الْمُتَشَابِهَ وَالْمُخْتَلَفَ فِيهِ.",segs:[{ar:"تَرَكُوا الْبَيِّنَ الْمُحْكَمَ",uz:"ravshan va aniq narsani tark etdilar"},{ar:"وَأَخَذُوا الْمُتَشَابِهَ",uz:"va ma’nosi bir qarashda aniq bo‘lmaganini oldilar"},{ar:"وَالْمُخْتَلَفَ فِيهِ",uz:"hamda bahsli narsani"}],full_uz:"Ravshan va aniq narsani tark etib, ma’nosi bir qarashda aniq bo‘lmagan hamda bahsli narsani oldilar.",note:"الْمُحْكَمُ — ma’nosi aniq; الْمُتَشَابِهُ — ma’nosini aniqlash izoh talab qiladigan. الْمُخْتَلَفُ فِيهِ — «ustida ixtilof bor narsa»."},
{num:395,time:"00:35:57,860 --> 00:36:03,860",arabic:"وَاللَّهِ مَا أَضَلَّ النَّاسَ إِلَّا الْهَوَى بِغَيْرِ عِلْمٍ.",segs:[{ar:"وَاللَّهِ",uz:"Allohga qasam"},{ar:"مَا أَضَلَّ النَّاسَ إِلَّا الْهَوَى",uz:"odamlarni faqat havoyi nafs adashtirdi"},{ar:"بِغَيْرِ عِلْمٍ",uz:"ilmsiz ravishda"}],full_uz:"Allohga qasam, odamlarni ilmsiz ravishda havoyi nafsga ergashishgina adashtirdi.",note:"أَضَلَّ — «adashtirdi»; ضَلَّ — «adashdi». الْهَوَى bu yerda «havoyi nafs, asossiz mayl»."},
{num:396,time:"00:36:16,860 --> 00:36:30,420",arabic:"بَدْرُ، اُدْخُلْ.",segs:[{ar:"بَدْرُ",uz:"Badr"},{ar:"اُدْخُلْ",uz:"kiring"}],full_uz:"Badr, kiring.",note:null},
{num:397,time:"00:36:40,860 --> 00:36:44,860",arabic:"بَدْرُ، مَا بِكَ؟ لِمَ كُلُّ هَذَا الرُّعْبِ؟",segs:[{ar:"بَدْرُ، مَا بِكَ؟",uz:"Badr, sizga nima bo‘ldi?"},{ar:"لِمَ كُلُّ هَذَا الرُّعْبِ؟",uz:"nega buncha qo‘rquv?"}],full_uz:"Badr, sizga nima bo‘ldi? Nega buncha qo‘rquv?",note:"رُعْبٌ — «qattiq qo‘rquv, dahshat». لِمَ — «nega?»."},
{num:398,time:"00:36:45,860 --> 00:36:51,860",arabic:"زَبَانِيَةُ هَارُونَ الرَّشِيدِ فِي أَعْقَابِنَا، النَّجَاةَ يَا شَيْخُ!",segs:[{ar:"زَبَانِيَةُ هَارُونَ الرَّشِيدِ",uz:"Horun Rashidning zolim malaylari"},{ar:"فِي أَعْقَابِنَا",uz:"izimizdan kelmoqda"},{ar:"النَّجَاةَ يَا شَيْخُ",uz:"qutulish kerak, ey shayx"}],full_uz:"Horun Rashidning zolim malaylari izimizdan kelmoqda. Qochib qutulish kerak, shayx!",note:"فِي أَعْقَابِنَا — «izimizda». النَّجَاةَ mansub shaklda shoshilinch undashni bildiradi."},
{num:399,time:"00:38:20,860 --> 00:38:21,860",arabic:"هَيَّا بِسُرْعَةٍ!",segs:null,full_uz:"Qani, tezroq!",note:null},
{num:400,time:"00:38:40,860 --> 00:38:51,940",arabic:"أَيُعْقَلُ أَنْ تَكُونَ هَذِهِ نِهَايَتَكَ يَا ابْنَ الْأَشْرَسِ؟",segs:[{ar:"أَيُعْقَلُ",uz:"aqlga sig‘adimi"},{ar:"أَنْ تَكُونَ هَذِهِ نِهَايَتَكَ",uz:"bu sizning oxiringiz bo‘lishi"},{ar:"يَا ابْنَ الْأَشْرَسِ؟",uz:"ey Ibn Ashras?"}],full_uz:"Oxiringiz shunday bo‘lishi aqlga sig‘adimi, Ibn Ashras?",note:null},
{num:401,time:"00:38:51,940 --> 00:38:55,420",arabic:"أَيُعْقَلُ؟",segs:null,full_uz:"Aqlga sig‘adimi?",note:null},
{num:402,time:"00:39:05,820 --> 00:39:09,000",arabic:"كَيْفَ اسْتَطَاعَ الْمَرِيسِيُّ أَنْ يَهْرُبَ مِنْكُمْ؟",segs:[{ar:"كَيْفَ اسْتَطَاعَ الْمَرِيسِيُّ",uz:"Marisiy qanday uddaladi"},{ar:"أَنْ يَهْرُبَ مِنْكُمْ؟",uz:"sizlardan qochishni?"}],full_uz:"Marisiy sizlardan qanday qochib qutula oldi?",note:null},
{num:403,time:"00:39:09,000 --> 00:39:11,639",arabic:"لَا أَدْرِي يَا مَوْلَايَ.",segs:[{ar:"لَا أَدْرِي",uz:"bilmayman"},{ar:"يَا مَوْلَايَ",uz:"ey hukmdorim"}],full_uz:"Bilmayman, hukmdorim.",note:null},
{num:404,time:"00:39:11,639 --> 00:39:14,420",arabic:"رُبَّمَا وَصَلَ إِلَيْهِ الْخَبَرُ قَبْلَ أَنْ نَصِلَ.",segs:[{ar:"رُبَّمَا وَصَلَ إِلَيْهِ الْخَبَرُ",uz:"balki unga xabar yetib borgandir"},{ar:"قَبْلَ أَنْ نَصِلَ",uz:"biz yetib borishimizdan oldin"}],full_uz:"Balki unga xabar biz yetib borishimizdan oldin yetgandir.",note:"قَبْلَ أَنْ + fe’l — «...ishidan oldin»."},
{num:405,time:"00:39:14,420 --> 00:39:22,639",arabic:"لَعَلَّ بَيْنَكُمْ عُيُونًا لِهَؤُلَاءِ الْمُفْسِدِينَ؟",segs:[{ar:"لَعَلَّ بَيْنَكُمْ عُيُونًا",uz:"balki orangizda josuslar bordir"},{ar:"لِهَؤُلَاءِ الْمُفْسِدِينَ؟",uz:"bu buzg‘unchilarning?"}],full_uz:"Balki orangizda bu buzg‘unchilarning josuslari bordir?",note:"عُيُونًا — لَعَلَّ ning keyinga kelgan ismi, shu sababli mansub. بَيْنَكُمْ — oldinga chiqqan xabar."},
{num:406,time:"00:39:22,639 --> 00:39:25,480",arabic:"لَيْسَ بَيْنَ جُنْدِنَا إِلَّا مَنْ يُخْلِصُ الْوَلَاءَ لِأَمِيرِ الْمُؤْمِنِينَ.",segs:[{ar:"لَيْسَ بَيْنَ جُنْدِنَا إِلَّا",uz:"askarlarimiz orasida faqat bor"},{ar:"مَنْ يُخْلِصُ الْوَلَاءَ",uz:"chin sadoqat ko‘rsatadiganlar"},{ar:"لِأَمِيرِ الْمُؤْمِنِينَ",uz:"mo‘minlar amiriga"}],full_uz:"Askarlarimiz orasida faqat mo‘minlar amiriga chin sadoqatli kishilar bor.",note:"أَخْلَصَ الْوَلَاءَ لِـ — «...ga chin dildan sodiq bo‘ldi»."},
{num:407,time:"00:39:25,480 --> 00:39:27,480",arabic:"كُنْ عَلَى ثِقَةٍ مِنْ ذَلِكَ يَا مَوْلَايَ.",segs:[{ar:"كُنْ عَلَى ثِقَةٍ مِنْ ذَلِكَ",uz:"bunga ishonchingiz komil bo‘lsin"},{ar:"يَا مَوْلَايَ",uz:"ey hukmdorim"}],full_uz:"Bunga ishonchingiz komil bo‘lsin, hukmdorim.",note:"عَلَى ثِقَةٍ مِنْ — «...ga ishonchi komil»."},
{num:408,time:"00:39:27,480 --> 00:39:31,480",arabic:"إِذَنْ كَيْفَ اسْتَطَاعَ أَنْ يُفْلِتَ مِنْكُمْ؟ كَيْفَ؟",segs:[{ar:"إِذَنْ كَيْفَ اسْتَطَاعَ",uz:"unda qanday uddaladi"},{ar:"أَنْ يُفْلِتَ مِنْكُمْ؟",uz:"qo‘lingizdan qochib qutulishni?"},{ar:"كَيْفَ؟",uz:"qanday?"}],full_uz:"Unda qo‘lingizdan qanday qochib qutula oldi? Qanday?",note:"أَفْلَتَ مِنْ — «...dan qochib qutuldi»."},
{num:409,time:"00:39:32,059 --> 00:39:34,679",arabic:"لَقَدْ فَرَّ قَبْلَ أَنْ يَصِلَ جُنْدُنَا إِلَيْهِ يَا مَوْلَايَ.",segs:[{ar:"لَقَدْ فَرَّ",uz:"u qochgan"},{ar:"قَبْلَ أَنْ يَصِلَ جُنْدُنَا إِلَيْهِ",uz:"askarlarimiz uning oldiga yetib borishidan oldin"},{ar:"يَا مَوْلَايَ",uz:"ey hukmdorim"}],full_uz:"Askarlarimiz uning oldiga yetib borishidan oldin qochgan, hukmdorim.",note:"فَرَّ — يَفِرُّ — «qochmoq»."},
{num:410,time:"00:39:34,679 --> 00:39:36,800",arabic:"فَبَيْتُهُ فِي أَطْرَافِ بَغْدَادَ.",segs:[{ar:"فَبَيْتُهُ",uz:"axir uning uyi"},{ar:"فِي أَطْرَافِ بَغْدَادَ",uz:"Bag‘dodning chekkasida"}],full_uz:"Axir uning uyi Bag‘dodning chekkasida.",note:"أَطْرَافٌ — طَرَفٌ («chet»)ning ko‘pligi; shahar bilan «chekka hududlar» ma’nosida."},
{num:411,time:"00:39:36,800 --> 00:39:39,820",arabic:"وَبَعْدَ أَنْ قَبَضْنَا عَلَى الْكَثِيرِ مِنْ رِجَالِهِ...",segs:[{ar:"وَبَعْدَ أَنْ قَبَضْنَا",uz:"qo‘lga olganimizdan keyin"},{ar:"عَلَى الْكَثِيرِ مِنْ رِجَالِهِ",uz:"uning ko‘p odamlarini"}],full_uz:"Uning ko‘p odamlarini qo‘lga olganimizdan keyin...",note:null},
{num:412,time:"00:39:39,820 --> 00:39:43,060",arabic:"وَصَلَ إِلَيْهِ أَحَدُهُمْ لِيُبَلِّغَهُ بِالْهُرُوبِ.",segs:[{ar:"وَصَلَ إِلَيْهِ أَحَدُهُمْ",uz:"ulardan biri uning oldiga yetib borgan"},{ar:"لِيُبَلِّغَهُ بِالْهُرُوبِ",uz:"qochish kerakligini bildirish uchun"}],full_uz:"Ulardan biri qochish kerakligini bildirish uchun uning oldiga yetib borgan.",note:"بَلَّغَ — «yetkazdi, xabar berdi». لِيُبَلِّغَهُ — «unga xabar berish uchun»."},
{num:413,time:"00:39:43,060 --> 00:39:44,480",arabic:"بَعْدَ أَنْ رَأَى مَا رَأَى.",segs:[{ar:"بَعْدَ أَنْ رَأَى",uz:"ko‘rganidan keyin"},{ar:"مَا رَأَى",uz:"ko‘rgan voqealarini"}],full_uz:"Bo‘lgan voqealarni ko‘rganidan keyin.",note:"رَأَى مَا رَأَى kabi takroriy qurilish tafsilotini aytmasdan, ma’lum voqealarga ishora qiladi."},
{num:414,time:"00:39:44,480 --> 00:39:46,460",arabic:"هَذَا تَفْسِيرٌ مُحْتَمَلٌ يَا مَوْلَايَ.",segs:[{ar:"هَذَا تَفْسِيرٌ مُحْتَمَلٌ",uz:"bu ehtimoliy izoh"},{ar:"يَا مَوْلَايَ",uz:"ey hukmdorim"}],full_uz:"Bu ehtimoliy izoh, hukmdorim.",note:"مُحْتَمَلٌ — «ehtimoliy, bo‘lishi mumkin bo‘lgan»."},
{num:415,time:"00:39:46,460 --> 00:39:49,500",arabic:"سَنَتَعَقَّبُ الْفَارِّينَ مِنْهُمْ فَلَا تَقْلَقْ.",segs:[{ar:"سَنَتَعَقَّبُ الْفَارِّينَ مِنْهُمْ",uz:"ular orasidan qochganlarni ta’qib qilamiz"},{ar:"فَلَا تَقْلَقْ",uz:"shuning uchun xavotir olmang"}],full_uz:"Ular orasidan qochganlarni ta’qib qilamiz, xavotir olmang.",note:"تَعَقَّبَ — «izidan bordi, ta’qib qildi». فَارٌّ — «qochayotgan yoki qochgan kishi»."},
{num:416,time:"00:40:00,860 --> 00:40:04,140",arabic:"لَيْتَهُمْ قَبَضُوا عَلَى ذَلِكَ الثَّعْلَبِ الْمَاكِرِ ابْنِ أَبِي دُؤَادٍ.",segs:[{ar:"لَيْتَهُمْ قَبَضُوا",uz:"qaniydi qo‘lga olishganida"},{ar:"عَلَى ذَلِكَ الثَّعْلَبِ الْمَاكِرِ",uz:"o‘sha makkor tulkini"},{ar:"ابْنِ أَبِي دُؤَادٍ",uz:"Ibn Abu Duodni"}],full_uz:"Qaniydi o‘sha makkor tulki Ibn Abu Duodni qo‘lga olishganida.",note:"لَيْتَهُمْ — «qaniydi ular». الثَّعْلَبُ الْمَاكِرُ — «makkor tulki», odamga ko‘chma ma’noda aytilgan."},
{num:417,time:"00:40:04,139 --> 00:40:07,199",arabic:"فَقَدْ سَمِعْتُ أَنَّ أَحَدًا لَمْ يَقْتَرِبْ مِنْهُ.",segs:[{ar:"فَقَدْ سَمِعْتُ",uz:"chunki eshitdim"},{ar:"أَنَّ أَحَدًا لَمْ يَقْتَرِبْ مِنْهُ",uz:"uning oldiga hech kim yaqinlashmaganini"}],full_uz:"Chunki uning oldiga hech kim yaqinlashmaganini eshitdim.",note:null},
{num:418,time:"00:40:07,199 --> 00:40:11,159",arabic:"ابْنُ أَبِي دُؤَادٍ وَأَمْثَالُهُ لَيْسُوا كَالْمَرِيسِيِّ وَجَمَاعَتِهِ.",segs:[{ar:"ابْنُ أَبِي دُؤَادٍ وَأَمْثَالُهُ",uz:"Ibn Abu Duod va unga o‘xshaganlar"},{ar:"لَيْسُوا كَالْمَرِيسِيِّ وَجَمَاعَتِهِ",uz:"Marisiy va uning jamoasi kabi emaslar"}],full_uz:"Ibn Abu Duod va unga o‘xshaganlar Marisiy hamda uning jamoasi kabi emaslar.",note:null},
{num:419,time:"00:40:11,159 --> 00:40:15,139",arabic:"كَيْفَ؟ أَلَيْسُوا جَمِيعًا مُبْتَدِعَةً وَمَنْهَجُهُمْ وَاحِدٌ؟",segs:[{ar:"كَيْفَ؟",uz:"qanday qilib?"},{ar:"أَلَيْسُوا جَمِيعًا مُبْتَدِعَةً",uz:"ularning hammasi bid’atchi emasmi"},{ar:"وَمَنْهَجُهُمْ وَاحِدٌ؟",uz:"va yo‘llari bir emasmi?"}],full_uz:"Qanday qilib? Ularning hammasi bid’atchi, yo‘llari esa bir emasmi?",note:"مَنْهَجٌ — «yo‘l, usul, yondashuv». مُبْتَدِعَةٌ bu yerda kishilar guruhini bildiruvchi ko‘plik."},
{num:420,time:"00:40:16,739 --> 00:40:19,139",arabic:"لَيْسَ كُلُّ مَنْ وَقَعَ فِي بِدْعَةٍ يَصِيرُ مُبْتَدِعًا.",segs:[{ar:"لَيْسَ كُلُّ مَنْ وَقَعَ فِي بِدْعَةٍ",uz:"bid’atga yo‘l qo‘ygan har bir kishi ham emas"},{ar:"يَصِيرُ مُبْتَدِعًا",uz:"bid’atchiga aylanadigan"}],full_uz:"Bid’atga yo‘l qo‘ygan har bir kishi ham bid’atchiga aylanavermaydi.",note:"لَيْسَ كُلُّ... — «har bir ... ham emas». Bu barcha kishilarni emas, umumlashtirishni inkor qiladi."},
{num:421,time:"00:40:20,119 --> 00:40:22,339",arabic:"وَلَيْسَ مَنْ جَاهَرَ بِالْبِدْعَةِ كَمَنْ كَتَمَهَا.",segs:[{ar:"وَلَيْسَ مَنْ جَاهَرَ بِالْبِدْعَةِ",uz:"bid’atini oshkor qilgan kishi emas"},{ar:"كَمَنْ كَتَمَهَا",uz:"uni yashirgan kishi kabi"}],full_uz:"Bid’atini oshkor qilgan kishi uni yashirgan kishi kabi emas.",note:"جَاهَرَ بِـ — «oshkor qildi»; كَتَمَ — «yashirdi»."},
{num:422,time:"00:40:22,339 --> 00:40:26,500",arabic:"ابْنُ أَبِي دُؤَادٍ وَآخَرُونَ مِنَ الْمُعْتَزِلَةِ يَكْتُمُونَ عَقَائِدَهُمْ.",segs:[{ar:"ابْنُ أَبِي دُؤَادٍ وَآخَرُونَ",uz:"Ibn Abu Duod va boshqalar"},{ar:"مِنَ الْمُعْتَزِلَةِ",uz:"mu’taziladan bo‘lgan"},{ar:"يَكْتُمُونَ عَقَائِدَهُمْ",uz:"o‘z aqidalarini yashiradilar"}],full_uz:"Ibn Abu Duod va mu’taziladan bo‘lgan boshqalar o‘z aqidalarini yashiradilar.",note:"عَقَائِدُ — عَقِيدَةٌ so‘zining ko‘pligi."},
{num:423,time:"00:40:26,500 --> 00:40:30,019",arabic:"لَا كَالْمَرِيسِيِّ وَجَمَاعَتِهِ، يُجَاهِرُونَ بِهَا.",segs:[{ar:"لَا كَالْمَرِيسِيِّ وَجَمَاعَتِهِ",uz:"Marisiy va uning jamoasi kabi emas"},{ar:"يُجَاهِرُونَ بِهَا",uz:"ular buni oshkor qiladilar"}],full_uz:"Marisiy va uning jamoasi kabi emas: ular aqidalarini oshkor qiladilar.",note:null},
{num:424,time:"00:40:30,019 --> 00:40:32,239",arabic:"بَلْ وَيَعْمَلُونَ عَلَى بَثِّهَا بَيْنَ النَّاسِ.",segs:[{ar:"بَلْ وَيَعْمَلُونَ عَلَى بَثِّهَا",uz:"balki uni yoyishga ham harakat qiladilar"},{ar:"بَيْنَ النَّاسِ",uz:"odamlar orasida"}],full_uz:"Balki uni odamlar orasida yoyishga ham harakat qiladilar.",note:"عَمِلَ عَلَى + masdar — «...ga harakat qildi». بَثٌّ — «tarqatish, yoyish»."},
{num:425,time:"00:40:32,239 --> 00:40:36,419",arabic:"الْحَمْدُ لِلَّهِ الَّذِي أَرَاحَنَا مِنْهُمْ جَمِيعًا.",segs:[{ar:"الْحَمْدُ لِلَّهِ",uz:"Allohga hamd bo‘lsin"},{ar:"الَّذِي أَرَاحَنَا مِنْهُمْ جَمِيعًا",uz:"bizni ularning barchasidan xalos qilgan"}],full_uz:"Bizni ularning barchasidan xalos qilgan Allohga hamd bo‘lsin.",note:"أَرَاحَهُ مِنْ — «uni ...dan xalos qilib, tinch qo‘ydi»."},
{num:426,time:"00:40:36,419 --> 00:40:40,179",arabic:"أَمَّا أَنَا يَا أَبَا زَكَرِيَّا فَأَرْجُو لِأَمْثَالِهِمُ الْهِدَايَةَ.",segs:[{ar:"أَمَّا أَنَا",uz:"menga kelsak"},{ar:"يَا أَبَا زَكَرِيَّا",uz:"ey Abu Zakariyo"},{ar:"فَأَرْجُو لِأَمْثَالِهِمُ الْهِدَايَةَ",uz:"ularga o‘xshaganlarga hidoyat tilayman"}],full_uz:"Menga kelsak, Abu Zakariyo, ularga o‘xshaganlarga hidoyat tilayman.",note:"أَمَّا ... فَـ ... — «...ga kelsak, ...». أَرْجُو لَهُ — «unga tilayman, u uchun umid qilaman»."},
{num:427,time:"00:40:40,179 --> 00:40:43,799",arabic:"إِنْ عَادَ هَؤُلَاءِ إِلَى رُشْدِهِمْ نَالَنَا خَيْرُهُمْ.",segs:[{ar:"إِنْ عَادَ هَؤُلَاءِ إِلَى رُشْدِهِمْ",uz:"agar ular to‘g‘ri yo‘lga qaytsalar"},{ar:"نَالَنَا خَيْرُهُمْ",uz:"ularning yaxshiligi bizga ham yetadi"}],full_uz:"Agar ular to‘g‘ri yo‘lga qaytsalar, ularning yaxshiligi bizga ham yetadi.",note:"عَادَ إِلَى رُشْدِهِ — «aqlini yig‘di, to‘g‘ri yo‘lga qaytdi». نَالَنَا — «bizga yetdi»."},
{num:428,time:"00:40:43,799 --> 00:40:46,239",arabic:"فَادْعُ لَهُمْ بِالْهِدَايَةِ يَا ابْنَ مَعِينٍ.",segs:[{ar:"فَادْعُ لَهُمْ بِالْهِدَايَةِ",uz:"ularga hidoyat so‘rab duo qiling"},{ar:"يَا ابْنَ مَعِينٍ",uz:"ey Ibn Ma’in"}],full_uz:"Ularga hidoyat so‘rab duo qiling, Ibn Ma’in.",note:"اُدْعُ — دَعَا fe’lining birlikdagi buyrug‘i; oxirgi illat harfi tushadi."},
{num:429,time:"00:40:46,239 --> 00:40:50,000",arabic:"دَعُونَا الْآنَ مِنْ سِيرَةِ هَؤُلَاءِ الْمُبْتَدِعَةِ.",segs:[{ar:"دَعُونَا الْآنَ",uz:"endi qo‘yaylik"},{ar:"مِنْ سِيرَةِ هَؤُلَاءِ الْمُبْتَدِعَةِ",uz:"bu bid’atchilar haqidagi gapni"}],full_uz:"Endi bu bid’atchilar haqidagi gapni qo‘yaylik.",note:"دَعُونَا مِنْ... — «...ni qo‘yaylik». سِيرَةٌ bu yerda «biror kishi haqidagi gap-so‘z»."},
{num:430,time:"00:40:50,000 --> 00:40:54,239",arabic:"وَأَخْبِرُونَا مَتَى نَوَيْتُمُ الْخُرُوجَ إِلَى مَهْدِ الْعِلْمِ وَالْوَحْيِ؟",segs:[{ar:"وَأَخْبِرُونَا",uz:"bizga aytinglar"},{ar:"مَتَى نَوَيْتُمُ الْخُرُوجَ",uz:"qachon yo‘lga chiqishni niyat qildingizlar"},{ar:"إِلَى مَهْدِ الْعِلْمِ وَالْوَحْيِ؟",uz:"ilm va vahiy beshigiga?"}],full_uz:"Bizga aytinglar, ilm va vahiy beshigiga qachon yo‘lga chiqishni niyat qildingizlar?",note:"مَهْدٌ — «beshik»; ko‘chma ma’noda biror narsa paydo bo‘lgan yoki rivojlangan joy."},
{num:431,time:"00:40:54,939 --> 00:40:57,399",arabic:"ثَمَّ قَافِلَةٌ سَتَخْرُجُ إِلَى الْحَجِّ بَعْدَ غَدٍ.",segs:[{ar:"ثَمَّ قَافِلَةٌ",uz:"bir karvon bor"},{ar:"سَتَخْرُجُ إِلَى الْحَجِّ",uz:"hajga yo‘lga chiqadigan"},{ar:"بَعْدَ غَدٍ",uz:"indinga"}],full_uz:"Indinga hajga yo‘lga chiqadigan bir karvon bor.",note:"ثَمَّ — «bor, u yerda»; ثُمَّ esa «so‘ng». بَعْدَ غَدٍ — «indinga»."},
{num:432,time:"00:40:57,399 --> 00:40:59,979",arabic:"إِنْ رَأَيْتُمْ أَنْ نَخْرُجَ مَعَهُمْ.",segs:[{ar:"إِنْ رَأَيْتُمْ",uz:"agar ma’qul ko‘rsangizlar"},{ar:"أَنْ نَخْرُجَ مَعَهُمْ",uz:"ular bilan yo‘lga chiqishimizni"}],full_uz:"Ma’qul ko‘rsangizlar, ular bilan yo‘lga chiqamiz.",note:"رَأَيْتُمْ bu yerda «ko‘rdingizlar» emas, «ma’qul deb bildingizlar» ma’nosida."},
{num:433,time:"00:40:59,979 --> 00:41:02,199",arabic:"مَا رَأْيُكَ يَا أَبَا عَبْدِ اللَّهِ؟",segs:[{ar:"مَا رَأْيُكَ",uz:"fikringiz qanday"},{ar:"يَا أَبَا عَبْدِ اللَّهِ؟",uz:"ey Abu Abdulloh?"}],full_uz:"Fikringiz qanday, Abu Abdulloh?",note:null},
{num:434,time:"00:41:02,199 --> 00:41:04,480",arabic:"عَلَى بَرَكَةِ اللَّهِ.",segs:null,full_uz:"Allohning barakasi bilan.",note:"Bir ishni boshlashga rozilik bildirganda ham ishlatiladi: «Allohning barakasi bilan boshlaylik»."},
{num:435,time:"00:41:04,480 --> 00:41:13,879",arabic:"تَعْسًا لَنَا، نَلْتَهِي بِسَفَاسِفِ الْخَبَرِ.",segs:[{ar:"تَعْسًا لَنَا",uz:"holimizga voy"},{ar:"نَلْتَهِي بِسَفَاسِفِ الْخَبَرِ",uz:"arzimas xabarlar bilan ovora bo‘lamiz"}],full_uz:"Holimizga voy, arzimas xabarlar bilan ovora bo‘lamiz.",note:"سَفَاسِفُ — «arzimas, past narsalar». اِلْتَهَى بِـ — «...bilan ovora bo‘lib qoldi»."},
{num:436,time:"00:41:13,879 --> 00:41:16,059",arabic:"وَغَيْرُنَا فَازَ بِحِصَّةِ الْأَسَدِ.",segs:[{ar:"وَغَيْرُنَا فَازَ",uz:"boshqalar esa qo‘lga kiritdi"},{ar:"بِحِصَّةِ الْأَسَدِ",uz:"eng katta ulushni"}],full_uz:"Boshqalar esa eng katta ulushni qo‘lga kiritdi.",note:"حِصَّةُ الْأَسَدِ — so‘zma-so‘z «sherning ulushi», ya’ni eng katta ulush."},
{num:437,time:"00:41:16,059 --> 00:41:17,699",arabic:"تَقْصِدُ الْمُعْتَزِلَةَ؟",segs:null,full_uz:"Mu’tazilani nazarda tutyapsizmi?",note:null},
{num:438,time:"00:41:17,699 --> 00:41:29,199",arabic:"وَهَلْ ثَمَّ خَبَرٌ الْيَوْمَ فِي بَغْدَادَ سِوَاهُ؟",segs:[{ar:"وَهَلْ ثَمَّ خَبَرٌ",uz:"yana biror xabar bormi"},{ar:"الْيَوْمَ فِي بَغْدَادَ",uz:"bugun Bag‘dodda"},{ar:"سِوَاهُ؟",uz:"undan boshqa?"}],full_uz:"Bugun Bag‘dodda undan boshqa xabar bormi?",note:"سِوَاهُ — «undan boshqa». ثَمَّ mavjudlikni bildiradi."},
{num:439,time:"00:41:29,199 --> 00:41:31,960",arabic:"إِنَّ صَاحِبَ خَبَرِ الْمُعْتَزِلَةِ...",segs:[{ar:"إِنَّ صَاحِبَ الْخَبَرِ",uz:"albatta, xabarni yetkazgan kishi"},{ar:"خَبَرِ الْمُعْتَزِلَةِ",uz:"mu’tazila haqidagi xabarni"}],full_uz:"Mu’tazila haqidagi xabarni yetkazgan kishi...",note:"صَاحِبُ الْخَبَرِ bu kontekstda xabarni topgan yoki yetkazgan kishini bildiradi."},
{num:440,time:"00:41:31,960 --> 00:41:35,339",arabic:"لَا بُدَّ أَنَّهُ سَيَنَالُ مِنَ الْمُكَافَآتِ مَا لَمْ يَحْلُمْ بِهِ.",segs:[{ar:"لَا بُدَّ أَنَّهُ سَيَنَالُ",uz:"shubhasiz, u oladi"},{ar:"مِنَ الْمُكَافَآتِ",uz:"mukofotlardan"},{ar:"مَا لَمْ يَحْلُمْ بِهِ",uz:"hatto orzu qilmaganini"}],full_uz:"Shubhasiz, u hatto orzu qilmagan mukofotlarini oladi.",note:"لَا بُدَّ أَنَّهُ... — «shubhasiz, u...». نَالَ — يَنَالُ — «erishmoq, olmoq»."},
{num:441,time:"00:41:35,339 --> 00:41:37,199",arabic:"هَذِهِ أَخْبَارٌ.",segs:null,full_uz:"Mana buni xabar desa bo‘ladi.",note:null},
{num:442,time:"00:41:37,199 --> 00:41:40,480",arabic:"لَا أَخْبَارُكَ أَنْتَ الَّتِي لَا قِيمَةَ لَهَا.",segs:[{ar:"لَا أَخْبَارُكَ أَنْتَ",uz:"sizning xabarlaringiz emas"},{ar:"الَّتِي لَا قِيمَةَ لَهَا",uz:"hech qanday qiymati yo‘q"}],full_uz:"Sizning hech qanday qiymati yo‘q xabarlaringiz emas.",note:"أَنْتَ bu yerda ta’kid uchun kelgan: «aynan sizning»."},
{num:443,time:"00:41:40,480 --> 00:41:43,639",arabic:"وَمَاذَا أَفْعَلُ يَا مُعَلِّمِي؟",segs:[{ar:"وَمَاذَا أَفْعَلُ",uz:"men nima qilay"},{ar:"يَا مُعَلِّمِي؟",uz:"ey ustozim?"}],full_uz:"Men nima qilay, ustozim?",note:null},
{num:444,time:"00:41:43,639 --> 00:41:44,859",arabic:"أَخْتَرِعُ أَخْبَارًا مِنْ عِنْدِي؟",segs:[{ar:"أَخْتَرِعُ أَخْبَارًا",uz:"xabarlar to‘qib chiqaraymi"},{ar:"مِنْ عِنْدِي؟",uz:"o‘zimdan?"}],full_uz:"O‘zimdan xabarlar to‘qib chiqaraymi?",note:"اِخْتَرَعَ bu yerda «uydirib chiqardi». مِنْ عِنْدِي — «o‘zimdan»."},
{num:445,time:"00:41:44,859 --> 00:41:45,980",arabic:"لَا، لَا تَخْتَرِعْ.",segs:[{ar:"لَا",uz:"yo‘q"},{ar:"لَا تَخْتَرِعْ",uz:"to‘qib chiqarmang"}],full_uz:"Yo‘q, to‘qib chiqarmang.",note:"Birinchi لَا — javob, ikkinchisi taqiq yuklamasi. Shuning uchun ular bir xil vazifada emas."},
{num:446,time:"00:41:45,980 --> 00:41:48,299",arabic:"لَوْ أَتْعَبْتَ نَفْسَكَ قَلِيلًا...",segs:[{ar:"لَوْ أَتْعَبْتَ نَفْسَكَ",uz:"agar o‘zingizni urintirganingizda"},{ar:"قَلِيلًا",uz:"biroz"}],full_uz:"Agar biroz harakat qilganingizda...",note:"أَتْعَبَ نَفْسَهُ — so‘zma-so‘z «o‘zini charchatdi»; bu yerda «harakat qildi, urindi»."},
{num:447,time:"00:41:48,299 --> 00:41:52,199",arabic:"لَحَصَلْنَا عَلَى خَبَرِ الْمُعْتَزِلَةِ قَبْلَ غَيْرِنَا.",segs:[{ar:"لَحَصَلْنَا عَلَى",uz:"qo‘lga kiritgan bo‘lardik"},{ar:"خَبَرِ الْمُعْتَزِلَةِ",uz:"mu’tazila haqidagi xabarni"},{ar:"قَبْلَ غَيْرِنَا",uz:"boshqalardan oldin"}],full_uz:"Mu’tazila haqidagi xabarni boshqalardan oldin qo‘lga kiritgan bo‘lardik.",note:"Oldingi banddagi لَوْ shartining javobi. حَصَلَ عَلَى — «qo‘lga kiritdi, ega bo‘ldi»."}
];

if (typeof module !== "undefined" && module.exports) {
    module.exports = lessons;
}
